// Erzeugt von tools/mk_glossar.js, nicht von Hand bearbeiten.
window.GLOSSAR = {
  "g-12-takt-blues": {"t":"12-Takt-Blues","d":"Der 12-Takt-Blues ist eine Akkordfolge aus zwölf Takten mit nur drei Akkorden, I7, IV7 und V7, in drei Zeilen zu je vier Takten. Er ist die Grundlage von Blues, frühem Rock ’n’ Roll und vielen Jazzstücken.","n":18,"h":"kap18-pop-progressionen.html#g-12-takt-blues","f":["12-Takt-Blues"]},
  "g-a-tempo": {"t":"a tempo","d":"a tempo ist eine Spielanweisung: nach einer Tempoveränderung zurück zum vorherigen Tempo.","n":4,"h":"kap04-takt.html#g-a-tempo","f":["a tempo"]},
  "g-aaba": {"t":"AABA-Form","d":"Die AABA-Form besteht aus vier Teilen zu je acht Takten, zusammen 32 Takte. Auf zwei A-Teile folgt eine kontrastierende Bridge (B), dann kehrt A zurück. Viele Jazzstandards haben diese Form.","n":42,"h":"kap42-songformen.html#g-aaba","f":["AABA-Form","AABA"]},
  "g-abphrasieren": {"t":"Abphrasieren","d":"Abphrasieren heißt, den letzten Ton einer Phrase etwas leiser und kürzer zu spielen, damit eine kleine Atempause entsteht.","n":10,"h":"kap10-vortrag.html#g-abphrasieren","f":["Abphrasieren","abphrasiert"]},
  "g-absolutes-gehoer": {"t":"absolutes Gehör","d":"Wer ein absolutes Gehör hat, kann einen einzelnen Ton benennen, ohne einen Vergleichston zu hören. Diese Fähigkeit ist selten.","n":49,"h":"kap49-nach-gehoer.html#g-absolutes-gehoer","f":["absolutes Gehör","absolute Gehör","absolutem Gehör","absoluten Gehör","absoluten Gehörs"]},
  "g-abspaltung": {"t":"Abspaltung","d":"Abspaltung heißt, nur einen Teil eines Motivs weiterzuverwenden, meist den Anfang oder das Ende. Die musikalischen Einheiten werden dadurch kürzer.","n":39,"h":"kap39-bausteine.html#g-abspaltung","f":["Abspaltung"]},
  "g-interleaving": {"t":"abwechselndes Üben","d":"Beim abwechselnden Üben (engl. interleaving) wechselst du häufig zwischen mehreren Stellen, etwa A, B, C, A, C, B. Jede Stelle wird gleich oft geübt, muss aber immer wieder neu abgerufen werden.","n":47,"h":"kap47-ueben.html#g-interleaving","f":["abwechselndes Üben","abwechselnden Üben","abwechselnde Üben","Interleaving"]},
  "g-accelerando": {"t":"accelerando","d":"accelerando (abgekürzt accel.) ist eine Spielanweisung: allmählich schneller werden.","n":4,"h":"kap04-takt.html#g-accelerando","f":["accelerando"]},
  "g-achtelnote": {"t":"Achtelnote","d":"Die Achtel (Achtelnote) dauert halb so lang wie eine Viertel. Einzeln trägt sie ein Fähnchen, mehrere Achtel verbindet man mit einem Balken.","n":3,"h":"kap03-rhythmus.html#g-achtelnote","f":["Achtel","Achteln","Achtelnote","Achtelnoten"]},
  "g-adagio": {"t":"Adagio","d":"Adagio (italienisch „gemächlich, mit Muße“) ist eine langsame Tempobezeichnung, ungefähr ♩ = 66–76.","n":4,"h":"kap04-takt.html#g-adagio","f":["Adagio"]},
  "g-agogik": {"t":"Agogik","d":"Agogik heißen kleine, bewusste Tempoabweichungen beim Gestalten einer Phrase, etwa ritardando, accelerando oder rubato.","n":10,"h":"kap10-vortrag.html#g-agogik","f":["Agogik","agogisch","agogische","agogischen"]},
  "g-akkord": {"t":"Akkord","d":"Ein Akkord ist ein Zusammenklang aus mindestens drei verschiedenen Tönen.","n":11,"h":"kap11-dreiklaenge.html#g-akkord","f":["Akkord","Akkorde","Akkords","Akkorden"]},
  "g-akkordfolge": {"t":"Akkordfolge","d":"Eine Akkordfolge (englisch chord progression) ist eine Reihe von Akkorden, die ein Stück oder einen Teil davon trägt.","n":18,"h":"kap18-pop-progressionen.html#g-akkordfolge","f":["Akkordfolge","Akkordfolgen"]},
  "g-akkordmelodie": {"t":"Akkordmelodie","d":"Eine Akkordmelodie ist ein Klaviersatz, bei dem die Melodie als oberster Ton liegt und jeder Melodieton mit einem eigenen Akkord harmonisiert wird.","n":29,"h":"kap29-voicings.html#g-akkordmelodie","f":["Akkordmelodie","Akkordmelodien"]},
  "g-akkordskala": {"t":"Akkordskala","d":"Eine Akkordskala ist die Tonleiter, die zu einem bestimmten Akkord passt. Sie füllt die Lücken zwischen den Akkordtönen mit Optionstönen und Avoid Notes, über Dm7 in C-Dur etwa D-Dorisch.","n":30,"h":"kap30-akkordskalen.html#g-akkordskala","f":["Akkordskala","Akkordskalen"]},
  "g-akkordsymbol": {"t":"Akkordsymbol","d":"Ein Akkordsymbol bezeichnet einen Akkord mit Buchstaben und Zusätzen, etwa C, Am7 oder C/E. Es nennt Grundton, Akkordtyp und eventuell den Basston und verwendet englische Tonnamen, B steht also für H.","n":17,"h":"kap17-leadsheets.html#g-akkordsymbol","f":["Akkordsymbol","Akkordsymbole","Akkordsymbolen"]},
  "g-akkordton": {"t":"Akkordton","d":"Akkordtöne sind die Töne des gerade klingenden Akkords. Über C-Dur sind das c, e und g.","n":19,"h":"kap19-nichtakkordtoene.html#g-akkordton","f":["Akkordton","Akkordtöne","Akkordtönen"]},
  "g-akustische-skala": {"t":"akustische Skala","d":"Die akustische Skala besteht aus den Teiltönen 8 bis 14 eines Tons, über c angenähert c, d, e, fis, g, a, b. Sie entspricht der Skala Lydisch ♭7.","n":27,"h":"kap27-optionstoene.html#g-akustische-skala","f":["akustische Skala","akustischen Skala"]},
  "g-akzent": {"t":"Akzent","d":"Ein Akzent (Zeichen: liegender Keil über der Note) heißt: diesen Ton betonen, also lauter spielen als seine Umgebung.","n":10,"h":"kap10-vortrag.html#g-akzent","f":["Akzent","Akzente","Akzenten"]},
  "g-akzentparallelen": {"t":"Akzentparallele","d":"Akzentparallelen sind Quinten oder Oktaven auf zwei aufeinanderfolgenden schweren Zeiten. Das Ohr verbindet sie über die Zwischennote hinweg und hört eine Parallele.","n":35,"h":"kap35-kontrapunkt-2.html#g-akzentparallelen","f":["Akzentparallele","Akzentparallelen"]},
  "g-alberti-bass": {"t":"Alberti-Bass","d":"Der Alberti-Bass bricht einen Akkord in enger Lage nach dem Muster tief, hoch, mitte, hoch, in C-Dur also c–g–e–g. Er war das Standardmuster der Wiener Klassik.","n":46,"h":"kap46-begleitmuster.html#g-alberti-bass","f":["Alberti-Bass","Alberti-Basses","Alberti-Bässe","Alberti-Bässen"]},
  "g-alla-breve": {"t":"alla breve","d":"Alla breve ist der 2/2-Takt, geschrieben als durchgestrichenes C (¢). Man zählt in Halben, also zwei Schläge pro Takt.","n":4,"h":"kap04-takt.html#g-alla-breve","f":["alla breve","Alla-breve-Takt"]},
  "g-allegretto": {"t":"Allegretto","d":"Allegretto (italienisch „etwas heiter“) ist eine Tempobezeichnung, etwas ruhiger als Allegro, ungefähr ♩ = 100–128.","n":4,"h":"kap04-takt.html#g-allegretto","f":["Allegretto"]},
  "g-allegro": {"t":"Allegro","d":"Allegro (italienisch „heiter, lebhaft“) ist eine Tempobezeichnung für ein lebhaftes, schnelles Tempo, ungefähr ♩ = 120–156.","n":4,"h":"kap04-takt.html#g-allegro","f":["Allegro"]},
  "g-alteration": {"t":"Alteration","d":"Alterationen sind chromatisch veränderte Optionstöne bei Dominantakkorden, nämlich ♭9, ♯9, ♯11 und ♭13. Jede liegt einen Halbton neben einem Ton des Zielakkords und wirkt wie ein zusätzlicher Leitton.","n":27,"h":"kap27-optionstoene.html#g-alteration","f":["Alteration","Alterationen"]},
  "g-alterierte-dominante": {"t":"alterierte Dominante","d":"Eine alterierte Dominante besteht aus Grundton, Terz und Septime und enthält statt 9, 13 und reiner Quinte nur Alterationen (♭9, ♯9, ♭5, ♭13). Man schreibt sie als G7alt.","n":31,"h":"kap31-tritonus-substitution.html#g-alterierte-dominante","f":["alterierte Dominante","alterierten Dominante","alterierte Dominanten","alterierten Dominanten"]},
  "g-alterierte-skala": {"t":"alterierte Skala","d":"Die alterierte Skala enthält Grundton, Terz und Septime einer Dominante sowie alle vier Alterationen, über G also g, as, b, h, des, es, f. Sie ist die siebte Stufe von melodisch Moll.","n":31,"h":"kap31-tritonus-substitution.html#g-alterierte-skala","f":["alterierte Skala","alterierten Skala"]},
  "g-altschluessel": {"t":"Altschlüssel","d":"Der Altschlüssel ist ein C-Schlüssel auf der dritten Linie. Das c' steht dann auf der Mittellinie. Die Bratsche liest in diesem Schlüssel.","n":2,"h":"kap02-notenschrift.html#g-altschluessel","f":["Altschlüssel","Altschlüssels"]},
  "g-andalusische-kadenz": {"t":"andalusische Kadenz","d":"Die andalusische Kadenz ist die Moll-Folge i–VII–VI–V, in a-Moll Am – G – F – E. Der Bass steigt stufenweise eine Quarte hinab, und die Dur-Dominante am Ende zieht zurück zur Tonika.","n":18,"h":"kap18-pop-progressionen.html#g-andalusische-kadenz","f":["andalusische Kadenz","andalusische Folge"]},
  "g-andante": {"t":"Andante","d":"Andante (italienisch „gehend“) ist eine ruhige, mittellangsame Tempobezeichnung, ungefähr ♩ = 76–108.","n":4,"h":"kap04-takt.html#g-andante","f":["Andante"]},
  "g-anhemitonisch": {"t":"anhemitonisch","d":"Anhemitonisch („ohne Halbton“) heißen Tonleitern, die keinen einzigen Halbtonschritt enthalten, etwa die Pentatonik.","n":9,"h":"kap09-weitere-skalen.html#g-anhemitonisch","f":["anhemitonisch","anhemitonische","anhemitonischen"]},
  "g-ankerpunkt": {"t":"Ankerpunkt","d":"Ankerpunkte sind ein oder zwei Stellen pro Phrase, an denen du sicher einsteigen kannst. Passiert beim Vorspielen ein Fehler, springst du zum nächsten Ankerpunkt und spielst weiter.","n":47,"h":"kap47-ueben.html#g-ankerpunkt","f":["Ankerpunkt","Ankerpunkte","Ankerpunkten"]},
  "g-anschlag": {"t":"Anschlag","d":"Anschlag nennt man das Niederdrücken einer Taste, durch das der Hammer die Saite trifft. Wie schnell die Taste sinkt, bestimmt die Lautstärke.","n":5,"h":"kap05-intervalle.html#g-anschlag","f":["Anschlägen","Anschlags","Anschläge","Anschlag"]},
  "g-antizipation": {"t":"Antizipation","d":"Eine Antizipation (Vorausnahme) ist ein Ton des kommenden Akkords, der schon kurz vor dem Akkordwechsel auf einer leichten Zählzeit erklingt. Mit dem neuen Akkord wird er wiederholt oder gehalten.","n":19,"h":"kap19-nichtakkordtoene.html#g-antizipation","f":["Antizipation","Vorausnahme"]},
  "g-comes": {"t":"Antwort (Fuge)","d":"Die Antwort (Comes) ist das Fugenthema in der Dominanttonart, meist eine Quinte höher oder eine Quarte tiefer. Sie folgt in einer anderen Stimme auf den ersten Themeneinsatz.","n":38,"h":"kap38-fuge.html#g-comes","f":["Comes"]},
  "g-aeolisch": {"t":"Äolisch","d":"Äolisch ist der Modus, der auf den weißen Tasten von a bis a' entsteht. Er ist identisch mit dem natürlichen Moll.","n":24,"h":"kap24-modi.html#g-aeolisch","f":["äolisch","äolische","äolischen"]},
  "g-appoggiatura": {"t":"Appoggiatura","d":"Die Appoggiatura (italienisch appoggiare, „anlehnen“) ist ein betonter Nichtakkordton, der im Sprung erreicht wird und sich im Schritt in die Gegenrichtung auflöst.","n":19,"h":"kap19-nichtakkordtoene.html#g-appoggiatura","f":["Appoggiatura","Appoggiaturen","freier Vorhalt"]},
  "g-arbeitsgedaechtnis": {"t":"Arbeitsgedächtnis","d":"Das Arbeitsgedächtnis ist der Teil des Gedächtnisses, mit dem wir gerade bewusst hantieren. Es fasst nur wenige Einheiten gleichzeitig, nach neueren Untersuchungen etwa drei bis fünf.","n":47,"h":"kap47-ueben.html#g-arbeitsgedaechtnis","f":["Arbeitsgedächtnis","Arbeitsgedächtnisses"]},
  "g-armstaccato": {"t":"Armstaccato","d":"Beim Armstaccato hebt sich der ganze Unterarm. Es eignet sich für laute, einzelne, kräftige Töne und Akkorde.","n":10,"h":"kap10-vortrag.html#g-armstaccato","f":["Armstaccato"]},
  "g-arpeggio": {"t":"Arpeggio","d":"Ein Arpeggio (gebrochener Akkord) ist ein Akkord, dessen Töne nacheinander statt gleichzeitig gespielt werden, oft über mehrere Oktaven.","n":44,"h":"kap44-fingersaetze.html#g-arpeggio","f":["Arpeggio","Arpeggien","Arpeggios","gebrochener Akkord","gebrochene Akkorde","gebrochenen Akkord","gebrochenen Akkorde","gebrochenen Akkorden","Akkordbrechung","Akkordbrechungen"]},
  "g-artikulation": {"t":"Artikulation","d":"Die Artikulation beschreibt, wie Töne beginnen, enden und miteinander verbunden sind.","n":10,"h":"kap10-vortrag.html#g-artikulation","f":["Artikulation","Artikulationen"]},
  "g-auditive-szenenanalyse": {"t":"auditive Szenenanalyse","d":"Die auditive Szenenanalyse beschreibt nach Albert Bregman, wie das Gehör eine Klangmischung in getrennte Ströme zerlegt. Nah beieinanderliegende Töne ordnet es demselben Strom zu.","n":19,"h":"kap19-nichtakkordtoene.html#g-auditive-szenenanalyse","f":["auditive Szenenanalyse","auditiven Szenenanalyse"]},
  "g-auditory-scene-analysis": {"t":"Auditory scene analysis","d":"Auditory scene analysis (Albert Bregman, 1990) beschreibt, wie das Gehör Klänge zu zusammenhängenden Strömen ordnet. Töne, die nah beieinanderliegen, hört es bevorzugt als eine Linie.","n":28,"h":"kap28-ii-v-i.html#g-auditory-scene-analysis","f":["auditory scene analysis"]},
  "g-aufloesung": {"t":"Auflösung","d":"Die Auflösung ist der Schritt, mit dem ein dissonanter Ton in einen Akkordton weitergeht, etwa beim Vorhalt c'' → h' über G-Dur. Auch Leitton und Septime des Dominantseptakkords lösen sich so auf.","n":19,"h":"kap19-nichtakkordtoene.html#g-aufloesung","f":["Auflösung","Auflösungen"]},
  "g-aufloesungszeichen": {"t":"Auflösungszeichen","d":"Das Zeichen ♮, das Auflösungszeichen, hebt eine Erhöhung oder Erniedrigung wieder auf.","n":1,"h":"kap01-klaviatur.html#g-aufloesungszeichen","f":["Auflösungszeichen","Auflösungszeichens"]},
  "g-auftakt": {"t":"Auftakt","d":"Ein Auftakt ist ein unvollständiger Anfangstakt: Die Melodie beginnt mit einem oder mehreren Tönen vor der ersten Eins und führt auf sie hin wie ein Anlauf.","n":4,"h":"kap04-takt.html#g-auftakt","f":["Auftakt","Auftakte","Auftakts","Auftakten"]},
  "g-auge-hand-spanne": {"t":"Auge-Hand-Spanne","d":"Die Auge-Hand-Spanne ist der Abstand, um den die Augen beim Spielen den Händen in den Noten voraus sind. Je größer sie ist, desto mehr Zeit bleibt, das Kommende vorzubereiten.","n":48,"h":"kap48-blattspiel.html#g-auge-hand-spanne","f":["Auge-Hand-Spanne"]},
  "g-augmentation": {"t":"Augmentation","d":"Augmentation heißt, die Notenwerte eines Motivs zu verdoppeln. Das Motiv klingt dadurch langsamer und bleibt trotzdem erkennbar.","n":39,"h":"kap39-bausteine.html#g-augmentation","f":["Augmentation"]},
  "g-ausloesung": {"t":"Auslösung","d":"Die Auslösung ist der Moment, in dem die Mechanik den Hammer kurz vor der Saite freigibt. Der Hammer fliegt das letzte Stück allein und hat dann keine Verbindung mehr zur Taste.","n":43,"h":"kap43-technik.html#g-ausloesung","f":["Auslösung"]},
  "g-aussenstimmen": {"t":"Außenstimme","d":"Die Außenstimmen sind die höchste und die tiefste Stimme eines Satzes, im vierstimmigen Satz also Sopran und Bass. Man hört sie am deutlichsten.","n":37,"h":"kap37-choralsatz.html#g-aussenstimmen","f":["Außenstimme","Außenstimmen"]},
  "g-ausweichung": {"t":"Ausweichung","d":"Einen kurzen Abstecher in eine andere Tonart, der zwar mit einer Kadenz bestätigt wird, aber schnell wieder verlassen wird, nennt man Ausweichung.","n":22,"h":"kap22-modulation.html#g-ausweichung","f":["Ausweichung","Ausweichungen"]},
  "g-authentische-tonart": {"t":"authentische Tonart","d":"In der Lehre von den Kirchentonarten ist eine authentische Tonart eine Tonart, deren Melodien über dem Grundton liegen.","n":16,"h":"kap16-kadenzen.html#g-authentische-tonart","f":["authentische Tonart","authentische Tonarten"]},
  "g-avoid-note": {"t":"Avoid Note","d":"Eine Avoid Note ist ein Ton, der eine kleine None über einem Akkordton bildet, etwa f über Cmaj7. Als gehaltener Ton stört er, weil er die Funktion des Akkords verwischt. Ausnahmen sind bei Dominanten die ♭9 über dem Grundton und die ♭13 über der Quinte.","n":27,"h":"kap27-optionstoene.html#g-avoid-note","f":["Avoid Note","Avoid Notes"]},
  "g-be": {"t":"b","d":"Das b ♭ erniedrigt einen Ton um einen Halbton. An den Namen wird dabei -es angehängt: d wird zu des, g zu ges. Das erniedrigte h heißt selbst b.","n":1,"h":"kap01-klaviatur.html#g-be","f":[]},
  "g-backbeat": {"t":"Backbeat","d":"Der Backbeat ist die Betonung der Zählzeiten 2 und 4 im 4/4-Takt. Er ist das Fundament von Rock und Pop.","n":46,"h":"kap46-begleitmuster.html#g-backbeat","f":["Backbeat","Backbeats"]},
  "g-backdoor": {"t":"Backdoor-Dominante","d":"Die Backdoor-Dominante ist der Septakkord auf der ♭VII. Stufe vor der Tonika, in C-Dur also B♭7 vor C. Sie stammt aus der gleichnamigen Molltonart und erreicht die Tonika „durch die Hintertür“, ohne Leitton.","n":32,"h":"kap32-reharmonisierung.html#g-backdoor","f":["Backdoor-Dominante","Backdoor-Dominanten"]},
  "g-balken": {"t":"Balken","d":"Ein Balken ist ein dicker Querstrich, der mehrere aufeinanderfolgende Achtel oder kürzere Noten verbindet. Er ersetzt die Fähnchen und fasst die Noten zusammen, die zu einem Schlag gehören.","n":3,"h":"kap03-rhythmus.html#g-balken","f":["Balken"]},
  "g-basisidee": {"t":"Basisidee","d":"Die Basisidee ist der zweitaktige Grundgedanke am Anfang eines Satzes (Themenform). Sie wird vorgestellt und gleich wiederholt, oft erst auf der Tonika, dann auf der Dominante.","n":39,"h":"kap39-bausteine.html#g-basisidee","f":["Basisidee"]},
  "g-basse-fondamentale": {"t":"basse fondamentale","d":"Die basse fondamentale (Fundamentbass) ist nach Jean-Philippe Rameau eine gedachte Basslinie aus den Grundtönen der Akkorde, auch wenn tatsächlich eine Umkehrung erklingt.","n":12,"h":"kap12-umkehrungen.html#g-basse-fondamentale","f":["basse fondamentale","Fundamentbass","Fundamentbasses"]},
  "g-bassklausel": {"t":"Bassklausel","d":"Die Bassklausel ist die Schlussformel des Basses, der Sprung von der 5. zur 1. Stufe eine Quinte abwärts oder Quarte aufwärts, in C-Dur g → c.","n":16,"h":"kap16-kadenzen.html#g-bassklausel","f":["Bassklausel"]},
  "g-basso-continuo": {"t":"basso continuo","d":"Der basso continuo ist das Bassfundament der Barockmusik. Ein Tasteninstrument, oft zusammen mit Cello oder Laute, spielt die notierte Basslinie und improvisiert darüber passende Akkorde.","n":12,"h":"kap12-umkehrungen.html#g-basso-continuo","f":["basso continuo"]},
  "g-bassschluessel": {"t":"Bassschlüssel","d":"Der Bassschlüssel (englisch bass clef) ist ein stilisiertes F. Seine zwei Punkte rahmen die vierte Linie ein, auf der das kleine f steht.","n":2,"h":"kap02-notenschrift.html#g-bassschluessel","f":["Bassschlüssel","Bassschlüssels"]},
  "g-bebop": {"t":"Bebop","d":"Bebop ist ein Jazzstil der 1940er-Jahre mit schnellen Tempi, virtuosen Melodielinien und reicher, oft alterierter Harmonik. Prägende Musiker waren Charlie Parker, Dizzy Gillespie und Bud Powell.","n":27,"h":"kap27-optionstoene.html#g-bebop","f":["Bebop"]},
  "g-bebop-skala": {"t":"Bebop-Skala","d":"Eine Bebop-Skala ist eine Tonleiter mit einem zusätzlichen chromatischen Ton. Durch diesen achten Ton fallen in Achtellinien die Akkordtöne auf die Zählzeiten.","n":30,"h":"kap30-akkordskalen.html#g-bebop-skala","f":["Bebop-Skala","Bebop-Skalen"]},
  "g-begleitmuster": {"t":"Begleitmuster","d":"Ein Begleitmuster ist eine feste Art, Bass, Harmonie und Rhythmus einer Begleitung auf die Hände zu verteilen und rhythmisch zu wiederholen. Für jeden Akkord setzt du nur die passenden Töne ein.","n":46,"h":"kap46-begleitmuster.html#g-begleitmuster","f":["Begleitmuster","Begleitmusters","Begleitmustern"]},
  "g-bezifferung": {"t":"Bezifferung","d":"Die Bezifferung besteht aus kleinen Ziffern an einer Basslinie. Sie geben an, welche Intervalle über dem Basston erklingen sollen, etwa 6 für den Sextakkord und 6/4 für den Quartsextakkord.","n":12,"h":"kap12-umkehrungen.html#g-bezifferung","f":["Bezifferung"]},
  "g-bindebogen": {"t":"Bindebogen","d":"Ein Bindebogen verbindet Noten verschiedener Tonhöhe. Er bedeutet legato: Die Töne werden gebunden, ohne Lücke gespielt.","n":3,"h":"kap03-rhythmus.html#g-bindebogen","f":["Bindebogen","Bindebögen","Bindebogens"]},
  "g-blattspiel": {"t":"Blattspiel","d":"Blattspiel (engl. sight-reading) heißt, ein unbekanntes Stück direkt vom Notenblatt zu spielen, ohne es vorher geübt zu haben.","n":48,"h":"kap48-blattspiel.html#g-blattspiel","f":["Blattspiel","Blattspiels"]},
  "g-blockakkord": {"t":"Blockakkord","d":"Bei Blockakkorden erklingen alle Töne eines Akkords gleichzeitig. In der einfachsten Begleitung spielt die linke Hand den Grundton und die rechte den Akkord, beide zusammen.","n":46,"h":"kap46-begleitmuster.html#g-blockakkord","f":["Blockakkord","Blockakkorde","Blockakkorden","Blockakkords"]},
  "g-blue-note": {"t":"Blue Note","d":"Blue Notes sind die Töne ♭3, ♭5 und ♭7 des Blues. Sänger und Instrumentalisten treffen sie oft zwischen zwei Klaviertasten, am Klavier deutet man sie mit Vorschlägen von unten an.","n":9,"h":"kap09-weitere-skalen.html#g-blue-note","f":["Blue Note","Blue Notes"]},
  "g-blues-skala": {"t":"Blues-Skala","d":"Die Blues-Skala ist die Moll-Pentatonik plus ♭5: 1 – ♭3 – 4 – ♭5 – 5 – ♭7, in a also a, c, d, es, e, g.","n":9,"h":"kap09-weitere-skalen.html#g-blues-skala","f":["Blues-Skala","Blues-Skalen"]},
  "g-bluehender-kontrapunkt": {"t":"blühender Kontrapunkt","d":"Der blühende Kontrapunkt (contrapunctus floridus) ist die fünfte Gattung nach Fux. Die Gegenstimme mischt alle Notenwerte der früheren Gattungen und folgt jeweils deren Regeln.","n":36,"h":"kap36-kontrapunkt-3.html#g-bluehender-kontrapunkt","f":["blühender Kontrapunkt","blühenden Kontrapunkt","blühenden Kontrapunkts"]},
  "g-bordun": {"t":"Bordun","d":"Ein Bordun ist ein durchgehender Dauerton im Bass, wie ihn Dudelsack oder Drehleier spielen. Über ihm bewegt sich die Melodie.","n":26,"h":"kap26-sequenzen.html#g-bordun","f":["Bordun","Borduns"]},
  "g-bpm": {"t":"BPM","d":"BPM (englisch beats per minute, Schläge pro Minute) gibt das Tempo als Zahl an. ♩ = 120 heißt 120 Viertel pro Minute, ein Schlag dauert dann 60 / 120 = 0,5 Sekunden.","n":4,"h":"kap04-takt.html#g-bpm","f":["BPM","Schläge pro Minute","Schlägen pro Minute"]},
  "g-bridge": {"t":"Bridge","d":"Die Bridge (auch middle eight) ist ein Kontrastteil mit neuen Akkorden. Im Popsong erklingt sie meist einmal nach dem zweiten Refrain, in der AABA-Form ist sie der B-Teil.","n":42,"h":"kap42-songformen.html#g-bridge","f":["Bridge"]},
  "g-bwv": {"t":"BWV","d":"BWV steht für Bach-Werke-Verzeichnis. Es gibt jedem Werk Johann Sebastian Bachs eine feste Nummer, etwa BWV 846 für Präludium und Fuge C-Dur aus dem Wohltemperierten Klavier.","n":26,"h":"kap26-sequenzen.html#g-bwv","f":["BWV"]},
  "g-c-schluessel": {"t":"C-Schlüssel","d":"Der C-Schlüssel zeigt mit seiner Mitte auf die Linie, auf der das c' steht. Er kann auf verschiedenen Linien stehen, etwa als Altschlüssel auf der dritten oder als Tenorschlüssel auf der vierten Linie.","n":2,"h":"kap02-notenschrift.html#g-c-schluessel","f":["C-Schlüssel"]},
  "g-call-and-response": {"t":"Call and Response","d":"Call and Response ist ein Prinzip der afroamerikanischen Musiktradition. Ein Sänger beginnt eine Zeile (Call), ein Instrument antwortet (Response), im Blues meist in der zweiten Hälfte jeder Zeile.","n":42,"h":"kap42-songformen.html#g-call-and-response","f":["Call and Response"]},
  "g-cambiata": {"t":"Cambiata","d":"Die Cambiata ist eine Figur aus vier Tönen: Schritt abwärts in eine Dissonanz, Terzsprung abwärts in eine Konsonanz, dann Schritt aufwärts. Mit ihr darf eine Dissonanz ausnahmsweise springend verlassen werden.","n":35,"h":"kap35-kontrapunkt-2.html#g-cambiata","f":["Cambiata","Fux’sche Wechselnote"]},
  "g-cantus-firmus": {"t":"Cantus firmus","d":"Der Cantus firmus (lateinisch „feststehender Gesang“) ist die vorgegebene Melodie, meist in ganzen Noten, zu der im Kontrapunkt eine Gegenstimme erfunden wird.","n":34,"h":"kap34-kontrapunkt-1.html#g-cantus-firmus","f":["Cantus firmus"]},
  "g-cent": {"t":"Cent","d":"Cent ist ein Maß für Intervalle: Die Oktave wird in 1200 Cent geteilt, ein Halbton auf dem Klavier hat genau 100 Cent.","n":5,"h":"kap05-intervalle.html#g-cent","f":["Cent"]},
  "g-chaconne": {"t":"Chaconne","d":"Die Chaconne ist eine Variationsform über einem ständig wiederkehrenden Bass, ebenso wie die Passacaglia.","n":18,"h":"kap18-pop-progressionen.html#g-chaconne","f":["Chaconne"]},
  "g-charakteristischer-ton": {"t":"charakteristischer Ton","d":"Der charakteristische Ton ist der Ton, der einen Modus von seinem nächsten Verwandten unterscheidet, also Dorisch von Moll oder Mixolydisch von Dur.","n":24,"h":"kap24-modi.html#g-charakteristischer-ton","f":["charakteristischer Ton","charakteristische Ton","charakteristischen Ton"]},
  "g-charakterstueck": {"t":"Charakterstück","d":"Ein Charakterstück ist ein kürzeres Instrumentalstück, meist für Klavier, das eine bestimmte Stimmung oder ein Bild ausdrückt. Die Gattung blühte in der Romantik.","n":40,"h":"kap40-liedformen.html#g-charakterstueck","f":["Charakterstücken","Charakterstücke","Charakterstück"]},
  "g-charaktervariation": {"t":"Charaktervariation","d":"Eine Charaktervariation versetzt ein Thema in einen ganz anderen Tonfall, etwa als Walzer oder Trauermarsch.","n":40,"h":"kap40-liedformen.html#g-charaktervariation","f":["Charaktervariation","Charaktervariationen"]},
  "g-choral": {"t":"Choral","d":"Ein Choral ist ein Gemeindelied der evangelischen Kirche. Im vierstimmigen Choralsatz liegt seine Melodie im Sopran, Alt, Tenor und Bass ergänzen sie.","n":37,"h":"kap37-choralsatz.html#g-choral","f":["Chorälen","Chorals","Choräle","Choral"]},
  "g-chorus-jazz": {"t":"Chorus (Jazz)","d":"Ein Chorus ist im Jazz ein vollständiger Durchgang durch die Form eines Stücks, etwa durch die 32 Takte eines AABA-Standards. Solisten improvisieren oft mehrere Chorusse hintereinander.","n":42,"h":"kap42-songformen.html#g-chorus-jazz","f":["Chorus","Chorusse"]},
  "g-chromatische-toene": {"t":"chromatisch","d":"Chromatisch (griechisch chroma, Farbe) heißen Töne, die nicht zur Tonart gehören und eine Melodie „färben“, etwa fis in C-Dur. Die Töne der Tonart selbst heißen diatonisch.","n":9,"h":"kap09-weitere-skalen.html#g-chromatische-toene","f":["chromatisch","chromatische","chromatischen","chromatischer","chromatisches"]},
  "g-chromatische-modulation": {"t":"chromatische Modulation","d":"Bei einer chromatischen Modulation wird ein Akkordton um einen Halbton verändert, und der neue Akkord führt in die neue Tonart. Eine Stimme bewegt sich dabei chromatisch, etwa g – gis – a.","n":22,"h":"kap22-modulation.html#g-chromatische-modulation","f":["chromatische Modulation","chromatischen Modulation","chromatische Modulationen"]},
  "g-chromatisch": {"t":"chromatische Tonleiter","d":"Die chromatische Tonleiter enthält alle zwölf Töne der Oktave in Halbtonschritten.","n":9,"h":"kap09-weitere-skalen.html#g-chromatisch","f":["chromatische Tonleiter","chromatischen Tonleiter"]},
  "g-chunk": {"t":"Chunk","d":"Ein Chunk ist eine größere, bedeutungsvolle Einheit, die das Gedächtnis als Ganzes speichert und abruft, etwa ein Dreiklang statt dreier Einzelnoten. Die Bildung solcher Einheiten heißt Chunking.","n":47,"h":"kap47-ueben.html#g-chunk","f":["Chunk","Chunks","Chunking"]},
  "g-cluster": {"t":"Cluster","d":"Ein Cluster ist ein Zusammenklang aus dicht nebeneinanderliegenden Tönen, etwa aus übereinandergeschichteten Sekunden wie c–d–e. Er klingt wie ein Klumpen aus Reibungen.","n":11,"h":"kap11-dreiklaenge.html#g-cluster","f":["Cluster"]},
  "g-coda": {"t":"Coda","d":"Eine Coda (italienisch „Schwanz“) ist ein angehängter Schlussteil, der das Ende eines Stücks bekräftigt, etwa nach der Reprise einer Sonatenform.","n":41,"h":"kap41-sonate.html#g-coda","f":["Coda","Codas"]},
  "g-couplet": {"t":"Couplet","d":"Couplets (auch Episoden) sind im Rondo die wechselnden Teile zwischen den Auftritten des Refrains. Sie bringen andere Tonarten und Charaktere.","n":40,"h":"kap40-liedformen.html#g-couplet","f":["Couplet","Couplets"]},
  "g-crescendo": {"t":"crescendo","d":"Crescendo (abgekürzt cresc., als Zeichen eine sich öffnende Gabel) bedeutet: allmählich lauter werden.","n":10,"h":"kap10-vortrag.html#g-crescendo","f":["crescendo","Crescendos","Crescendi"]},
  "g-da-capo": {"t":"Da capo","d":"Da capo (abgekürzt D.C., „vom Kopf“) bedeutet: zurück zum Anfang des Stücks. D.C. al Fine heißt: zurück zum Anfang und bis zum Wort Fine spielen.","n":10,"h":"kap10-vortrag.html#g-da-capo","f":["Da capo"]},
  "g-dal-segno": {"t":"Dal segno","d":"Dal segno (abgekürzt D.S., „vom Zeichen“) bedeutet: zurück zum Segno-Zeichen 𝄋 und von dort weiterspielen, etwa bis Fine oder bis „zur Coda“.","n":10,"h":"kap10-vortrag.html#g-dal-segno","f":["Dal segno","Segno"]},
  "g-daempfer": {"t":"Dämpfer","d":"Der Dämpfer liegt auf der Saite und hält sie still. Beim Drücken der Taste hebt er sich, beim Loslassen fällt er zurück und der Ton verstummt.","n":43,"h":"kap43-technik.html#g-daempfer","f":["Dämpfer","Dämpfern","Dämpfers"]},
  "g-daumenuntersatz": {"t":"Daumenuntersatz","d":"Beim Daumenuntersatz gleitet der Daumen unter den Fingern hindurch und spielt den nächsten Ton. So wechselt die Hand ohne Lücke die Lage, rechts aufwärts und links abwärts.","n":44,"h":"kap44-fingersaetze.html#g-daumenuntersatz","f":["Daumenuntersatz","Daumenuntersatzes","Untersatz"]},
  "g-deliberate-practice": {"t":"deliberate practice","d":"Deliberate practice (bewusstes, gezieltes Üben) nannte der Psychologe K. Anders Ericsson die Arbeit an den eigenen Schwächen, mit Konzentration und Rückmeldung, oft unter Anleitung.","n":47,"h":"kap47-ueben.html#g-deliberate-practice","f":["deliberate practice"]},
  "g-deutscher-sextakkord": {"t":"deutscher Sextakkord","d":"Der deutsche Sextakkord (Ger+6) ist der übermäßige Sextakkord mit zusätzlicher Moll-Terz über dem Grundton, in c-Moll as – c – es – fis. Er klingt wie ein Dominantseptakkord und löst sich meist über den Quartsextakkord der Tonika auf.","n":25,"h":"kap25-chromatische-akkorde.html#g-deutscher-sextakkord","f":["deutscher Sextakkord","deutsche Sextakkord","deutschen Sextakkord","deutschen Sextakkords"]},
  "g-dezime": {"t":"Dezime","d":"Die Dezime ist eine Terz plus eine Oktave, zum Beispiel c'–e''. Die kleine Dezime hat 15 Halbtöne, die große 16.","n":5,"h":"kap05-intervalle.html#g-dezime","f":["Dezime","Dezimen"]},
  "g-diatonisch": {"t":"diatonisch","d":"Diatonisch heißen Tonleitern mit sieben Tönen aus Ganz- und Halbtönen, in denen jeder Buchstabe genau einmal vorkommt, etwa die Dur-Tonleiter.","n":6,"h":"kap06-dur.html#g-diatonisch","f":["diatonisch","diatonische","diatonischen","diatonischer","diatonisches"]},
  "g-diatonische-modulation": {"t":"diatonische Modulation","d":"Bei einer diatonischen Modulation wechselt die Musik über einen Drehpunktakkord, der in beiden Tonarten vorkommt, in die neue Tonart. Danach folgen meist V – I der neuen Tonart.","n":22,"h":"kap22-modulation.html#g-diatonische-modulation","f":["diatonische Modulation","diatonischen Modulation","diatonische Modulationen"]},
  "g-diminuendo": {"t":"diminuendo","d":"Diminuendo oder decrescendo (abgekürzt dim. oder decresc., als Zeichen eine sich schließende Gabel) bedeutet: allmählich leiser werden.","n":10,"h":"kap10-vortrag.html#g-diminuendo","f":["diminuendo","Diminuendos","decrescendo"]},
  "g-diminution": {"t":"Diminution","d":"Diminution heißt, die Notenwerte eines Motivs zu halbieren. Das Motiv klingt dadurch schneller und bleibt trotzdem erkennbar.","n":39,"h":"kap39-bausteine.html#g-diminution","f":["Diminution"]},
  "g-direktes-pedal": {"t":"direktes Pedal","d":"Beim direkten Pedal (auch rhythmisches Pedal) trittst du das Pedal genau mit dem Anschlag und hebst es im Rhythmus der Musik wieder.","n":45,"h":"kap45-pedal.html#g-direktes-pedal","f":["direktes Pedal","direkte Pedal","direkten Pedal","direkten Pedals","rhythmisches Pedal","rhythmische Pedal","rhythmischen Pedal"]},
  "g-diskant": {"t":"Diskant","d":"Der Diskant ist die hohe Lage der Klaviatur, das Gegenstück zum Bass. Das Wort bezeichnet auch die oberste Stimme eines mehrstimmigen Satzes.","n":43,"h":"kap43-technik.html#g-diskant","f":["Diskant"]},
  "g-diskantklausel": {"t":"Diskantklausel","d":"Die Diskantklausel ist die Schlussformel der Oberstimme, der Schritt von der 7. zur 8. Stufe einen Halbton aufwärts, in C-Dur h → c.","n":16,"h":"kap16-kadenzen.html#g-diskantklausel","f":["Diskantklausel"]},
  "g-dissonanz": {"t":"Dissonanz","d":"Eine Dissonanz ist ein Intervall, das Spannung erzeugt und nach Auflösung verlangt: Sekunden, Septimen, der Tritonus und alle übermäßigen und verminderten Intervalle.","n":5,"h":"kap05-intervalle.html#g-dissonanz","f":["Dissonanz","Dissonanzen","dissonant","dissonante","dissonanten"]},
  "g-dissonanz-im-grossen": {"t":"Dissonanz im Großen","d":"Als „Dissonanz im Großen“ beschreibt Charles Rosen den Seitensatz in der Dominante. Er klingt in sich stabil, steht aber in der falschen Tonart und verlangt nach Auflösung in der Reprise.","n":41,"h":"kap41-sonate.html#g-dissonanz-im-grossen","f":["Dissonanz im Großen"]},
  "g-dominante": {"t":"Dominante","d":"Die Dominante ist die 5. Stufe einer Tonart, eine Quinte über der Tonika und ihr stärkster Gegenpol. In C-Dur ist das g.","n":6,"h":"kap06-dur.html#g-dominante","f":["Dominante","Dominanten"]},
  "g-dominante-funktion": {"t":"Dominante (Funktion)","d":"Die Dominante (V, Funktionssymbol D) ist der Akkord auf der 5. Stufe und der Akkord der größten Spannung. Mit ihrem Leitton drängt sie zur Tonika zurück.","n":14,"h":"kap14-funktionen.html#g-dominante-funktion","f":["Dominante","Dominanten"]},
  "g-dominantorgelpunkt": {"t":"Dominantorgelpunkt","d":"Ein Dominantorgelpunkt ist ein Orgelpunkt auf der 5. Stufe, oft kurz vor dem Einsatz der Tonika. Er staut Spannung auf, weil das Ohr auf die Auflösung zur Tonika wartet.","n":26,"h":"kap26-sequenzen.html#g-dominantorgelpunkt","f":["Dominantorgelpunkt","Dominantorgelpunkte","Dominantorgelpunkts"]},
  "g-dominantseptakkord": {"t":"Dominantseptakkord","d":"Der Dominantseptakkord ist ein Durdreiklang mit kleiner Septime, zum Beispiel G7 = g–h–d–f. In Dur kommt er leitereigen nur auf der V. Stufe vor, und sein Tritonus drängt zur Tonika.","n":15,"h":"kap15-septakkorde.html#g-dominantseptakkord","f":["Dominantseptakkord","Dominantseptakkorde","Dominantseptakkords","Dominantseptakkorden","Dominantsept"]},
  "g-dominantseptnonakkord": {"t":"Dominantseptnonakkord","d":"Ein Dominantseptnonakkord ist ein Dominantseptakkord mit zusätzlicher None, etwa G7♭9 aus g, h, d, f und as. Ohne Grundton ergibt die Form mit kleiner None einen verminderten Septakkord.","n":21,"h":"kap21-zwischendominanten.html#g-dominantseptnonakkord","f":["Dominantseptnonakkorde","Dominantseptnonakkords","Dominantseptnonakkord"]},
  "g-dominanttonart": {"t":"Dominanttonart","d":"Die Dominanttonart ist die Tonart, deren Tonika die fünfte Stufe der Ausgangstonart ist, zu C-Dur also G-Dur. Ihre Vorzeichnung hat ein ♯ mehr oder ein ♭ weniger.","n":22,"h":"kap22-modulation.html#g-dominanttonart","f":["Dominanttonart","Dominanttonarten"]},
  "g-doppel-b": {"t":"Doppel-b","d":"Das Doppel-b 𝄫 erniedrigt einen Ton um zwei Halbtöne. An den Namen wird -eses angehängt: deses, heses.","n":1,"h":"kap01-klaviatur.html#g-doppel-b","f":["Doppel-b"]},
  "g-doppeldominante": {"t":"Doppeldominante","d":"Die Doppeldominante ist die Dominante der Dominante (V/V), in C-Dur also D-Dur bzw. D7. Sie steht oft direkt vor der Dominante, kurz vor einem Schluss. In der Funktionstheorie heißt sie DD.","n":21,"h":"kap21-zwischendominanten.html#g-doppeldominante","f":["Doppeldominante","Doppeldominanten"]},
  "g-doppelkreuz": {"t":"Doppelkreuz","d":"Das Doppelkreuz 𝄪 erhöht einen Ton um zwei Halbtöne. An den Namen wird -isis angehängt: cisis, fisis.","n":1,"h":"kap01-klaviatur.html#g-doppelkreuz","f":["Doppelkreuz","Doppelkreuze"]},
  "g-doppelpunktierung": {"t":"Doppelpunktierung","d":"Bei einer Doppelpunktierung stehen zwei Punkte hinter einer Note. Der zweite Punkt fügt noch die Hälfte des ersten hinzu: Eine doppelt punktierte Halbe dauert 2 + 1 + ½ = 3½ Viertel.","n":3,"h":"kap03-rhythmus.html#g-doppelpunktierung","f":["Doppelpunktierung","doppelt punktierte","doppelt punktierten"]},
  "g-doppelschlag": {"t":"Doppelschlag","d":"Ein Doppelschlag ist eine Verzierung aus oberer Nebennote, Hauptnote, unterer Nebennote und wieder Hauptnote.","n":10,"h":"kap10-vortrag.html#g-doppelschlag","f":["Doppelschlag","Doppelschläge"]},
  "g-doppelte-ausloesung": {"t":"doppelte Auslösung","d":"Die doppelte Auslösung ist eine Flügelmechanik, die den Hammer nach dem Anschlag auf halber Höhe hält. So lässt sich ein Ton erneut anschlagen, bevor die Taste ganz hochgekommen ist.","n":43,"h":"kap43-technik.html#g-doppelte-ausloesung","f":["doppelte Auslösung","doppelten Auslösung"]},
  "g-doppelte-rueckkehr": {"t":"doppelte Rückkehr","d":"Die doppelte Rückkehr ist der Beginn der Reprise einer Sonatenform, an dem Hauptthema und Grundtonart gleichzeitig zurückkehren.","n":41,"h":"kap41-sonate.html#g-doppelte-rueckkehr","f":["doppelte Rückkehr","doppelten Rückkehr"]},
  "g-doppelter-plagalschluss": {"t":"doppelter Plagalschluss","d":"Der doppelte Plagalschluss ist die Folge ♭VII – IV – I, in C-Dur B – F – C. Sie reiht zwei Plagalschlüsse (IV – I) aneinander, jeder Grundton liegt eine Quinte über dem vorigen.","n":23,"h":"kap23-modale-mischung.html#g-doppelter-plagalschluss","f":["doppelter Plagalschluss","doppelten Plagalschluss"]},
  "g-doppelter-taktstrich": {"t":"doppelter Taktstrich","d":"Ein doppelter Taktstrich besteht aus zwei dünnen Linien und beendet einen Abschnitt innerhalb eines Stücks.","n":4,"h":"kap04-takt.html#g-doppelter-taktstrich","f":["doppelter Taktstrich","doppelten Taktstrich","doppelte Taktstrich","Doppelstrich","Doppelstrichs","Doppelstriche"]},
  "g-dorisch": {"t":"Dorisch","d":"Dorisch ist der Modus, der auf den weißen Tasten von d bis d' entsteht. Er klingt wie natürliches Moll mit großer Sexte.","n":24,"h":"kap24-modi.html#g-dorisch","f":["dorisch","dorische","dorischen","dorischer","dorisches"]},
  "g-drehpunktakkord": {"t":"Drehpunktakkord","d":"Ein Drehpunktakkord ist ein Akkord, der in der alten und der neuen Tonart vorkommt und beim Modulieren umgedeutet wird. Von C-Dur nach G-Dur eignet sich etwa a-Moll, vi in C und ii in G.","n":22,"h":"kap22-modulation.html#g-drehpunktakkord","f":["Drehpunktakkord","Drehpunktakkorde","Drehpunktakkorden","Drehpunktakkords","Drehpunkt"]},
  "g-dreiklang": {"t":"Dreiklang","d":"Ein Dreiklang ist ein Akkord aus zwei übereinandergelegten Terzen, also aus Grundton, Terz und Quinte, zum Beispiel c–e–g.","n":11,"h":"kap11-dreiklaenge.html#g-dreiklang","f":["Dreiklang","Dreiklänge","Dreiklängen","Dreiklangs"]},
  "g-dreiteilige-liedform": {"t":"dreiteilige Liedform","d":"Die dreiteilige Liedform folgt dem Muster A B A: ein Hauptteil, ein kontrastierender Mittelteil und die Rückkehr des Hauptteils.","n":40,"h":"kap40-liedformen.html#g-dreiteilige-liedform","f":["dreiteilige Liedform","dreiteilige Form","dreiteiligen Form"]},
  "g-drop-2": {"t":"Drop-2-Voicing","d":"Ein Drop-2-Voicing entsteht aus einem Vierklang in enger Lage, indem man den zweithöchsten Ton eine Oktave tiefer legt („fallen lässt“).","n":29,"h":"kap29-voicings.html#g-drop-2","f":["Drop-2-Voicing","Drop-2-Voicings","Drop 2"]},
  "g-dualismus": {"t":"Dualismus","d":"Der Dualismus ist Hugo Riemanns Idee, Moll als Spiegelbild von Dur zu denken und den Mollakkord aus einer nach unten verlaufenden Untertonreihe abzuleiten. Spätere Theoretiker gaben diese Idee auf.","n":14,"h":"kap14-funktionen.html#g-dualismus","f":["Dualismus","dualistisch"]},
  "g-duodezime": {"t":"Duodezime","d":"Die Duodezime ist eine Quinte plus eine Oktave, zum Beispiel c'–g''. Die reine Duodezime hat 19 Halbtöne.","n":5,"h":"kap05-intervalle.html#g-duodezime","f":["Duodezime","Duodezimen"]},
  "g-duole": {"t":"Duole","d":"Eine Duole sind zwei Noten in der Zeit von drei Noten desselben Werts. Sie kommt vor allem im 6/8-Takt vor und wird mit einer kleinen 2 gekennzeichnet.","n":3,"h":"kap03-rhythmus.html#g-duole","f":["Duole","Duolen"]},
  "g-dur-blues": {"t":"Dur-Blues-Skala","d":"Die Dur-Blues-Skala ist die Dur-Pentatonik mit zusätzlicher kleiner Terz: 1 – 2 – ♭3 – 3 – 5 – 6, in C also c, d, es, e, g, a. Sie klingt heller als die Blues-Skala.","n":9,"h":"kap09-weitere-skalen.html#g-dur-blues","f":["Dur-Blues","Dur-Blues-Skala"]},
  "g-dur-moll-wechsel": {"t":"Dur-Moll-Wechsel","d":"Beim Dur-Moll-Wechsel wechselt die Tonika selbst kurz zwischen Dur und Moll, etwa von C-Dur nach c-Moll und zurück. Der Grundton bleibt dabei gleich.","n":23,"h":"kap23-modale-mischung.html#g-dur-moll-wechsel","f":["Dur-Moll-Wechsel","Dur-Moll-Wechsels"]},
  "g-dur-pentatonik": {"t":"Dur-Pentatonik","d":"Die Dur-Pentatonik ist die Dur-Tonleiter ohne 4. und 7. Stufe: 1 – 2 – 3 – 5 – 6, in C also c, d, e, g, a. Sie enthält keinen Halbtonschritt.","n":9,"h":"kap09-weitere-skalen.html#g-dur-pentatonik","f":["Dur-Pentatonik"]},
  "g-dur-tonleiter": {"t":"Dur-Tonleiter","d":"Die Dur-Tonleiter ist die siebentönige Tonleiter mit dem Muster Ganz – Ganz – Halb – Ganz – Ganz – Ganz – Halb. Auf c ergibt sie die weißen Tasten c, d, e, f, g, a, h.","n":6,"h":"kap06-dur.html#g-dur-tonleiter","f":["Dur-Tonleiter","Dur-Tonleitern","Durtonleiter","Durtonleitern"]},
  "g-durchfuehrung": {"t":"Durchführung","d":"Die Durchführung ist der mittlere Teil der Sonatenform. Sie verarbeitet die Themen der Exposition und wandert durch verschiedene Tonarten, bevor die Reprise einsetzt.","n":41,"h":"kap41-sonate.html#g-durchfuehrung","f":["Durchführung","Durchführungen"]},
  "g-fugendurchfuehrung": {"t":"Durchführung (Fuge)","d":"In der Fuge heißt jeder vollständige Durchgang des Themas durch alle Stimmen Durchführung. Die erste Durchführung ist die Exposition. In der Sonate hat das Wort eine andere Bedeutung.","n":38,"h":"kap38-fuge.html#g-fugendurchfuehrung","f":["~Durchführung","~Durchführungen"]},
  "g-durchgang": {"t":"Durchgang","d":"Ein Durchgang (Durchgangston) füllt den Raum zwischen zwei Akkordtönen stufenweise aus, etwa f zwischen e und g über C-Dur. Er wird im Schritt erreicht und in derselben Richtung im Schritt verlassen.","n":19,"h":"kap19-nichtakkordtoene.html#g-durchgang","f":["Durchgangston","Durchgangstöne","Durchgangstönen","chromatischer Durchgang","chromatischen Durchgängen"]},
  "g-durchgangs-quartsextakkord": {"t":"Durchgangs-Quartsextakkord","d":"Ein Durchgangs-Quartsextakkord steht auf leichter Zeit über einem Bass, der stufenweise durchgeht, etwa C/G zwischen F und F/A. Die Oberstimmen bleiben liegen oder gehen in Schritten.","n":37,"h":"kap37-choralsatz.html#g-durchgangs-quartsextakkord","f":["Durchgangs-Quartsextakkord","Durchgangs-Quartsextakkorde","Durchgangs-Quartsextakkords"]},
  "g-durchgangsakkord": {"t":"Durchgangsakkord","d":"Ein Durchgangsakkord ist ein Akkord, der nur als kurzer Zwischenschritt entsteht, weil eine Stimme stufenweise oder chromatisch weitergeht, etwa C – C+ – C6 mit der Linie g – gis – a.","n":20,"h":"kap20-moll-harmonik.html#g-durchgangsakkord","f":["Durchgangsakkord","Durchgangsakkorde"]},
  "g-durdreiklang": {"t":"Durdreiklang","d":"Ein Durdreiklang besteht aus einer großen Terz und darüber einer kleinen Terz, zusammen eine reine Quinte, zum Beispiel c–e–g. Sein Akkordsymbol ist der bloße Grundton, etwa C.","n":11,"h":"kap11-dreiklaenge.html#g-durdreiklang","f":["Durdreiklang","Durdreiklänge","Durdreiklängen","Durdreiklangs","Dur-Dreiklang","Dur-Dreiklänge","Dur-Dreiklangs","Durakkord","Durakkorde","Durakkords","Dur-Akkord","Dur-Akkorde"]},
  "g-dynamik": {"t":"Dynamik","d":"Die Lautstärke eines Stücks heißt Dynamik.","n":10,"h":"kap10-vortrag.html#g-dynamik","f":["Dynamik"]},
  "g-echappee": {"t":"Échappée","d":"Eine Échappée ist ein unbetonter Nichtakkordton, der im Schritt erreicht und im Sprung in die Gegenrichtung verlassen wird. Die Melodie entwischt kurz aus der Linie.","n":19,"h":"kap19-nichtakkordtoene.html#g-echappee","f":["Échappée"]},
  "g-einfacher-takt": {"t":"einfache Taktart","d":"In einfachen Taktarten wie 2/4, 3/4 und 4/4 wird jeder Schlag in zwei gleiche Teile geteilt, etwa eine Viertel in zwei Achtel.","n":4,"h":"kap04-takt.html#g-einfacher-takt","f":["einfache Taktart","einfache Taktarten","einfachen Taktarten","einfache Takte","einfachen Takte"]},
  "g-eingestrichene-oktave": {"t":"eingestrichene Oktave","d":"Die eingestrichene Oktave reicht vom mittleren C c' bis h' (wissenschaftlich C4 bis B4). Ihre Töne schreibt man mit Kleinbuchstaben und einem Strich.","n":1,"h":"kap01-klaviatur.html#g-eingestrichene-oktave","f":["eingestrichene Oktave","eingestrichenen Oktave"]},
  "g-eins": {"t":"Eins","d":"Die Eins (englisch downbeat) ist der erste und schwerste Schlag eines Takts, direkt nach dem Taktstrich.","n":4,"h":"kap04-takt.html#g-eins","f":[]},
  "g-elterntonart": {"t":"Elterntonart","d":"Die Elterntonart eines Modus ist die Dur-Tonart mit denselben Tönen. e-Dorisch hat zum Beispiel die Elterntonart D-Dur, weil e deren 2. Stufe ist, und damit die Vorzeichen fis und cis.","n":24,"h":"kap24-modi.html#g-elterntonart","f":["Elterntonart","Dur-Elterntonart"]},
  "g-lage-eng": {"t":"enge Lage","d":"In enger Lage liegen die Oberstimmen eines Akkords so dicht wie möglich. Zwischen zwei benachbarten Oberstimmen passt kein weiterer Akkordton.","n":12,"h":"kap12-umkehrungen.html#g-lage-eng","f":["enge Lage","enger Lage","engen Lage"]},
  "g-engfuehrung": {"t":"Engführung","d":"Eine Engführung entsteht, wenn sich Themeneinsätze überlappen, also eine Stimme das Thema beginnt, bevor die vorige es beendet hat.","n":38,"h":"kap38-fuge.html#g-engfuehrung","f":["Engführung","Engführungen"]},
  "g-enharmonisch": {"t":"enharmonisch","d":"Enharmonisch verwechselt heißen zwei Töne oder Intervalle, die verschieden geschrieben werden, aber auf dem Klavier gleich klingen, etwa die übermäßige Sekunde c–dis und die kleine Terz c–es.","n":5,"h":"kap05-intervalle.html#g-enharmonisch","f":["enharmonisch","enharmonisch verwechselt","enharmonisch verwechselte","enharmonische Intervalle"]},
  "g-enharmonische-modulation": {"t":"enharmonische Modulation","d":"Bei einer enharmonischen Modulation wird ein Akkord enharmonisch umgedeutet, etwa ein verminderter Septakkord oder ein Dominantseptakkord, und führt so in eine neue, oft weit entfernte Tonart.","n":22,"h":"kap22-modulation.html#g-enharmonische-modulation","f":["enharmonische Modulation","enharmonischen Modulation","enharmonischer Modulation","enharmonische Modulationen","enharmonischen Modulationen"]},
  "g-enharmonische-tonarten": {"t":"enharmonische Tonarten","d":"Enharmonische Tonarten klingen auf dem Klavier gleich, werden aber verschieden geschrieben: H-Dur und Ces-Dur, Fis-Dur und Ges-Dur, Cis-Dur und Des-Dur. Ihre Vorzeichen ergeben zusammen zwölf.","n":7,"h":"kap07-quintenzirkel.html#g-enharmonische-tonarten","f":["enharmonische Tonarten","enharmonischen Tonarten","enharmonische Paare"]},
  "g-enharmonische-verwechslung": {"t":"enharmonische Verwechslung","d":"Zwei Namen für dieselbe Taste nennt man enharmonische Verwechslung.","n":1,"h":"kap01-klaviatur.html#g-enharmonische-verwechslung","f":["enharmonische Verwechslung","enharmonischen Verwechslung","enharmonische Verwechslungen","enharmonischen Verwechslungen"]},
  "g-erb": {"t":"ERB","d":"ERB (englisch equivalent rectangular bandwidth) ist ein Näherungsmaß für die kritische Bandbreite des Gehörs, angegeben in Hertz.","n":29,"h":"kap29-voicings.html#g-erb","f":["ERB"]},
  "g-erweiterte-periode": {"t":"erweiterte Periode","d":"Eine erweiterte Periode ist eine Periode, deren Vorder- oder Nachsatz durch Wiederholungen, eingeschobene Takte oder einen hinausgezögerten Schluss verlängert wird.","n":39,"h":"kap39-bausteine.html#g-erweiterte-periode","f":["erweiterte Periode"]},
  "g-etuede": {"t":"Etüde","d":"Eine Etüde ist ein Übungsstück, das eine bestimmte Spieltechnik trainiert, oft mit künstlerischem Anspruch wie bei Chopin.","n":26,"h":"kap26-sequenzen.html#g-etuede","f":["Etüden","Etüde"]},
  "g-fugenexposition": {"t":"Exposition (Fuge)","d":"Die Exposition ist der Anfang einer Fuge, in dem jede Stimme einmal mit dem Thema oder der Antwort einsetzt.","n":38,"h":"kap38-fuge.html#g-fugenexposition","f":["Fugenexposition","~Exposition"]},
  "g-exposition-sonate": {"t":"Exposition (Sonatenform)","d":"Die Exposition ist der erste große Teil der Sonatenform. Sie stellt Hauptsatz und Seitensatz vor und baut den Tonartenkonflikt auf, indem sie von der Grundtonart in eine Nebentonart führt.","n":41,"h":"kap41-sonate.html#g-exposition-sonate","f":["Exposition","Expositionen"]},
  "g-f-schluessel": {"t":"F-Schlüssel","d":"F-Schlüssel ist ein anderer Name für den Bassschlüssel. Er ist aus dem Buchstaben F entstanden und legt fest, auf welcher Linie das kleine f steht.","n":2,"h":"kap02-notenschrift.html#g-f-schluessel","f":["F-Schlüssel"]},
  "g-faehnchen": {"t":"Fähnchen","d":"Ein Fähnchen ist der kleine Haken am Hals einer einzelnen Achtel oder kürzeren Note. Jedes zusätzliche Fähnchen halbiert den Wert.","n":3,"h":"kap03-rhythmus.html#g-faehnchen","f":["Fähnchen"]},
  "g-fakebook": {"t":"Fakebook","d":"Ein Fakebook ist eine Sammlung von Leadsheets. Das bekannteste ist das „Real Book“ mit Jazzstandards.","n":17,"h":"kap17-leadsheets.html#g-fakebook","f":["Fakebook","Fakebooks"]},
  "g-fauxbourdon": {"t":"Fauxbourdon","d":"Fauxbourdon heißt eine Satzweise des 15. Jahrhunderts, in der Akkorde in Sextakkordlage parallel stufenweise auf- oder absteigen.","n":26,"h":"kap26-sequenzen.html#g-fauxbourdon","f":["Fauxbourdon"]},
  "g-fermate": {"t":"Fermate","d":"Eine Fermate 𝄐 über einer Note oder Pause bedeutet, sie nach Gefühl länger auszuhalten. Danach geht es im Tempo weiter.","n":4,"h":"kap04-takt.html#g-fermate","f":["Fermate","Fermaten"]},
  "g-figuration": {"t":"Figuration","d":"Bei der Figuration wird eine Melodie in schnellere Notenwerte aufgelöst. Die Haupttöne bleiben auf den betonten Zeiten, dazwischen liegen Nachbartöne.","n":40,"h":"kap40-liedformen.html#g-figuration","f":["Figuration"]},
  "g-finalis": {"t":"Finalis","d":"Finalis (Mehrzahl Finales) heißt der Grundton eines mittelalterlichen Modus. Die mittelalterliche Theorie kannte zunächst vier Finales: d, e, f und g.","n":24,"h":"kap24-modi.html#g-finalis","f":["Finalis","Finales"]},
  "g-fine": {"t":"Fine","d":"Fine (italienisch „Ende“) markiert die Stelle, an der ein Stück nach einem Sprung mit Da capo oder Dal segno endet.","n":10,"h":"kap10-vortrag.html#g-fine","f":[]},
  "g-fingerlegato": {"t":"Fingerlegato.","d":"Fingerlegato ist Legato allein mit den Fingern: Der nächste Finger drückt seine Taste genau in dem Moment, in dem der vorige seine loslässt. Bei langsamen, gesanglichen Stellen dürfen sich die Töne minimal überlappen.","n":10,"h":"kap10-vortrag.html#g-fingerlegato","f":["Fingerlegato"]},
  "g-fingersatz": {"t":"Fingersatz","d":"Ein Fingersatz gibt mit Zahlen über den Noten an, welcher Finger eine Taste spielt: 1 = Daumen, 2 = Zeigefinger, 3 = Mittelfinger, 4 = Ringfinger, 5 = kleiner Finger.","n":1,"h":"kap01-klaviatur.html#g-fingersatz","f":["Fingersatz","Fingersätze","Fingersätzen","Fingersatzes"]},
  "g-fingerstaccato": {"t":"Fingerstaccato","d":"Beim Fingerstaccato zieht sich der Finger nach dem Anschlag schnell zur Handfläche zurück. Es eignet sich für leise, schnelle, leichte Stellen.","n":10,"h":"kap10-vortrag.html#g-fingerstaccato","f":["Fingerstaccato"]},
  "g-fitts-gesetz": {"t":"Fitts’sches Gesetz","d":"Das Fitts’sche Gesetz beschreibt, dass eine zielgerichtete Bewegung umso ungenauer wird, je schneller sie ausgeführt wird. Geschwindigkeit und Genauigkeit stehen in einem Tauschverhältnis.","n":47,"h":"kap47-ueben.html#g-fitts-gesetz","f":["Fitts’sches Gesetz","Fitts’sche Gesetz","Fitts’schen Gesetz","Fitts’schen Gesetzes"]},
  "g-folia": {"t":"Folia","d":"Die Folia ist ein Akkordmodell in Moll aus dem 16. und 17. Jahrhundert, über das Komponisten von Corelli bis Rachmaninow Variationen geschrieben haben.","n":18,"h":"kap18-pop-progressionen.html#g-folia","f":["Folia"]},
  "g-fonte": {"t":"Fonte","d":"Fonte („Quelle“) ist eine fallende, zweigliedrige Sequenz mit Zwischendominanten, in C-Dur A7 – Dm – G7 – C. Das Modell wird einen Ganzton tiefer wiederholt.","n":26,"h":"kap26-sequenzen.html#g-fonte","f":["Fonte"]},
  "g-formenlehre": {"t":"Formenlehre","d":"Die Formenlehre beschreibt, wie Musikstücke gegliedert sind.","n":39,"h":"kap39-bausteine.html#g-formenlehre","f":["Formenlehre"]},
  "g-forte": {"t":"forte (f)","d":"Forte (abgekürzt f) ist die Dynamikangabe für laut. ff (fortissimo) heißt sehr laut, mf (mezzoforte) mäßig laut.","n":10,"h":"kap10-vortrag.html#g-forte","f":["forte","fortissimo","mezzoforte"]},
  "g-fortsetzung": {"t":"Fortsetzung (Satz)","d":"Die Fortsetzung ist die zweite Hälfte eines Satzes (Themenform), meist Takt 5–8. Die Einheiten werden kürzer, die Ereignisse dichter, und am Ende steht eine Kadenz.","n":39,"h":"kap39-bausteine.html#g-fortsetzung","f":[]},
  "g-franzoesischer-sextakkord": {"t":"französischer Sextakkord","d":"Der französische Sextakkord (Fr+6) ist der übermäßige Sextakkord mit zusätzlicher 2. Stufe, in c-Moll as – c – d – fis. Er enthält zwei Tritoni, klingt scharf und führt direkt zur Dominante.","n":25,"h":"kap25-chromatische-akkorde.html#g-franzoesischer-sextakkord","f":["französischer Sextakkord","französische Sextakkord","französischen Sextakkord"]},
  "g-frequenz": {"t":"Frequenz","d":"Die Zahl der Schwingungen pro Sekunde heißt Frequenz und wird in Hertz (Hz) gemessen.","n":5,"h":"kap05-intervalle.html#g-frequenz","f":["Frequenz","Frequenzen","Hertz"]},
  "g-fuge": {"t":"Fuge","d":"Eine Fuge ist ein mehrstimmiges Stück, das aus einem einzigen kurzen Thema entwickelt wird.","n":38,"h":"kap38-fuge.html#g-fuge","f":["Fuge","Fugen"]},
  "g-fugenthema": {"t":"Fugenthema","d":"Das Thema einer Fuge (auch Subjekt oder Dux) ist die Melodie, aus der die Fuge entwickelt wird. Beim ersten Erklingen steht es in der Grundtonart.","n":38,"h":"kap38-fuge.html#g-fugenthema","f":["Fugenthema","Fugenthemas","Dux","Subjekt"]},
  "g-fundamentalbass": {"t":"Fundamentalbass","d":"Der Fundamentalbass ist nach Jean-Philippe Rameau die Folge der Akkordgrundtöne, unabhängig von der tatsächlich gespielten Basslinie.","n":26,"h":"kap26-sequenzen.html#g-fundamentalbass","f":["Fundamentalbass","Fundamentalbasses"]},
  "g-fuenf-finger-lage": {"t":"Fünf-Finger-Lage","d":"In der Fünf-Finger-Lage liegt jeder Finger einer Hand auf einer eigenen, benachbarten weißen Taste, zum Beispiel rechts der Daumen auf c' und der kleine Finger auf g'.","n":1,"h":"kap01-klaviatur.html#g-fuenf-finger-lage","f":["Fünf-Finger-Lage"]},
  "g-fuenftonraum": {"t":"Fünftonraum","d":"Ein Fünftonraum besteht aus den ersten fünf Tönen einer Tonleiter, in Dur Ganz – Ganz – Halb – Ganz. Jeder Finger liegt auf einer eigenen Taste, ein Daumenuntersatz ist nicht nötig.","n":6,"h":"kap06-dur.html#g-fuenftonraum","f":["Fünftonraum","Fünftonräume","Fünftonräumen","Dur-Fünftonraum","Dur-Fünftonräume"]},
  "g-funktion": {"t":"Funktion","d":"Die Funktion eines Akkords ist seine Rolle in der Tonart. Die drei Funktionen sind Tonika (Ruhe), Subdominante (Wegbewegung) und Dominante (Spannung).","n":14,"h":"kap14-funktionen.html#g-funktion","f":["Funktion","Funktionen"]},
  "g-funktionstheorie": {"t":"Funktionstheorie","d":"Die Funktionstheorie benennt Akkorde nach ihrer Rolle in der Tonart, mit Symbolen wie T, S, D, Tp oder Sp. Sie geht auf Hugo Riemann zurück und ist vor allem im deutschsprachigen Raum verbreitet.","n":14,"h":"kap14-funktionen.html#g-funktionstheorie","f":["Funktionstheorie"]},
  "g-g-schluessel": {"t":"G-Schlüssel","d":"G-Schlüssel ist ein anderer Name für den Violinschlüssel. Er ist aus dem Buchstaben G entstanden und legt fest, auf welcher Linie das g' steht.","n":2,"h":"kap02-notenschrift.html#g-g-schluessel","f":["G-Schlüssel"]},
  "g-ganze-note": {"t":"Ganze Note","d":"Die Ganze Note ist der Ausgangspunkt der Notenwerte. Sie dauert so lang wie zwei Halbe oder vier Viertel und wird als hohle Note ohne Hals geschrieben.","n":3,"h":"kap03-rhythmus.html#g-ganze-note","f":["Ganze Note","Ganzen Note","Ganze Noten","Ganzen Noten"]},
  "g-ganzschluss": {"t":"Ganzschluss","d":"Der Ganzschluss (auch authentischer Schluss) ist die Verbindung V–I oder V7–I am Ende einer Phrase.","n":16,"h":"kap16-kadenzen.html#g-ganzschluss","f":["Ganzschluss","Ganzschlüsse","authentischer Schluss"]},
  "g-ganztaktpause": {"t":"Ganztaktpause","d":"Die Ganztaktpause ist die ganze Pause in ihrer zweiten Bedeutung: Sie steht für einen ganzen Takt Stille, egal wie lang der Takt ist. Sie hängt unter der vierten Linie.","n":3,"h":"kap03-rhythmus.html#g-ganztaktpause","f":["Ganztaktpause","Ganztaktpausen"]},
  "g-ganzton": {"t":"Ganzton","d":"Ein Ganzton ist der Abstand aus zwei Halbtönen, zum Beispiel c–d oder e–fis.","n":1,"h":"kap01-klaviatur.html#g-ganzton","f":["Ganzton","Ganztöne","Ganztönen","Ganztons"]},
  "g-ganzton-halbton-leiter": {"t":"Ganzton-Halbton-Leiter","d":"Die Ganzton-Halbton-Leiter (auch verminderte oder oktatonische Skala) wechselt Ganz- und Halbtöne ab, zum Beispiel c, d, es, f, ges, as, a, h. Sie hat acht Töne, und es gibt nur drei verschiedene.","n":9,"h":"kap09-weitere-skalen.html#g-ganzton-halbton-leiter","f":["Ganzton-Halbton-Leiter","Ganzton-Halbton-Skala","oktatonische Skala","oktatonischen Skala"]},
  "g-ganztonleiter": {"t":"Ganztonleiter","d":"Die Ganztonleiter besteht nur aus Ganztönen und hat sechs Töne, etwa c, d, e, fis, gis, ais. Sie ist völlig gleichmäßig gebaut, hat keinen Grundton und existiert nur in zwei Lagen.","n":9,"h":"kap09-weitere-skalen.html#g-ganztonleiter","f":["Ganztonleiter","Ganztonleitern"]},
  "g-gap-fill": {"t":"gap fill","d":"Gap fill heißt das Muster, dass eine Melodie nach einem großen Sprung oft in die Gegenrichtung zurückgeht und die entstandene Lücke füllt.","n":19,"h":"kap19-nichtakkordtoene.html#g-gap-fill","f":["gap fill"]},
  "g-gattung": {"t":"Gattung","d":"Eine Gattung ist eine der fünf Lernstufen des Kontrapunkts nach Fux. Gegen einen Cantus firmus in ganzen Noten bekommt die Gegenstimme von Gattung zu Gattung neue rhythmische Möglichkeiten.","n":34,"h":"kap34-kontrapunkt-1.html#g-gattung","f":["Gattungen"]},
  "g-gavotte": {"t":"Gavotte","d":"Die Gavotte ist ein barocker Tanz im geraden Takt und mäßigen Tempo, der mit einem halbtaktigen Auftakt beginnt.","n":40,"h":"kap40-liedformen.html#g-gavotte","f":["Gavotten","Gavotte"]},
  "g-gegenbewegung": {"t":"Gegenbewegung","d":"Bei Gegenbewegung steigt eine Stimme, während die andere fällt. Diese Bewegungsart trennt zwei Stimmen am deutlichsten.","n":33,"h":"kap33-stimmfuehrung.html#g-gegenbewegung","f":["Gegenbewegung"]},
  "g-gegenklang": {"t":"Gegenklang","d":"Der Gegenklang (g) ist in Dur der Mollakkord eine große Terz über dem Hauptakkord.","n":14,"h":"kap14-funktionen.html#g-gegenklang","f":["Gegenklang","Gegenklänge","Tonikagegenklang","Subdominantgegenklang"]},
  "g-gegenleitton": {"t":"Gegenleitton","d":"Ein Gegenleitton liegt einen Halbton über seinem Zielton und strebt abwärts zu ihm, als Gegenstück zum aufwärts strebenden Leitton. In C-Dur zieht etwa as zur Quinte g.","n":23,"h":"kap23-modale-mischung.html#g-gegenleitton","f":["Gegenleitton","Gegenleittöne","Gegenleittons"]},
  "g-gegenparallele": {"t":"Gegenparallele","d":"Gegenparallelen entstehen, wenn zwei Stimmen in Gegenbewegung von einer Quinte in die nächste Quinte oder von einer Oktave in die nächste Oktave gehen. Im strengen Satz sind sie verboten.","n":33,"h":"kap33-stimmfuehrung.html#g-gegenparallele","f":["Gegenparallele","Gegenparallelen"]},
  "g-gegenstimme": {"t":"Gegenstimme","d":"Eine Gegenstimme ist eine eigenständige Melodie, die zu einer gegebenen Stimme erfunden wird und mit ihr zusammenklingt. Im Kontrapunkt ist es die Stimme, die zum Cantus firmus geschrieben wird.","n":34,"h":"kap34-kontrapunkt-1.html#g-gegenstimme","f":["Gegenstimme","Gegenstimmen"]},
  "g-gemeinsames-schicksal": {"t":"gemeinsames Schicksal","d":"Das Gestaltprinzip des gemeinsamen Schicksals besagt, dass Wahrnehmung zusammenfasst, was sich gemeinsam bewegt. Zwei Stimmen in Parallelbewegung hört das Ohr deshalb leicht als eine Linie.","n":33,"h":"kap33-stimmfuehrung.html#g-gemeinsames-schicksal","f":["gemeinsames Schicksal","gemeinsamen Schicksals"]},
  "g-generalbass": {"t":"Generalbass","d":"Der Generalbass ist eine Spielpraxis der Barockzeit. Notiert ist nur die Basslinie mit kleinen Ziffern, und der Spieler ergänzt darüber die passenden Akkorde.","n":12,"h":"kap12-umkehrungen.html#g-generalbass","f":["Generalbass"]},
  "g-gerundet": {"t":"gerundete zweiteilige Form","d":"Die gerundete zweiteilige Form ist eine zweiteilige Form, deren Teil B am Ende den Anfang von A wieder aufgreift, jetzt in der Grundtonart. Sie gilt als Vorstufe der dreiteiligen Form und der Sonatenform.","n":40,"h":"kap40-liedformen.html#g-gerundet","f":["gerundete zweiteilige Form","gerundeten zweiteiligen Form","gerundete Form"]},
  "g-geschlecht": {"t":"Geschlecht","d":"Das Geschlecht (Tongeschlecht) gibt an, ob ein Akkord oder eine Tonart Dur oder Moll ist. Im Akkordsymbol steht für Moll ein m hinter dem Grundton, für Dur steht nichts.","n":17,"h":"kap17-leadsheets.html#g-geschlecht","f":["Geschlecht","Tongeschlecht","Tongeschlechts","Tongeschlechter"]},
  "g-gigue": {"t":"Gigue","d":"Die Gigue ist ein schneller barocker Tanz, meist im 6/8- oder 12/8-Takt. In der Suite steht sie oft am Schluss.","n":40,"h":"kap40-liedformen.html#g-gigue","f":["Giguen","Gigue"]},
  "g-gleichbewegung": {"t":"Gleichbewegung","d":"Bei Gleichbewegung (auch gerade Bewegung) gehen zwei Stimmen in dieselbe Richtung, aber das Intervall zwischen ihnen ändert sich.","n":33,"h":"kap33-stimmfuehrung.html#g-gleichbewegung","f":["Gleichbewegung","gerade Bewegung"]},
  "g-gleichstufig": {"t":"gleichstufige Stimmung","d":"In der gleichstufigen Stimmung wird die Oktave in zwölf exakt gleiche Halbtöne geteilt. So klingt jede Tonart gleich gut, aber außer der Oktave ist kein Intervall ganz rein.","n":5,"h":"kap05-intervalle.html#g-gleichstufig","f":["gleichstufige Stimmung","gleichstufigen Stimmung","gleichstufig","gleichstufige","gleichstufigen"]},
  "g-grave": {"t":"Grave","d":"Grave (italienisch „schwer, ernst“) ist die langsamste übliche Tempobezeichnung, ungefähr ♩ = 25–45.","n":4,"h":"kap04-takt.html#g-grave","f":["Grave"]},
  "g-gregorianischer-choral": {"t":"gregorianischer Choral","d":"Der gregorianische Choral ist der einstimmige Gesang der christlichen Kirche des Mittelalters. Aus ihm stammen die Kirchentonarten.","n":24,"h":"kap24-modi.html#g-gregorianischer-choral","f":["gregorianischer Choral","gregorianische Choral","gregorianischen Choral"]},
  "g-groove": {"t":"Groove","d":"Groove ist das rhythmische Gefühl eines Stücks, das zum Mitbewegen einlädt. Er entsteht aus einem stabilen Puls, gezielten Betonungen und Synkopen.","n":4,"h":"kap04-takt.html#g-groove","f":["Grooves","Groove"]},
  "g-gross-klein": {"t":"groß und klein","d":"Groß und klein heißen die zwei Normalformen von Sekunde, Terz, Sexte und Septime. Die kleine Form ist einen Halbton kleiner als die große, etwa kleine Terz c–es (3 Halbtöne) und große Terz c–e (4 Halbtöne).","n":5,"h":"kap05-intervalle.html#g-gross-klein","f":[]},
  "g-grosse-oktave": {"t":"große Oktave","d":"Die große Oktave ist der Oktavbereich von C bis H (wissenschaftlich C2 bis B2). Ihre Töne schreibt man in Helmholtz-Schreibweise mit Großbuchstaben.","n":1,"h":"kap01-klaviatur.html#g-grosse-oktave","f":["große Oktave","großen Oktave"]},
  "g-grosser-septakkord": {"t":"großer Septakkord","d":"Der große Septakkord ist ein Durdreiklang mit großer Septime, zum Beispiel Cmaj7 = c–e–g–h. Er klingt weich und schwebend.","n":15,"h":"kap15-septakkorde.html#g-grosser-septakkord","f":["großer Septakkord","große Septakkord","Major-Sept"]},
  "g-grosses-system": {"t":"großes System","d":"Das große System (englisch grand staff) verbindet ein Notensystem im Violinschlüssel und eines im Bassschlüssel mit einer geschweiften Klammer. So wird Klaviermusik notiert.","n":2,"h":"kap02-notenschrift.html#g-grosses-system","f":["großes System","große System","großen System","großen Systems"]},
  "g-ground": {"t":"Ground","d":"Ground hieß in England ein ständig wiederholter Bass, über dem ein Stück aufgebaut ist, etwa in Henry Purcells „When I Am Laid in Earth“.","n":18,"h":"kap18-pop-progressionen.html#g-ground","f":["Ground"]},
  "g-grundstellung": {"t":"Grundstellung","d":"Ein Akkord steht in Grundstellung, wenn sein Grundton der tiefste Ton ist. Beim Dreiklang liegen darüber Terz und Quinte, etwa c–e–g.","n":12,"h":"kap12-umkehrungen.html#g-grundstellung","f":["Grundstellung","Grundstellungen"]},
  "g-grundton": {"t":"Grundton","d":"Der Grundton ist der Ton, auf dem eine Tonleiter beginnt und endet und nach dem sie benannt ist, etwa c in C-Dur.","n":6,"h":"kap06-dur.html#g-grundton","f":["Grundton","Grundtöne","Grundtönen","Grundtons"]},
  "g-grundton-akkord": {"t":"Grundton (Akkord)","d":"Der Grundton eines Akkords ist der unterste Ton seiner Terzschichtung, bei c–e–g also c. Er gibt dem Akkord den Namen, auch wenn er nicht im Bass liegt.","n":11,"h":"kap11-dreiklaenge.html#g-grundton-akkord","f":["Grundton","Grundtöne","Grundtönen","Grundtons"]},
  "g-grundtonart": {"t":"Grundtonart","d":"Die Grundtonart ist die Haupttonart eines Stücks. In ihr beginnt und endet es meist.","n":22,"h":"kap22-modulation.html#g-grundtonart","f":["Grundtonarten","Grundtonart"]},
  "g-guide-tones": {"t":"Guide Tones","d":"Guide Tones sind Terz und Septime eines Akkords. Sie entscheiden über Dur oder Moll und über die Funktion und bleiben deshalb in fast jedem Voicing erhalten.","n":27,"h":"kap27-optionstoene.html#g-guide-tones","f":["Guide Tones","Guide Tone","Leitlinienton","Leitlinientöne"]},
  "g-gute-fortsetzung": {"t":"gute Fortsetzung","d":"Die gute Fortsetzung ist ein Prinzip der Gestaltpsychologie. Elemente, die sich in eine glatte Bahn fügen, werden als Einheit wahrgenommen, deshalb hört das Ohr schrittweise Töne als zusammenhängende Linie.","n":19,"h":"kap19-nichtakkordtoene.html#g-gute-fortsetzung","f":["gute Fortsetzung","guten Fortsetzung"]},
  "g-halbe-note": {"t":"Halbe Note","d":"Die Halbe (halbe Note) dauert halb so lang wie eine Ganze, also zwei Viertel. Sie wird als hohle Note mit Hals geschrieben.","n":3,"h":"kap03-rhythmus.html#g-halbe-note","f":["Halbe Note","Halbe Noten","halben Note","halben Noten"]},
  "g-halbpedal": {"t":"Halbpedal","d":"Beim Halbpedal ist das Pedal nur so weit getreten, dass die Dämpfer die Saiten noch leicht berühren. Sie dämpfen dann nur teilweise, die langen Basssaiten stärker als die hohen.","n":45,"h":"kap45-pedal.html#g-halbpedal","f":["Halbpedal"]},
  "g-halbschluss": {"t":"Halbschluss","d":"Ein Halbschluss ist ein Phrasenende auf der Dominante, etwa I–V oder IV–V. Weil die Dominante Spannung trägt, bleibt die Musik offen wie nach einem Komma.","n":16,"h":"kap16-kadenzen.html#g-halbschluss","f":["Halbschluss"]},
  "g-halbton": {"t":"Halbton","d":"Ein Halbton ist der kleinste Schritt auf dem Klavier, von einer Taste zur unmittelbar benachbarten, zum Beispiel c–cis oder e–f.","n":1,"h":"kap01-klaviatur.html#g-halbton","f":["Halbton","Halbtöne","Halbtönen","Halbtons"]},
  "g-halbton-ganzton-skala": {"t":"Halbton-Ganzton-Skala","d":"Die Halbton-Ganzton-Skala wechselt regelmäßig Halbton- und Ganztonschritte ab, beginnend mit dem Halbton, über G also g–as–b–h–cis–d–e–f. Sie hat acht Töne und passt zu Dominanten mit ♭9 und natürlicher 13.","n":30,"h":"kap30-akkordskalen.html#g-halbton-ganzton-skala","f":["Halbton-Ganzton-Skala","Halbton-Ganzton-Skalen"]},
  "g-halbvermindert": {"t":"halbverminderter Septakkord","d":"Der halbverminderte Septakkord ist ein verminderter Dreiklang mit kleiner Septime, zum Beispiel Cø7 = c–es–ges–b. „Halb“ vermindert heißt er, weil nur der Dreiklang vermindert ist.","n":15,"h":"kap15-septakkorde.html#g-halbvermindert","f":["halbverminderter Septakkord","halbverminderte Septakkord","halbvermindert","halbverminderte","halbverminderten"]},
  "g-haltebogen": {"t":"Haltebogen","d":"Ein Haltebogen verbindet zwei Noten gleicher Tonhöhe. Die zweite Note wird nicht neu angeschlagen, ihre Dauer wird zur ersten addiert.","n":3,"h":"kap03-rhythmus.html#g-haltebogen","f":["Haltebogen","Haltebögen","Haltebogens"]},
  "g-haltepedal": {"t":"Haltepedal","d":"Das Haltepedal ist das rechte Pedal von Flügel und Klavier. Es hebt alle Dämpfer von den Saiten, sodass angeschlagene Töne auch nach dem Loslassen der Tasten weiterklingen.","n":45,"h":"kap45-pedal.html#g-haltepedal","f":["Haltepedal","Haltepedale","Haltepedals","Dämpferpedal","Fortepedal"]},
  "g-hammerklavier": {"t":"Hammerklavier","d":"Hammerklavier nennt man die frühen Klaviere des 18. und frühen 19. Jahrhunderts, deren Saiten von Hämmern angeschlagen werden. Sie klangen leiser und verklangen schneller als ein moderner Flügel.","n":45,"h":"kap45-pedal.html#g-hammerklavier","f":["Hammerklavieren","Hammerklaviere","Hammerklaviers","Hammerklavier"]},
  "g-handgelenkstaccato": {"t":"Handgelenkstaccato","d":"Beim Handgelenkstaccato federt die Hand aus dem lockeren Handgelenk, wie beim Abschütteln von Wassertropfen. Es eignet sich für mittelschnelle Staccati, Akkorde und Oktaven.","n":10,"h":"kap10-vortrag.html#g-handgelenkstaccato","f":["Handgelenkstaccato"]},
  "g-harmonischer-rhythmus": {"t":"harmonischer Rhythmus","d":"Der harmonische Rhythmus ist das Tempo der Akkordwechsel, also wie oft in einem Stück die Harmonie wechselt.","n":39,"h":"kap39-bausteine.html#g-harmonischer-rhythmus","f":["harmonischer Rhythmus","harmonische Rhythmus","harmonischen Rhythmus"]},
  "g-harmonisches-intervall": {"t":"harmonisches Intervall","d":"Ein harmonisches Intervall entsteht, wenn zwei Töne gleichzeitig erklingen.","n":5,"h":"kap05-intervalle.html#g-harmonisches-intervall","f":["harmonisches Intervall","harmonischen Intervall","harmonische Intervalle","harmonischen Intervallen"]},
  "g-harmonisches-moll": {"t":"harmonisches Moll","d":"Harmonisches Moll ist natürliches Moll mit um einen Halbton erhöhter 7. Stufe, damit ein Leitton entsteht. In a-Moll wird aus g ein gis, zwischen 6. und 7. Stufe liegt dann eine übermäßige Sekunde.","n":8,"h":"kap08-moll.html#g-harmonisches-moll","f":["harmonisches Moll","harmonischen Moll","harmonischem Moll"]},
  "g-harmonisieren": {"t":"harmonisieren","d":"Zu einer Melodie passende Akkorde zu finden, heißt harmonisieren.","n":19,"h":"kap19-nichtakkordtoene.html#g-harmonisieren","f":["harmonisieren","harmonisiert","harmonisiere","Harmonisierung"]},
  "g-hauptdreiklaenge": {"t":"Hauptdreiklang","d":"Die Hauptdreiklänge einer Durtonart sind die Durakkorde auf der I., IV. und V. Stufe, in C-Dur also C, F und G. Zusammen enthalten sie alle sieben Töne der Tonleiter.","n":13,"h":"kap13-stufen.html#g-hauptdreiklaenge","f":["Hauptdreiklang","Hauptdreiklänge","Hauptdreiklängen","Hauptakkord","Hauptakkorde"]},
  "g-hauptsatz": {"t":"Hauptsatz","d":"Der Hauptsatz ist in der Sonatenform der Abschnitt mit dem ersten Thema in der Grundtonart. Er eröffnet die Exposition und kehrt zu Beginn der Reprise wieder.","n":41,"h":"kap41-sonate.html#g-hauptsatz","f":["Hauptsatz"]},
  "g-head": {"t":"Head","d":"Der Head ist im Jazz die komponierte Melodie eines Stücks. Sie erklingt am Anfang und am Ende einmal komplett, dazwischen wird über die Akkordfolge improvisiert.","n":42,"h":"kap42-songformen.html#g-head","f":["Head"]},
  "g-helmholtz-schreibweise": {"t":"Helmholtz-Schreibweise","d":"Die nach dem Physiker Hermann von Helmholtz benannte Helmholtz-Schreibweise unterscheidet gleichnamige Töne verschiedener Oktaven durch Groß- und Kleinbuchstaben, Striche und Ziffern (C, c, c', c'').","n":1,"h":"kap01-klaviatur.html#g-helmholtz-schreibweise","f":["Helmholtz-Schreibweise"]},
  "g-hemiole": {"t":"Hemiole","d":"Eine Hemiole (griechisch „anderthalb“) entsteht, wenn Musik kurz zwischen Zweier- und Dreiergruppierung umschaltet, ohne dass sich die Notenwerte ändern. Ein Beispiel sind zwei 3/4-Takte, die wie ein großer 3/2-Takt klingen.","n":4,"h":"kap04-takt.html#g-hemiole","f":["Hemiole","Hemiolen"]},
  "g-hilfslinie": {"t":"Hilfslinie","d":"Hilfslinien (englisch ledger lines) sind kurze Zusatzlinien über oder unter dem Notensystem. Sie nehmen Töne auf, die nicht in die fünf Linien passen.","n":2,"h":"kap02-notenschrift.html#g-hilfslinie","f":["Hilfslinie","Hilfslinien"]},
  "g-hm5": {"t":"HM5","d":"HM5 ist die Tonleiter ab der fünften Stufe von harmonisch Moll, über G also g–as–h–c–d–es–f. Sie passt zu Dominanten, die sich nach Moll auflösen, und heißt auch Mixolydisch ♭9 ♭13 oder Phrygisch-Dur.","n":30,"h":"kap30-akkordskalen.html#g-hm5","f":["HM5","Mixolydisch ♭9 ♭13","Phrygisch-Dur"]},
  "g-hook": {"t":"Hook","d":"Die Hook ist die eingängigste Stelle eines Songs, die „hängen bleibt“. Meist steckt sie im Refrain, oft in der Zeile mit dem Titel, manchmal in einem Instrumentalriff.","n":42,"h":"kap42-songformen.html#g-hook","f":["Hook"]},
  "g-hybrides-thema": {"t":"hybrides Thema","d":"Ein hybrides Thema mischt Merkmale von Periode und Satz, zum Beispiel eine Periode, deren Nachsatz wie die Fortsetzung eines Satzes gebaut ist. Der Begriff stammt von William Caplin.","n":39,"h":"kap39-bausteine.html#g-hybrides-thema","f":["hybride Themen","hybrides Thema"]},
  "g-hypermetrum": {"t":"Hypermetrum","d":"Das Hypermetrum setzt den Wechsel von schwer und leicht über die Taktebene hinaus fort. Takte gruppieren sich zu schweren und leichten Takten, Zweitakter zu Viertaktern, Viertakter zu Achttaktern.","n":39,"h":"kap39-bausteine.html#g-hypermetrum","f":["Hypermetrum"]},
  "g-ii-v-i": {"t":"II–V–I","d":"Die II–V–I (gesprochen „zwei-fünf-eins“, englisch two-five-one) besteht aus drei leitereigenen Septakkorden einer Dur-Tonart: der II., V. und I.","n":28,"h":"kap28-ii-v-i.html#g-ii-v-i","f":["II–V–I","II–V–Is","II–V–i","II–V","II–Vs"]},
  "g-imitation": {"t":"Imitation","d":"Imitation heißt, dass eine Stimme eine Melodie wiederholt, die eine andere Stimme kurz vorher gespielt hat, auf derselben oder einer anderen Tonhöhe.","n":38,"h":"kap38-fuge.html#g-imitation","f":["Imitation","Imitationen"]},
  "g-improvisieren": {"t":"Improvisieren","d":"Improvisieren heißt, Musik im Moment zu erfinden.","n":49,"h":"kap49-nach-gehoer.html#g-improvisieren","f":["Improvisieren","Improvisierens","Improvisation","Improvisationen","improvisiert","improvisierte","improvisierten","improvisiere"]},
  "g-intervall": {"t":"Intervall","d":"Ein Intervall (lateinisch intervallum, „Zwischenraum“) beschreibt, wie weit zwei Töne auseinanderliegen.","n":5,"h":"kap05-intervalle.html#g-intervall","f":["Intervall","Intervalle","Intervallen","Intervalls"]},
  "g-intonieren": {"t":"Intonieren","d":"Intonieren heißt, den Hammerfilz eines Klaviers mit Nadeln zu lockern oder zu härten. So stimmt der Klavierbauer ab, wie weich oder hell das Instrument klingt.","n":43,"h":"kap43-technik.html#g-intonieren","f":["~Intonieren","~intoniert"]},
  "g-intonieren-tonhoehe": {"t":"intonieren (Tonhöhe)","d":"Intonieren heißt beim Singen oder Spielen, die Tonhöhe genau zu treffen. Sänger und Bläser können dabei feiner abstufen als das Klavier mit seinen festen Tönen.","n":9,"h":"kap09-weitere-skalen.html#g-intonieren-tonhoehe","f":["intonierten","intonieren","intonierte","Intonation","intoniert"]},
  "g-intro": {"t":"Intro","d":"Das Intro ist der Anfangsteil eines Songs. Es stellt Tonart, Tempo und Klangwelt vor, oft mit Material aus dem Refrain.","n":42,"h":"kap42-songformen.html#g-intro","f":["Intro"]},
  "g-ionisch": {"t":"Ionisch","d":"Ionisch ist der Modus, der auf den weißen Tasten von c bis c' entsteht. Er ist identisch mit der Dur-Tonleiter.","n":24,"h":"kap24-modi.html#g-ionisch","f":["ionisch","ionische","ionischen"]},
  "g-italienischer-sextakkord": {"t":"italienischer Sextakkord","d":"Der italienische Sextakkord (It+6) ist der übermäßige Sextakkord aus nur drei Tönen: Bass auf der erniedrigten 6. Stufe, dazu Grundton und erhöhte 4. Stufe, in c-Moll as – c – fis. Er führt direkt zur Dominante.","n":25,"h":"kap25-chromatische-akkorde.html#g-italienischer-sextakkord","f":["italienischer Sextakkord","italienische Sextakkord","italienischen Sextakkord"]},
  "g-jazz-blues": {"t":"Jazz-Blues","d":"Der Jazz-Blues ist ein 12-Takt-Blues, dessen Gerüst mit II–V-Verbindungen und Zwischendominanten gefüllt ist. Die Takte 11–12 bilden meist einen Turnaround I–VI–II–V.","n":42,"h":"kap42-songformen.html#g-jazz-blues","f":["Jazz-Blues"]},
  "g-jazzstandard": {"t":"Jazzstandard","d":"Ein Jazzstandard ist ein bekanntes Stück aus dem gemeinsamen Repertoire von Jazzmusikern, das in vielen Fassungen gespielt wird. Viele stammen aus Musicals und Filmen der 1920er- bis 1950er-Jahre.","n":17,"h":"kap17-leadsheets.html#g-jazzstandard","f":["Jazz-Standards","Jazzstandards","Jazz-Standard","Jazzstandard"]},
  "g-kadenz": {"t":"Kadenz","d":"Eine Kadenz ist eine Akkordfolge, die zur Tonika führt und die Tonart festigt, meist am Ende eines Abschnitts. Ihre Grundform ist I–IV–V–I, in Funktionen T–S–D–T.","n":14,"h":"kap14-funktionen.html#g-kadenz","f":["Kadenz","Kadenzen"]},
  "g-kanon": {"t":"Kanon","d":"Wird eine Melodie von Anfang bis Ende streng nachgeahmt, entsteht ein Kanon.","n":38,"h":"kap38-fuge.html#g-kanon","f":["Kanon","Kanons"]},
  "g-kantate": {"t":"Kantate","d":"Eine Kantate ist ein mehrteiliges Werk für Gesang und Instrumente aus Arien, Rezitativen und Chören. Bach schrieb viele Kantaten für den Gottesdienst.","n":37,"h":"kap37-choralsatz.html#g-kantate","f":["Kantaten","Kantate"]},
  "g-kirchentonart": {"t":"Kirchentonart","d":"Kirchentonart ist der traditionelle Name der Modi wie Dorisch, Phrygisch oder Mixolydisch. Der Name kommt vom einstimmigen Kirchengesang des Mittelalters, aus dem diese Tonleitern stammen.","n":24,"h":"kap24-modi.html#g-kirchentonart","f":["Kirchentonart","Kirchentonarten"]},
  "g-klausel": {"t":"Klausel","d":"Eine Klausel ist die typische Schlussformel einer einzelnen Stimme am Phrasenende, wie sie die mehrstimmige Musik des 15. und 16. Jahrhunderts verwendete, etwa die Diskantklausel h → c.","n":16,"h":"kap16-kadenzen.html#g-klausel","f":["Klausel","Klauseln"]},
  "g-klaviersatz": {"t":"Klaviersatz","d":"Ein Klaviersatz ist eine ausführliche Klavierfassung eines Stücks, in der die Noten für beide Hände ausgeschrieben sind.","n":17,"h":"kap17-leadsheets.html#g-klaviersatz","f":["Klaviersatz"]},
  "g-kleine-oktave": {"t":"kleine Oktave","d":"Die kleine Oktave ist der Oktavbereich von c bis h (wissenschaftlich C3 bis B3) direkt unter dem mittleren C. Ihre Töne schreibt man mit Kleinbuchstaben ohne Strich.","n":1,"h":"kap01-klaviatur.html#g-kleine-oktave","f":["kleine Oktave","kleinen Oktave"]},
  "g-konsolidierung": {"t":"Konsolidierung","d":"Konsolidierung ist die Festigung von neu Gelerntem in den Stunden nach dem Üben. Vorher ist das Gelernte noch instabil und leicht störbar.","n":47,"h":"kap47-ueben.html#g-konsolidierung","f":["Konsolidierung"]},
  "g-konsonanz": {"t":"Konsonanz","d":"Eine Konsonanz ist ein Intervall, das ruhig und verschmolzen klingt. Vollkommene Konsonanzen sind reine Prime, Oktave und Quinte, unvollkommene Konsonanzen große und kleine Terz und Sexte.","n":5,"h":"kap05-intervalle.html#g-konsonanz","f":["Konsonanz","Konsonanzen","konsonant","vollkommene Konsonanz","vollkommene Konsonanzen","vollkommenen Konsonanz","vollkommenen Konsonanzen"]},
  "g-kontextinterferenz": {"t":"Kontextinterferenz-Effekt","d":"Der Kontextinterferenz-Effekt beschreibt, dass gemischt statt blockweise geübte Bewegungen langfristig besser behalten und leichter übertragen werden. Während des Übens wirkt das Mischen dagegen zunächst schlechter.","n":47,"h":"kap47-ueben.html#g-kontextinterferenz","f":["Kontextinterferenz-Effekt","Kontextinterferenz-Effekts","Kontextinterferenz"]},
  "g-kontrafaktur": {"t":"Kontrafaktur","d":"Eine Kontrafaktur ist ein Stück, das die Akkordfolge eines bekannten Stücks übernimmt und darüber eine neue Melodie setzt. Ursprünglich hieß so das Unterlegen eines neuen Textes unter eine bekannte Melodie.","n":32,"h":"kap32-reharmonisierung.html#g-kontrafaktur","f":["Kontrafaktur","Kontrafakturen"]},
  "g-kontraoktave": {"t":"Kontraoktave","d":"Die Kontraoktave ist der Oktavbereich von C1 bis H1 (wissenschaftlich C1 bis B1), direkt unter der großen Oktave.","n":1,"h":"kap01-klaviatur.html#g-kontraoktave","f":["Kontraoktave"]},
  "g-kontrapunkt": {"t":"Kontrapunkt","d":"Kontrapunkt ist die Satztechnik, mehrere eigenständige Stimmen so zu verbinden, dass jede für sich eine gute Melodie ist und alle gut zusammenklingen. Das Wort bezeichnet auch die Gegenstimme selbst.","n":34,"h":"kap34-kontrapunkt-1.html#g-kontrapunkt","f":["Kontrapunkt","Kontrapunkts","Kontrapunkte"]},
  "g-kontrasubjekt": {"t":"Kontrasubjekt","d":"Ein Kontrasubjekt ist eine Gegenstimme, die das Thema einer Fuge bei mehreren Einsätzen gleichbleibend begleitet.","n":38,"h":"kap38-fuge.html#g-kontrasubjekt","f":["Kontrasubjekt","Kontrasubjekts","Kontrasubjekte"]},
  "g-kontur": {"t":"Kontur","d":"Die Kontur einer Melodie ist die Abfolge von „hoch, runter, gleich“, unabhängig von der genauen Größe der Schritte.","n":39,"h":"kap39-bausteine.html#g-kontur","f":["Kontur"]},
  "g-krebs": {"t":"Krebs","d":"Beim Krebs wird ein Motiv rückwärts gespielt, also mit denselben Tönen und Notenwerten in umgekehrter Reihenfolge.","n":39,"h":"kap39-bausteine.html#g-krebs","f":["Krebs"]},
  "g-kreuz": {"t":"Kreuz","d":"Das Kreuz ♯ erhöht einen Ton um einen Halbton. An den Namen wird dabei -is angehängt: c wird zu cis, f zu fis.","n":1,"h":"kap01-klaviatur.html#g-kreuz","f":["Kreuz","Kreuze"]},
  "g-kritische-bandbreite": {"t":"kritische Bandbreite","d":"Die kritische Bandbreite ist die Breite der Frequenzbänder, in die das Gehör Klänge zerlegt. Liegen zwei Töne im selben Band, reiben sie sich und klingen rau. Im Bass sind die Bänder im Verhältnis breiter als in der Mitte.","n":29,"h":"kap29-voicings.html#g-kritische-bandbreite","f":["kritische Bandbreite","kritischen Bandbreite","kritischen Bandbreiten"]},
  "g-lage": {"t":"Lage","d":"Die Lage beschreibt, wie die Oberstimmen eines Akkords über dem Bass verteilt sind. Man unterscheidet enge und weite Lage und nach dem obersten Ton Oktav-, Terz- und Quintlage.","n":12,"h":"kap12-umkehrungen.html#g-lage","f":[]},
  "g-lagenwechsel": {"t":"Lagenwechsel","d":"Ein Lagenwechsel ist eine Verschiebung der Hand auf eine neue Gruppe von Tasten. Ohne Lagenwechsel deckt eine Hand etwa fünf benachbarte Töne ab.","n":44,"h":"kap44-fingersaetze.html#g-lagenwechsel","f":["Lagenwechsel","Lagenwechseln","Lagenwechsels"]},
  "g-larghetto": {"t":"Larghetto","d":"Larghetto (italienisch „etwas breit“) ist eine langsame Tempobezeichnung, etwas schneller als Largo, ungefähr ♩ = 60–66.","n":4,"h":"kap04-takt.html#g-larghetto","f":["Larghetto"]},
  "g-largo": {"t":"Largo","d":"Largo (italienisch „breit“) ist eine sehr langsame Tempobezeichnung, ungefähr ♩ = 40–60.","n":4,"h":"kap04-takt.html#g-largo","f":["Largo"]},
  "g-leadsheet": {"t":"Leadsheet","d":"Ein Leadsheet notiert nur die Melodie in einem einzigen Notensystem, darüber die Akkorde als Akkordsymbole und oft den Liedtext. Die Begleitung gestaltet der Spieler selbst.","n":17,"h":"kap17-leadsheets.html#g-leadsheet","f":["Leadsheet","Leadsheets"]},
  "g-leerweg": {"t":"Leerweg","d":"Der Leerweg ist der erste Teil des Pedalwegs, in dem sich noch keine Dämpfer bewegen. Für das Wechseln brauchst du nur den Bereich danach.","n":45,"h":"kap45-pedal.html#g-leerweg","f":["Leerweg"]},
  "g-legato": {"t":"legato","d":"Legato heißt gebunden, ohne Lücke. Am Klavier lässt man eine Taste erst los, wenn die nächste unten ist. Angezeigt wird es durch einen Bogen über mehreren Noten.","n":10,"h":"kap10-vortrag.html#g-legato","f":["legato"]},
  "g-leichte-zeit": {"t":"leichte Zeit","d":"Leichte Zeiten sind die unbetonten Schläge eines Takts zwischen den schweren Zeiten. Sie führen zum nächsten schweren Schlag hin.","n":4,"h":"kap04-takt.html#g-leichte-zeit","f":["leichte Zeit","leichten Zeit","leichte Zeiten","leichten Zeiten","leichter Zeit"]},
  "g-leitereigen": {"t":"leitereigen","d":"Leitereigen heißen Töne und Akkorde, die nur aus Tönen der Tonleiter einer Tonart bestehen. In C-Dur sind die leitereigenen Dreiklänge C, Dm, Em, F, G, Am und H°.","n":13,"h":"kap13-stufen.html#g-leitereigen","f":["leitereigen","leitereigene","leitereigenen"]},
  "g-leitlinie": {"t":"Leitlinie","d":"Leitlinien sind die Stimmen aus Terz und Septime, die sich durch eine Akkordfolge ziehen. Im Quintfall geht die Septime einen Schritt abwärts zur Terz des nächsten Akkords, die Terz bleibt liegen und wird zur Septime.","n":28,"h":"kap28-ii-v-i.html#g-leitlinie","f":["Leitlinie","Leitlinien"]},
  "g-leitnote": {"t":"Leitnote","d":"Leitnoten sind wenige Noten, die du im Notensystem sofort erkennst, etwa c', g' und f. Von ihnen aus findest du andere Noten, indem du in Intervallen weiterzählst.","n":48,"h":"kap48-blattspiel.html#g-leitnote","f":["Leitnote","Leitnoten"]},
  "g-leitton": {"t":"Leitton","d":"Der Leitton ist die 7. Stufe der Dur-Tonleiter. Er liegt einen Halbton unter der Tonika und strebt zu ihr, in C-Dur das h.","n":6,"h":"kap06-dur.html#g-leitton","f":["Leitton","Leittöne","Leittons","Leittönen"]},
  "g-liegender-ton": {"t":"liegender Ton","d":"Ein liegender Ton oder umgekehrter Orgelpunkt ist ein lang ausgehaltener Ton in einer Oberstimme, unter dem die Harmonien wechseln.","n":26,"h":"kap26-sequenzen.html#g-liegender-ton","f":["liegender Ton","liegenden Ton","umgekehrter Orgelpunkt","umgekehrten Orgelpunkt"]},
  "g-line-cliche": {"t":"Line Cliché","d":"Ein Line Cliché ist eine chromatisch steigende oder fallende Stimme über einem liegenden Akkord, etwa a – gis – g – fis über a-Moll (Am – Am(maj7) – Am7 – Am6).","n":25,"h":"kap25-chromatische-akkorde.html#g-line-cliche","f":["Line Cliché"]},
  "g-lokrisch": {"t":"Lokrisch","d":"Lokrisch ist der Modus, der auf den weißen Tasten von h bis h' entsteht. Er klingt wie Moll mit kleiner Sekunde und verminderter Quinte, sein Grundakkord ist vermindert.","n":24,"h":"kap24-modi.html#g-lokrisch","f":["lokrisch","lokrische","lokrischen"]},
  "g-low-interval-limits": {"t":"low interval limits","d":"Low interval limits sind Untergrenzen, unterhalb derer ein Intervall im Bass matschig klingt. Arrangeure nutzen solche Tabellen, um tiefe Akkorde klar zu halten.","n":29,"h":"kap29-voicings.html#g-low-interval-limits","f":["low interval limits"]},
  "g-lydisch": {"t":"Lydisch","d":"Lydisch ist der Modus, der auf den weißen Tasten von f bis f' entsteht. Er klingt wie Dur mit übermäßiger Quarte.","n":24,"h":"kap24-modi.html#g-lydisch","f":["lydisch","lydische","lydischen","lydisches"]},
  "g-lydisch-b7": {"t":"Lydisch ♭7","d":"Lydisch ♭7 ist die vierte Stufe von melodisch Moll, über G also g–a–h–cis–d–e–f. Sie passt zu Dominantakkorden mit ♯11, etwa zu Tritonussubstituten, und heißt auch akustische Skala.","n":30,"h":"kap30-akkordskalen.html#g-lydisch-b7","f":["Lydisch ♭7"]},
  "g-marcato": {"t":"marcato","d":"Marcato (Zeichen: Dach über der Note) heißt stark betont, markiert: ein kräftiger Akzent, meist etwas kürzer gespielt.","n":10,"h":"kap10-vortrag.html#g-marcato","f":["marcato"]},
  "g-mario-kadenz": {"t":"Mario-Kadenz","d":"Mario-Kadenz ist ein englischer Spitzname für den Schluss ♭VI – ♭VII – I, benannt nach der Level-Fanfare von „Super Mario Bros.“ Zwei Dur-Akkorde steigen dabei in Ganztönen zur Tonika auf, in C-Dur As – B – C.","n":23,"h":"kap23-modale-mischung.html#g-mario-kadenz","f":["Mario-Kadenz"]},
  "g-mechanik": {"t":"Mechanik","d":"Zwischen Taste und Saite liegt die Mechanik, ein Hebelwerk aus Holz, Filz und Federn.","n":43,"h":"kap43-technik.html#g-mechanik","f":["Mechanik","Mechaniken"]},
  "g-mediale-zaesur": {"t":"mediale Zäsur","d":"Die mediale Zäsur ist der deutliche Einschnitt am Ende der Überleitung einer Sonatenform, meist ein Halbschluss in der neuen Tonart mit kurzer Pause. Sie kündigt den Seitensatz an.","n":41,"h":"kap41-sonate.html#g-mediale-zaesur","f":["mediale Zäsur","medialen Zäsur"]},
  "g-mediante": {"t":"Mediante","d":"Die Mediante ist die 3. Stufe einer Tonleiter, in der Mitte zwischen Tonika und Dominante. Sie entscheidet über Dur oder Moll. In C-Dur ist das e.","n":6,"h":"kap06-dur.html#g-mediante","f":["Mediante"]},
  "g-melodisches-intervall": {"t":"melodisches Intervall","d":"Ein melodisches Intervall entsteht, wenn zwei Töne nacheinander erklingen.","n":5,"h":"kap05-intervalle.html#g-melodisches-intervall","f":["melodisches Intervall","melodischen Intervall","melodische Intervalle","melodischen Intervallen"]},
  "g-melodisches-moll": {"t":"melodisches Moll","d":"Melodisches Moll erhöht aufwärts die 6. und 7. Stufe und ist abwärts wie natürliches Moll. Im Jazz wird es in beide Richtungen mit erhöhter 6. und 7. Stufe gespielt und heißt dort auch Jazz-Moll.","n":8,"h":"kap08-moll.html#g-melodisches-moll","f":["melodisches Moll","melodischen Moll","melodischem Moll","Jazz-Moll"]},
  "g-mensuralnotation": {"t":"Mensuralnotation","d":"Die Mensuralnotation ist die Notenschrift, mit der man vom 13. bis zum 16. Jahrhundert mehrstimmige Musik aufschrieb. Aus ihren Werten wie brevis, semibrevis und minima entstanden unsere heutigen Notenwerte.","n":3,"h":"kap03-rhythmus.html#g-mensuralnotation","f":["Mensuralnotation"]},
  "g-mentales-ueben": {"t":"mentales Üben","d":"Beim mentalen Üben gehst du ein Stück nur im Kopf durch. Du hörst es innerlich, stellst dir die Bewegungen vor und siehst die Noten.","n":47,"h":"kap47-ueben.html#g-mentales-ueben","f":["mentales Üben","mentale Üben","mentalen Üben","mental üben"]},
  "g-menuett": {"t":"Menuett","d":"Das Menuett ist ein mäßig bewegter Tanz im 3/4-Takt aus dem 17. und 18. Jahrhundert. In der Klassik ist es oft der dritte Satz einer Sonate oder Sinfonie, in der Form Menuett, Trio, Menuett.","n":4,"h":"kap04-takt.html#g-menuett","f":["Menuetten","Menuetts","Menuette","Menuett"]},
  "g-mere-exposure-effekt": {"t":"Mere-Exposure-Effekt","d":"Der Mere-Exposure-Effekt besagt, dass Menschen Dinge positiver bewerten, je öfter sie ihnen begegnet sind, selbst wenn sie sich an die Begegnung nicht erinnern. Für Musik ist er vielfach bestätigt.","n":18,"h":"kap18-pop-progressionen.html#g-mere-exposure-effekt","f":["Mere-Exposure-Effekt"]},
  "g-metrische-hierarchie": {"t":"metrische Hierarchie","d":"Die metrische Hierarchie ist die Abstufung der Schläge nach Gewicht. Im 4/4-Takt ist die Eins am schwersten, die Drei etwas leichter, Zwei und Vier sind leicht. Innerhalb eines Schlags ist das „und“ leichter als der Schlag.","n":4,"h":"kap04-takt.html#g-metrische-hierarchie","f":["metrische Hierarchie","metrischen Hierarchie"]},
  "g-metronom": {"t":"Metronom","d":"Ein Metronom ist ein Gerät, das gleichmäßige Klicks in einem einstellbaren Tempo erzeugt, angegeben in Schlägen pro Minute. Es macht hörbar, ob man das Tempo hält.","n":4,"h":"kap04-takt.html#g-metronom","f":["Metronom","Metronoms","Metronome","Metronomen"]},
  "g-metronom-treppe": {"t":"Metronom-Treppe","d":"Die Metronom-Treppe ist eine Methode, das Tempo schrittweise zu steigern. Nach drei fehlerfreien Durchgängen erhöhst du um 4 Schläge pro Minute. Gelingt es nicht mehr, gehst du zwei Stufen zurück.","n":47,"h":"kap47-ueben.html#g-metronom-treppe","f":["Metronom-Treppe"]},
  "g-metrum": {"t":"Metrum","d":"Die regelmäßige Ordnung von schweren und leichten Schlägen heißt Metrum.","n":4,"h":"kap04-takt.html#g-metrum","f":["Metrum","Metrums","Metren"]},
  "g-mitschwingen": {"t":"Mitschwingen","d":"Mitschwingen (sympathetische Resonanz) heißt, dass freie Saiten leise mitklingen, wenn ihr Grundton oder ihre Teiltöne mit den Frequenzen eines gespielten Tons übereinstimmen.","n":45,"h":"kap45-pedal.html#g-mitschwingen","f":["Mitschwingen","sympathetische Resonanz","sympathetischen Resonanz"]},
  "g-mittelstimmen": {"t":"Mittelstimme","d":"Mittelstimmen (auch Innenstimmen) sind die Stimmen zwischen der höchsten und der tiefsten Stimme, im vierstimmigen Satz also Alt und Tenor.","n":37,"h":"kap37-choralsatz.html#g-mittelstimmen","f":["Mittelstimme","Mittelstimmen","Innenstimme","Innenstimmen"]},
  "g-mitteltoenig": {"t":"mitteltönige Stimmung","d":"Die mitteltönige Stimmung ist eine ältere Stimmung von Tasteninstrumenten. Die Terzen der gängigen Tonarten sind darin rein, entfernte Tonarten aber unbrauchbar.","n":5,"h":"kap05-intervalle.html#g-mitteltoenig","f":["mitteltönige Stimmung","mitteltönigen Stimmung","mitteltönig","mitteltönige","mitteltönigen"]},
  "g-mittleres-c": {"t":"mittleres C","d":"Das mittlere C ist das c' (wissenschaftlich C4) ungefähr in der Mitte der Klaviatur. Es ist der wichtigste Bezugspunkt, um sich auf den Tasten und in den Noten zu orientieren.","n":1,"h":"kap01-klaviatur.html#g-mittleres-c","f":["mittleres C","mittlere C","mittleren C"]},
  "g-mixolydisch": {"t":"Mixolydisch","d":"Mixolydisch ist der Modus, der auf den weißen Tasten von g bis g' entsteht. Er klingt wie Dur mit kleiner Septime, also Dur ohne Leitton.","n":24,"h":"kap24-modi.html#g-mixolydisch","f":["mixolydisch","mixolydische","mixolydischen"]},
  "g-mixtur": {"t":"Mixtur","d":"Eine Mixtur ist ein Orgelregister, das jedem gespielten Ton parallele Quinten und Oktaven hinzufügt, damit er voller klingt.","n":33,"h":"kap33-stimmfuehrung.html#g-mixtur","f":["Mixtur","Mixturregister","Mixturregistern"]},
  "g-modale-mischung": {"t":"modale Mischung","d":"Modale Mischung heißt, dass ein Stück Akkorde aus der Variante auf demselben Grundton leiht, in Dur meist aus Moll, etwa f-Moll oder As-Dur in C-Dur. Die Tonart bleibt dabei erhalten.","n":23,"h":"kap23-modale-mischung.html#g-modale-mischung","f":["modale Mischung","modalen Mischung","modaler Mischung","Dur-Moll-Mischung","geliehener Akkord","geliehene Akkord","geliehenen Akkord","geliehene Akkorde","geliehenen Akkorde"]},
  "g-modaler-jazz": {"t":"modaler Jazz","d":"Der modale Jazz entstand Ende der 1950er-Jahre, etwa mit dem Album „Kind of Blue“ (1959). Seine Stücke bauen auf Skalen statt auf schnellen Akkordwechseln auf, ein Akkord bleibt oft viele Takte lang liegen.","n":30,"h":"kap30-akkordskalen.html#g-modaler-jazz","f":["modaler Jazz","modalen Jazz","modale Jazz"]},
  "g-modell": {"t":"Modell","d":"Das Modell ist der erste Abschnitt einer Sequenz, also das Muster, das danach auf anderen Tonstufen wiederholt wird.","n":26,"h":"kap26-sequenzen.html#g-modell","f":[]},
  "g-moderato": {"t":"Moderato","d":"Moderato (italienisch „mäßig“) ist eine Tempobezeichnung für ein mittleres Tempo, ungefähr ♩ = 108–120.","n":4,"h":"kap04-takt.html#g-moderato","f":["Moderato"]},
  "g-moderator": {"t":"Moderator","d":"Der Moderator (Übungsdämpfer) ist das mittlere Pedal vieler aufrechter Klaviere. Er senkt einen Filzstreifen zwischen Hämmer und Saiten und macht das Instrument sehr leise.","n":45,"h":"kap45-pedal.html#g-moderator","f":["Moderator","Übungsdämpfer"]},
  "g-begrenzte-transponierbarkeit": {"t":"Modi mit begrenzter Transponierbarkeit","d":"So nannte Olivier Messiaen symmetrische Skalen, die nach wenigen Verschiebungen wieder dieselben Töne ergeben, etwa die Ganztonleiter (zwei Lagen) und die Ganzton-Halbton-Leiter (drei Lagen).","n":9,"h":"kap09-weitere-skalen.html#g-begrenzte-transponierbarkeit","f":["begrenzter Transponierbarkeit"]},
  "g-modi-begrenzte-transposition": {"t":"Modi mit begrenzter Transpositionsmöglichkeit","d":"Modi mit begrenzter Transpositionsmöglichkeit nannte Olivier Messiaen Tonleitern, die nach wenigen Transpositionen wieder dieselben Töne ergeben, etwa die Ganztonleiter mit nur zwei verschiedenen Formen.","n":25,"h":"kap25-chromatische-akkorde.html#g-modi-begrenzte-transposition","f":["Modi mit begrenzter Transpositionsmöglichkeit"]},
  "g-modulation": {"t":"Modulation","d":"Eine Modulation ist ein dauerhafter Tonartwechsel. Nach ihr ist ein neuer Ton das Zentrum, neue Töne bleiben, und meist bestätigt eine Kadenz die neue Tonart.","n":22,"h":"kap22-modulation.html#g-modulation","f":["Modulation","Modulationen"]},
  "g-modulierende-periode": {"t":"modulierende Periode","d":"Eine modulierende Periode ist eine Periode, deren Nachsatz statt in der Ausgangstonart in einer verwandten Tonart endet, oft in der Dominanttonart.","n":39,"h":"kap39-bausteine.html#g-modulierende-periode","f":["modulierende Periode"]},
  "g-modus": {"t":"Modus","d":"Ein Modus ist eine der sieben Tonleitern, die entstehen, wenn man die Dur-Tonleiter auf jeder ihrer Stufen beginnen lässt, etwa Dorisch ab d. Ionisch ist Dur, Äolisch das natürliche Moll.","n":24,"h":"kap24-modi.html#g-modus","f":["Modi"]},
  "g-moll-blues": {"t":"Moll-Blues","d":"Der Moll-Blues ist ein 12-Takt-Blues in Moll. Die Stufen i und iv erklingen als Moll-Septakkorde, in Takt 9 steht oft ♭VI7 statt V.","n":42,"h":"kap42-songformen.html#g-moll-blues","f":["Moll-Blues"]},
  "g-moll-dur": {"t":"Moll-Dur","d":"Moll-Dur ist ein Begriff aus der Theorie des 19. Jahrhunderts für Dur mit Moll-Subdominante, etwa C-Dur mit f-Moll statt F-Dur.","n":23,"h":"kap23-modale-mischung.html#g-moll-dur","f":["Moll-Dur"]},
  "g-moll-major-septakkord": {"t":"Moll-Major-Septakkord","d":"Der Moll-Major-Septakkord ist ein Molldreiklang mit großer Septime, zum Beispiel c–es–g–h (CmMaj7). Er kommt vor allem im Jazz vor.","n":15,"h":"kap15-septakkorde.html#g-moll-major-septakkord","f":["Moll-Major-Septakkord"]},
  "g-moll-pentatonik": {"t":"Moll-Pentatonik","d":"Die Moll-Pentatonik ist natürliches Moll ohne 2. und 6. Stufe: 1 – ♭3 – 4 – 5 – ♭7, in a also a, c, d, e, g. Sie hat dieselben Töne wie die Dur-Pentatonik eine kleine Terz höher.","n":9,"h":"kap09-weitere-skalen.html#g-moll-pentatonik","f":["Moll-Pentatonik"]},
  "g-moll-subdominante": {"t":"Moll-Subdominante","d":"Die Moll-Subdominante ist ein Moll-Akkord auf der vierten Stufe, in Dur aus der Moll-Variante geliehen, in C-Dur also f-Moll. In der Funktionstheorie schreibt man sie mit kleinem s.","n":23,"h":"kap23-modale-mischung.html#g-moll-subdominante","f":["Moll-Subdominante"]},
  "g-molldreiklang": {"t":"Molldreiklang","d":"Ein Molldreiklang besteht aus einer kleinen Terz und darüber einer großen Terz, zusammen eine reine Quinte, zum Beispiel c–es–g. Im Akkordsymbol steht ein m hinter dem Grundton, etwa Cm.","n":11,"h":"kap11-dreiklaenge.html#g-molldreiklang","f":["Molldreiklang","Molldreiklänge","Moll-Dreiklang","Moll-Dreiklänge","Moll-Dreiklangs","Mollakkord","Mollakkorde","Moll-Akkord","Moll-Akkorden"]},
  "g-mollseptakkord": {"t":"Mollseptakkord","d":"Der Mollseptakkord ist ein Molldreiklang mit kleiner Septime, zum Beispiel Cm7 = c–es–g–b.","n":15,"h":"kap15-septakkorde.html#g-mollseptakkord","f":["Mollseptakkord","Moll-Septakkord","Moll-Septakkorde"]},
  "g-monothematische-exposition": {"t":"monothematische Exposition","d":"Eine monothematische Exposition baut den Seitensatz aus dem Hauptthema selbst, sodass nur die Tonart den Unterschied macht. Haydn verwendet das gern.","n":41,"h":"kap41-sonate.html#g-monothematische-exposition","f":["monothematische Exposition","monothematischen Exposition"]},
  "g-monte": {"t":"Monte","d":"Monte („Berg“) ist eine steigende, zweigliedrige Sequenz mit Zwischendominanten, in C-Dur C7 – F – D7 – G. Das Modell wird einen Ganzton höher wiederholt.","n":26,"h":"kap26-sequenzen.html#g-monte","f":["Monte"]},
  "g-mordent": {"t":"Mordent","d":"Ein Mordent ist eine Verzierung aus Hauptnote, unterer Nebennote und wieder Hauptnote, schnell gespielt. Sein Zeichen hat einen senkrechten Strich.","n":10,"h":"kap10-vortrag.html#g-mordent","f":["Mordent","Mordente","Mordents"]},
  "g-motiv": {"t":"Motiv","d":"Ein Motiv ist die kleinste musikalische Einheit, die man als zusammengehörig und wiedererkennbar wahrnimmt.","n":39,"h":"kap39-bausteine.html#g-motiv","f":["Motiv","Motive","Motivs","Motiven"]},
  "g-mozart-quinten": {"t":"Mozart-Quinten","d":"Mozart-Quinten heißen die parallelen Quinten, die entstehen, wenn ein deutscher Sextakkord direkt zur Dominante aufgelöst wird, in C-Dur as – es zu g – d. Sie gelten als tolerierte Ausnahme vom Verbot paralleler Quinten.","n":25,"h":"kap25-chromatische-akkorde.html#g-mozart-quinten","f":["Mozart-Quinten"]},
  "g-musica-ficta": {"t":"musica ficta","d":"Musica ficta heißt die Praxis, Töne zu erhöhen oder zu erniedrigen, obwohl es nicht notiert ist, etwa den Ton unter dem Grundton an Schlüssen zum Leitton. Sie war spätestens ab dem 14. Jahrhundert üblich.","n":14,"h":"kap14-funktionen.html#g-musica-ficta","f":["musica ficta"]},
  "g-myhill-eigenschaft": {"t":"Myhill-Eigenschaft","d":"Eine Tonleiter hat die Myhill-Eigenschaft, wenn jede Intervallzahl darin in genau zwei Größen vorkommt, etwa Sekunden groß oder klein und Quarten rein oder übermäßig. Die Dur-Tonleiter hat sie.","n":6,"h":"kap06-dur.html#g-myhill-eigenschaft","f":["Myhill-Eigenschaft"]},
  "g-nachsatz": {"t":"Nachsatz","d":"Der Nachsatz ist die zweite Hälfte einer Periode, meist Takt 5–8. Er beginnt wie der Vordersatz, führt aber zu einem geschlossenen Ende, meist zu einem Ganzschluss.","n":39,"h":"kap39-bausteine.html#g-nachsatz","f":["Nachsatz"]},
  "g-nachschlag": {"t":"Nachschlag","d":"Der Nachschlag besteht aus ein oder zwei kleinen Noten am Ende eines Trillers, meist untere Nebennote und Hauptnote. Er leitet zur nächsten Note über.","n":10,"h":"kap10-vortrag.html#g-nachschlag","f":["Nachschläge","Nachschlag"]},
  "g-verwandte-tonarten": {"t":"nächstverwandte Tonarten","d":"Nächstverwandte Tonarten sind Tonarten, deren Vorzeichnung sich höchstens um ein Vorzeichen unterscheidet. Zu C-Dur gehören G-Dur, F-Dur, a-Moll, e-Moll und d-Moll.","n":22,"h":"kap22-modulation.html#g-verwandte-tonarten","f":["nächstverwandt","nächstverwandte","nächstverwandten","verwandte Tonart","verwandten Tonart","verwandte Tonarten","verwandten Tonarten"]},
  "g-natuerliches-moll": {"t":"natürliches Moll","d":"Natürliches Moll (auch äolisch) ist die Moll-Tonleiter ohne zusätzliche Vorzeichen, mit dem Muster Ganz – Halb – Ganz – Ganz – Halb – Ganz – Ganz. Auf a ergibt sie die weißen Tasten a bis a.","n":8,"h":"kap08-moll.html#g-natuerliches-moll","f":["natürliches Moll","natürlichen Moll","natürliche Moll","natürlichem Moll"]},
  "g-naturseptime": {"t":"Naturseptime","d":"Die Naturseptime ist die Septime zwischen dem 4. und dem 7. Teilton, im Verhältnis 7:4. Mit rund 969 Cent ist sie etwa 31 Cent tiefer als die kleine Septime des Klaviers.","n":15,"h":"kap15-septakkorde.html#g-naturseptime","f":["Naturseptime"]},
  "g-neapolitaner": {"t":"neapolitanischer Sextakkord","d":"Der neapolitanische Sextakkord, kurz Neapolitaner, ist ein Dur-Dreiklang auf der erniedrigten zweiten Stufe, meist als Sextakkord, also mit der Terz im Bass.","n":25,"h":"kap25-chromatische-akkorde.html#g-neapolitaner","f":["Neapolitaner","neapolitanischer Sextakkord","neapolitanische Sextakkord","neapolitanischen Sextakkord"]},
  "g-nebendreiklaenge": {"t":"Nebendreiklang","d":"Die Nebendreiklänge einer Durtonart sind die Mollakkorde auf der ii., iii. und vi. Stufe, in C-Dur Dm, Em und Am. Jeder teilt zwei Töne mit einem Hauptdreiklang und kann ihn oft vertreten.","n":13,"h":"kap13-stufen.html#g-nebendreiklaenge","f":["Nebendreiklang","Nebendreiklänge"]},
  "g-nebennote": {"t":"Nebennote","d":"Nebennoten sind die Nachbartöne einer Hauptnote in der Tonart: der nächsthöhere (obere Nebennote) und der nächsttiefere Ton (untere Nebennote). Verzierungen sind aus ihnen gebaut.","n":10,"h":"kap10-vortrag.html#g-nebennote","f":["Nebennote","Nebennoten"]},
  "g-nichtakkordton": {"t":"Nichtakkordton","d":"Ein Nichtakkordton ist ein Melodieton, der nicht zum gerade klingenden Akkord gehört, etwa f über C-Dur. Die wichtigsten Typen sind Durchgang, Wechselnote, Vorhalt, Antizipation, Appoggiatura und Échappée.","n":19,"h":"kap19-nichtakkordtoene.html#g-nichtakkordton","f":["Nichtakkordton","Nichtakkordtöne","Nichtakkordtönen","harmoniefremder Ton"]},
  "g-nocturne": {"t":"Nocturne","d":"Ein Nocturne („Nachtstück“) ist ein ruhiges, gesangliches Klavierstück der Romantik, meist eine Melodie über gebrochenen Akkorden. Berühmt sind die Nocturnes von Chopin.","n":40,"h":"kap40-liedformen.html#g-nocturne","f":["Nocturnes","Nocturne"]},
  "g-non-legato": {"t":"non legato","d":"Non legato heißt leicht getrennt. Es ist die normale Spielweise ohne Zeichen, mit einer kurzen Lücke zwischen den Tönen.","n":10,"h":"kap10-vortrag.html#g-non-legato","f":["non legato"]},
  "g-none": {"t":"None","d":"Die None ist eine Sekunde plus eine Oktave, zum Beispiel c'–d''. Die kleine None hat 13 Halbtöne, die große 14. In Akkordsymbolen erscheint sie als 9.","n":5,"h":"kap05-intervalle.html#g-none","f":["None","Nonen"]},
  "g-notenhals": {"t":"Notenhals","d":"Der Hals (Notenhals) ist der senkrechte Strich an einer Note. Bei Noten unter der Mittellinie zeigt er nach oben, bei Noten auf oder über der Mittellinie nach unten.","n":2,"h":"kap02-notenschrift.html#g-notenhals","f":["Hals","Hälse","Notenhals","Notenhälse"]},
  "g-notenkopf": {"t":"Notenkopf","d":"Der Notenkopf ist der ovale Teil einer Note. Seine Lage im Notensystem zeigt die Tonhöhe, seine Form (hohl oder gefüllt) zusammen mit Hals und Fähnchen die Dauer.","n":2,"h":"kap02-notenschrift.html#g-notenkopf","f":["Notenköpfen","Notenkopfes","Notenköpfe","Notenkopfs","Notenkopf"]},
  "g-schluessel": {"t":"Notenschlüssel","d":"Ein Notenschlüssel am Anfang des Notensystems legt fest, welcher Ton auf welcher Linie steht. Die übrigen Noten ergibt man durch Weiterzählen. Am Klavier braucht man vor allem Violin- und Bassschlüssel.","n":2,"h":"kap02-notenschrift.html#g-schluessel","f":["Notenschlüssel","Notenschlüssels"]},
  "g-notensystem": {"t":"Notensystem","d":"Ein Notensystem (englisch staff) besteht aus fünf Linien und den vier Zwischenräumen dazwischen. Je höher eine Note darin steht, desto höher klingt sie.","n":2,"h":"kap02-notenschrift.html#g-notensystem","f":["Notensystem","Notensysteme","Notensystems","Notensystemen"]},
  "g-notenwert": {"t":"Notenwert","d":"Ein Notenwert gibt an, wie lang ein Ton im Verhältnis zu den anderen dauert, etwa Ganze, Halbe, Viertel oder Achtel. Jeder Wert ist halb so lang wie der vorige.","n":3,"h":"kap03-rhythmus.html#g-notenwert","f":["Notenwert","Notenwerte","Notenwerten","Notenwerts","Notenwertes"]},
  "g-oberstimme": {"t":"Oberstimme","d":"Die Oberstimme ist die höchste Stimme eines mehrstimmigen Satzes, meist die Melodie. Im Plural meint Oberstimmen oft alle Stimmen über dem Bass.","n":12,"h":"kap12-umkehrungen.html#g-oberstimme","f":["Oberstimmen","Oberstimme"]},
  "g-offbeat": {"t":"Offbeat","d":"Offbeat heißt die Stelle zwischen zwei Schlägen, beim Zählen das „und“. Ein Ton im Offbeat beginnt also nicht auf einer Zählzeit.","n":3,"h":"kap03-rhythmus.html#g-offbeat","f":["Offbeat","Offbeats"]},
  "g-oktave": {"t":"Oktave","d":"Der Abstand zwischen zwei Tönen gleichen Namens heißt Oktave (lateinisch octava, „die achte“, weil das zweite c der achte Stammton ist).","n":1,"h":"kap01-klaviatur.html#g-oktave","f":["Oktave","Oktaven"]},
  "g-oktavgattung": {"t":"Oktavgattung","d":"Eine Oktavgattung ist im antiken griechischen Tonsystem ein Oktavausschnitt mit einer bestimmten Folge von Ganz- und Halbtönen. Von dort stammen die Namen dorisch, phrygisch, lydisch und mixolydisch.","n":24,"h":"kap24-modi.html#g-oktavgattung","f":["Oktavgattung","Oktavgattungen"]},
  "g-oktavierungszeichen": {"t":"Oktavierungszeichen","d":"Ein Oktavierungszeichen verschiebt die gespielte Lage: 8va über den Noten heißt eine Oktave höher spielen als notiert, 8vb darunter eine Oktave tiefer, loco wieder wie notiert.","n":2,"h":"kap02-notenschrift.html#g-oktavierungszeichen","f":["Oktavierungszeichen","Oktavierungszeichens"]},
  "g-oktavlage": {"t":"Oktavlage","d":"Bei der Oktavlage liegt der Grundton eines Akkords als oberster Ton, C-Dur etwa als e'–g'–c''.","n":12,"h":"kap12-umkehrungen.html#g-oktavlage","f":["Oktavlage"]},
  "g-oktavparallele": {"t":"Oktavparallele","d":"Eine Oktavparallele entsteht, wenn zwei Stimmen von einer Oktave (oder Prime) in die nächste gehen und sich dabei beide bewegen. Im klassischen Satz ist sie verboten.","n":33,"h":"kap33-stimmfuehrung.html#g-oktavparallele","f":["Oktavparallele","Oktavparallelen"]},
  "g-optionston": {"t":"Optionston","d":"Optionstöne sind die Töne 9, 11 und 13 über einem Septakkord. Sie dürfen hinzukommen, müssen aber nicht, und verändern die Farbe des Akkords, nicht seine Funktion.","n":27,"h":"kap27-optionstoene.html#g-optionston","f":["Optionston","Optionstöne","Optionstönen","Spannungston","Spannungstöne"]},
  "g-organum": {"t":"Organum","d":"Das Organum ist eine frühe Form mehrstimmigen Gesangs aus der Zeit um 900, bei der eine Melodie in parallelen Quarten oder Quinten verdoppelt wird.","n":33,"h":"kap33-stimmfuehrung.html#g-organum","f":["Organum"]},
  "g-orgelpunkt": {"t":"Orgelpunkt","d":"Ein Orgelpunkt ist ein lang ausgehaltener oder ständig wiederholter Basston, über dem die Harmonien wechseln.","n":26,"h":"kap26-sequenzen.html#g-orgelpunkt","f":["Orgelpunkt","Orgelpunkte","Orgelpunkts","Orgelpunkten"]},
  "g-ostinato": {"t":"Ostinato","d":"Ein Ostinato ist eine kurze Basslinie oder Akkordfolge, die ständig unverändert wiederholt wird. Darüber entstehen immer neue Melodien.","n":40,"h":"kap40-liedformen.html#g-ostinato","f":["Ostinato","Ostinatos"]},
  "g-outro": {"t":"Outro","d":"Das Outro ist der Schlussteil eines Songs, oft ein wiederholter Refrain, der ausgeblendet wird.","n":42,"h":"kap42-songformen.html#g-outro","f":["Outro"]},
  "g-paarfingersatz": {"t":"Paarfingersatz","d":"Ein Paarfingersatz ist ein älterer Tonleiterfingersatz, bei dem zwei Finger abwechseln, etwa rechts aufwärts 3–4–3–4, und der Daumen kaum vorkommt. Er war bis ins frühe 18. Jahrhundert verbreitet.","n":44,"h":"kap44-fingersaetze.html#g-paarfingersatz","f":["Paarfingersatz","Paarfingersätze","Paarfingersätzen"]},
  "g-parallelbewegung": {"t":"Parallelbewegung","d":"Bei Parallelbewegung gehen zwei Stimmen in dieselbe Richtung, und das Intervall zwischen ihnen bleibt gleich, etwa Terz bleibt Terz.","n":33,"h":"kap33-stimmfuehrung.html#g-parallelbewegung","f":["Parallelbewegung"]},
  "g-parallele": {"t":"Parallele","d":"Die Parallele (p) ist in Dur der Mollakkord eine kleine Terz unter einem Hauptdreiklang. In C-Dur ist a-Moll die Tonikaparallele (Tp), d-Moll die Subdominantparallele (Sp) und e-Moll die Dominantparallele (Dp).","n":14,"h":"kap14-funktionen.html#g-parallele","f":["Tonikaparallele","Subdominantparallele","Dominantparallele","Moll-Parallele"]},
  "g-parallele-sextakkorde": {"t":"parallele Sextakkorde","d":"Parallele Sextakkorde sind eine Folge von Akkorden in Sextakkordlage (Terz im Bass), die stufenweise auf- oder absteigt. Weil alle Stimmen parallel laufen, klingt das wie eine verdickte Melodie.","n":26,"h":"kap26-sequenzen.html#g-parallele-sextakkorde","f":["parallele Sextakkorde","parallelen Sextakkorde","parallelen Sextakkorden"]},
  "g-paralleltonart": {"t":"Paralleltonart","d":"Paralleltonarten (englisch relative keys) sind eine Dur- und eine Moll-Tonart mit denselben Tönen und derselben Vorzeichnung, etwa C-Dur und a-Moll. Die Moll-Parallele liegt eine kleine Terz unter der Dur-Tonika.","n":8,"h":"kap08-moll.html#g-paralleltonart","f":["Paralleltonart","Paralleltonarten","parallele Moll-Tonart","parallelen Moll-Tonart","parallele Molltonart","parallelen Molltonart"]},
  "g-passacaglia": {"t":"Passacaglia","d":"Die Passacaglia ist eine Variationsform über einem ständig wiederkehrenden Bass, ebenso wie die Chaconne.","n":18,"h":"kap18-pop-progressionen.html#g-passacaglia","f":["Passacaglia"]},
  "g-passion": {"t":"Passion","d":"Eine Passion vertont die Leidensgeschichte Jesu nach einem der Evangelien für Solisten, Chor und Orchester, etwa Bachs Matthäus-Passion.","n":37,"h":"kap37-choralsatz.html#g-passion","f":["Passionen","Passion"]},
  "g-pause": {"t":"Pause","d":"Eine Pause ist ein Zeichen für genau abgemessene Stille. Zu jedem Notenwert gibt es eine Pause derselben Länge.","n":3,"h":"kap03-rhythmus.html#g-pause","f":[]},
  "g-pendelwechsel": {"t":"Pendelwechsel","d":"Ein Pendelwechsel ist der ständige Wechsel zwischen zwei Akkorden. In modaler Musik pendelt man meist zwischen dem Grundakkord und einem Akkord mit dem charakteristischen Ton, etwa Dm – G in d-Dorisch.","n":24,"h":"kap24-modi.html#g-pendelwechsel","f":["Pendelwechsel"]},
  "g-pentatonik": {"t":"Pentatonik","d":"Eine Pentatonik (griechisch pente, fünf) ist eine Tonleiter mit fünf Tönen.","n":9,"h":"kap09-weitere-skalen.html#g-pentatonik","f":["Pentatonik","Pentatoniken","pentatonische","pentatonischen"]},
  "g-periode": {"t":"Periode","d":"Eine Periode ist ein meist achttaktiges Thema aus zwei gleich langen Hälften, Vordersatz und Nachsatz. Beide beginnen gleich, der Vordersatz endet offen (meist Halbschluss), der Nachsatz geschlossen (meist Ganzschluss).","n":39,"h":"kap39-bausteine.html#g-periode","f":["Periode"]},
  "g-phrase": {"t":"Phrase","d":"Eine Phrase ist ein zusammenhängender musikalischer Abschnitt, der wie ein Satz in der Sprache einen Anfang, einen Höhepunkt und ein Ende hat.","n":10,"h":"kap10-vortrag.html#g-phrase","f":["Phrase","Phrasen"]},
  "g-phrasierungsbogen": {"t":"Phrasierungsbogen","d":"Ein Phrasierungsbogen ist ein langer Bogen über mehreren Takten. Er zeigt, was als eine Phrase zusammengehört und als ein Gedanke gespielt werden soll.","n":10,"h":"kap10-vortrag.html#g-phrasierungsbogen","f":["Phrasierungsbogen","Phrasierungsbögen"]},
  "g-phrygisch": {"t":"Phrygisch","d":"Phrygisch ist der Modus, der auf den weißen Tasten von e bis e' entsteht. Er klingt wie natürliches Moll mit kleiner Sekunde über dem Grundton.","n":24,"h":"kap24-modi.html#g-phrygisch","f":["phrygisch","phrygische","phrygischen","phrygischer"]},
  "g-phrygischer-halbschluss": {"t":"phrygischer Halbschluss","d":"Der phrygische Halbschluss ist ein Halbschluss in Moll, iv–V mit der Subdominante in erster Umkehrung. Der Bass fällt dabei einen Halbton abwärts in die Dominante, in a-Moll von f nach e.","n":16,"h":"kap16-kadenzen.html#g-phrygischer-halbschluss","f":["phrygischer Halbschluss","phrygischen Halbschluss"]},
  "g-piano": {"t":"piano (p)","d":"Piano (abgekürzt p) ist die Dynamikangabe für leise. pp (pianissimo) heißt sehr leise, mp (mezzopiano) mäßig leise.","n":10,"h":"kap10-vortrag.html#g-piano","f":["pianissimo","mezzopiano"]},
  "g-pianopedal": {"t":"Pianopedal","d":"Das Pianopedal ist das linke Pedal des aufrechten Klaviers. Es rückt die Hämmer näher an die Saiten, sodass sie mit weniger Schwung anschlagen und der Ton leiser wird.","n":45,"h":"kap45-pedal.html#g-pianopedal","f":["Pianopedal"]},
  "g-picardische-terz": {"t":"picardische Terz","d":"Die picardische Terz ist ein Dur-Schlussakkord am Ende eines Stücks in Moll, zum Beispiel A-Dur statt a-Moll. Sie war in der Barockmusik der übliche Schluss.","n":16,"h":"kap16-kadenzen.html#g-picardische-terz","f":["picardische Terz","picardischer Terz"]},
  "g-pitch-proximity": {"t":"pitch proximity","d":"Pitch proximity (Tonhöhennähe) ist das Prinzip, dass in Melodien ein Ton am wahrscheinlichsten auf einen nahe gelegenen Ton folgt. Hörer erwarten deshalb vor allem Schritte.","n":19,"h":"kap19-nichtakkordtoene.html#g-pitch-proximity","f":["pitch proximity"]},
  "g-plagale-tonart": {"t":"plagale Tonart","d":"In der Lehre von den Kirchentonarten ist eine plagale Tonart eine Tonart, deren Melodien den Grundton umspielen. Ihr Tonumfang liegt um den Grundton herum statt darüber.","n":16,"h":"kap16-kadenzen.html#g-plagale-tonart","f":["plagale Tonart","plagalen Tonarten"]},
  "g-plagalschluss": {"t":"Plagalschluss","d":"Der Plagalschluss ist die Verbindung IV–I. Ohne Leitton klingt er weicher als der Ganzschluss. Nach dem gesungenen „Amen“ vieler Kirchenlieder heißt er auch Amen-Schluss.","n":16,"h":"kap16-kadenzen.html#g-plagalschluss","f":["Plagalschluss","Amen-Schluss"]},
  "g-play-along": {"t":"Play-along","d":"Play-along-Aufnahmen enthalten nur die Begleitung eines Stücks, sodass man selbst die Melodie oder ein Solo dazu spielen kann.","n":30,"h":"kap30-akkordskalen.html#g-play-along","f":["Play-along-Aufnahmen","Play-along-Aufnahme"]},
  "g-polyphonie": {"t":"Polyphonie","d":"Polyphonie ist Mehrstimmigkeit aus selbstständigen Stimmen, von denen jede eine eigene Melodie ist. Vokalpolyphonie ist solche Musik für Singstimmen. Das Gegenstück ist eine Melodie mit Akkordbegleitung.","n":19,"h":"kap19-nichtakkordtoene.html#g-polyphonie","f":["Vokalpolyphonie","Polyphonie","polyphonen","polyphoner","polyphone","polyphon"]},
  "g-ponte": {"t":"Ponte","d":"Ponte („Brücke“) nannte Joseph Riepel einen Abschnitt, der auf der Dominante verharrt.","n":26,"h":"kap26-sequenzen.html#g-ponte","f":["Ponte"]},
  "g-portato": {"t":"portato","d":"Portato (Zeichen: Punkte unter einem Bogen) heißt getragen und leicht getrennt, zwischen legato und staccato.","n":10,"h":"kap10-vortrag.html#g-portato","f":["portato"]},
  "g-powerchord": {"t":"Powerchord","d":"Ein Powerchord ist ein Zweiklang aus Grundton und Quinte, typisch für die Rockgitarre. Er wird meist als Ganzes parallel verschoben.","n":33,"h":"kap33-stimmfuehrung.html#g-powerchord","f":["Powerchord","Powerchords"]},
  "g-pralltriller": {"t":"Pralltriller","d":"Ein Pralltriller ist eine Verzierung aus Hauptnote, oberer Nebennote und wieder Hauptnote, schnell gespielt.","n":10,"h":"kap10-vortrag.html#g-pralltriller","f":["Pralltriller"]},
  "g-praeludium": {"t":"Präludium","d":"Ein Präludium (Vorspiel) ist ein frei gestaltetes Instrumentalstück, das oft einem anderen Stück wie einer Fuge vorangeht.","n":5,"h":"kap05-intervalle.html#g-praeludium","f":["Präludiums","Präludium","Präludien"]},
  "g-praesentation": {"t":"Präsentation","d":"Die Präsentation ist die erste Hälfte eines Satzes (Themenform), meist Takt 1–4. Eine zweitaktige Basisidee wird vorgestellt und gleich wiederholt.","n":39,"h":"kap39-bausteine.html#g-praesentation","f":["Präsentation"]},
  "g-pre-chorus": {"t":"Pre-Chorus","d":"Der Pre-Chorus (auch build) ist der Teil zwischen Strophe und Refrain eines Songs. Er baut Spannung auf, meidet harmonisch die Tonika und leitet zum Refrain über.","n":42,"h":"kap42-songformen.html#g-pre-chorus","f":["Pre-Chorus"]},
  "g-prestissimo": {"t":"Prestissimo","d":"Prestissimo (italienisch „äußerst schnell“) ist die schnellste übliche Tempobezeichnung, ungefähr ♩ = über 200.","n":4,"h":"kap04-takt.html#g-prestissimo","f":["Prestissimo"]},
  "g-presto": {"t":"Presto","d":"Presto (italienisch „schnell“) ist eine sehr schnelle Tempobezeichnung, ungefähr ♩ = 168–200.","n":4,"h":"kap04-takt.html#g-presto","f":["Presto"]},
  "g-prime": {"t":"Prime","d":"Die Prime (lateinisch „die erste“) ist das Intervall zwischen zwei Tönen gleichen Namens in derselben Lage, zum Beispiel c–c. Die reine Prime hat 0 Halbtöne.","n":5,"h":"kap05-intervalle.html#g-prime","f":["Prime","Primen"]},
  "g-puls": {"t":"Puls","d":"Fast jede Musik, die du am Klavier spielst, hat einen gleichmäßigen Puls: einen inneren Herzschlag, zu dem man mit dem Fuß tippen kann.","n":3,"h":"kap03-rhythmus.html#g-puls","f":["Puls","Pulse","Pulses"]},
  "g-punktierung": {"t":"Punktierung","d":"Ein Punkt hinter einer Note verlängert sie um die Hälfte ihres Werts.","n":3,"h":"kap03-rhythmus.html#g-punktierung","f":["Punktierung","Punktierungen","punktiert","punktierte","punktierten","punktierter","punktiertes"]},
  "g-komma": {"t":"pythagoreisches Komma","d":"Das pythagoreische Komma ist der Unterschied zwischen zwölf reinen Quinten und sieben Oktaven. Es beträgt rund 23,5 Cent, etwa ein Viertel Halbton.","n":5,"h":"kap05-intervalle.html#g-komma","f":["pythagoreisches Komma","pythagoreische Komma","pythagoreischen Komma","pythagoreischen Kommas"]},
  "g-qualitaet": {"t":"Qualität","d":"Die Qualität eines Intervalls gibt an, welche Größe genau gemeint ist: rein, groß, klein, übermäßig oder vermindert. So unterscheiden sich etwa die große Terz c–e und die kleine Terz c–es.","n":5,"h":"kap05-intervalle.html#g-qualitaet","f":[]},
  "g-quarte": {"t":"Quarte","d":"Die Quarte (lateinisch „die vierte“) ist das Intervall über vier Stammtöne, zum Beispiel c–f. Die reine Quarte hat fünf Halbtöne.","n":5,"h":"kap05-intervalle.html#g-quarte","f":["Quarte","Quarten"]},
  "g-quartsextakkord": {"t":"Quartsextakkord","d":"Der Quartsextakkord ist die zweite Umkehrung eines Dreiklangs, mit der Quinte im Bass, zum Beispiel g–c–e. Über dem Bass liegen Quarte und Sexte, daher der Name und die Bezifferung 6/4.","n":12,"h":"kap12-umkehrungen.html#g-quartsextakkord","f":["Quartsextakkord"]},
  "g-quartsextvorhalt": {"t":"Quartsextvorhalt","d":"Der Quartsextvorhalt ist ein Akkord vor der Dominante, der wie die Tonika in zweiter Umkehrung aussieht, etwa C/G vor G. Quarte und Sexte über dem Bass lösen sich danach abwärts in Terz und Quinte der Dominante auf.","n":16,"h":"kap16-kadenzen.html#g-quartsextvorhalt","f":["Quartsextvorhalt"]},
  "g-quartvoicing": {"t":"Quartvoicing","d":"Quartvoicings sind Akkordgriffe aus übereinandergeschichteten Quarten statt Terzen. Sie klingen offen und modern und legen sich weniger deutlich auf Dur oder Moll fest.","n":29,"h":"kap29-voicings.html#g-quartvoicing","f":["Quartvoicing","Quartvoicings"]},
  "g-quick-change": {"t":"Quick Change","d":"Der Quick Change ist eine Variante des 12-Takt-Blues, bei der schon in Takt 2 kurz die IV erklingt, bevor es in Takt 3 zur I zurückgeht.","n":42,"h":"kap42-songformen.html#g-quick-change","f":["Quick Change"]},
  "g-quint-sext-pattern": {"t":"Quint-Sext-Pattern","d":"Das Quint-Sext-Pattern ist ein Blues-Begleitmuster der linken Hand. In Achteln erklingt mit dem Grundton im Wechsel zweimal die Quinte und zweimal die Sexte.","n":42,"h":"kap42-songformen.html#g-quint-sext-pattern","f":["Quint-Sext-Pattern"]},
  "g-quinte": {"t":"Quinte","d":"Die Quinte (lateinisch „die fünfte“) ist das Intervall über fünf Stammtöne, zum Beispiel c–g. Die reine Quinte hat sieben Halbtöne und klingt nach der Oktave am stärksten verschmolzen.","n":5,"h":"kap05-intervalle.html#g-quinte","f":["Quinte","Quinten"]},
  "g-quintenspirale": {"t":"Quintenspirale","d":"Die Quintenspirale entsteht, wenn man reine Quinten aufeinanderschichtet. Wegen des pythagoreischen Kommas schließt sie sich nie: his liegt etwas höher als c, Fis-Dur etwas höher als Ges-Dur.","n":7,"h":"kap07-quintenzirkel.html#g-quintenspirale","f":["Quintenspirale"]},
  "g-quintenzirkel": {"t":"Quintenzirkel","d":"Der Quintenzirkel (englisch circle of fifths) ordnet alle Dur-Tonarten im Quintabstand zu einem Kreis. Im Uhrzeigersinn kommt mit jeder Quinte aufwärts ein Kreuz dazu, gegen den Uhrzeigersinn ein ♭.","n":7,"h":"kap07-quintenzirkel.html#g-quintenzirkel","f":["Quintenzirkel","Quintenzirkels"]},
  "g-quintfall": {"t":"Quintfall","d":"Ein Quintfall ist eine Grundtonbewegung um eine Quinte abwärts oder, gleichwertig, eine Quarte aufwärts, etwa g → c bei V–I. Er gilt als die stärkste Grundtonbewegung.","n":14,"h":"kap14-funktionen.html#g-quintfall","f":["Quintfall","Quintfälle","Quintfällen","Quintfalls"]},
  "g-quintfallkette": {"t":"Quintfallkette","d":"Eine Quintfallkette ist eine Akkordfolge, deren Grundtöne immer eine Quinte abwärts fallen, etwa Am – Dm – G – C. Jeder Akkord wirkt dabei wie eine kleine Dominante zum nächsten.","n":18,"h":"kap18-pop-progressionen.html#g-quintfallkette","f":["Quintfallkette","Quintfallketten"]},
  "g-quintfallsequenz": {"t":"Quintfallsequenz","d":"Eine Quintfallsequenz ist eine Akkordfolge, deren Grundtöne von Akkord zu Akkord eine Quinte fallen, in C-Dur C – F – H° – Em – Am – Dm – G – C. Sie durchläuft alle sieben Stufen der Tonart.","n":26,"h":"kap26-sequenzen.html#g-quintfallsequenz","f":["Quintfallsequenz","Quintfallsequenzen"]},
  "g-quintlage": {"t":"Quintlage","d":"Bei der Quintlage liegt die Quinte eines Akkords als oberster Ton, C-Dur etwa als c'–e'–g'.","n":12,"h":"kap12-umkehrungen.html#g-quintlage","f":["Quintlage"]},
  "g-quintole": {"t":"Quintole","d":"Eine Quintole sind fünf Noten in der Zeit von vier Noten desselben Werts. Sie wird mit einer kleinen 5 gekennzeichnet.","n":3,"h":"kap03-rhythmus.html#g-quintole","f":["Quintole","Quintolen"]},
  "g-quintparallele": {"t":"Quintparallele","d":"Eine Quintparallele entsteht, wenn zwei Stimmen von einer reinen Quinte in die nächste reine Quinte gehen und sich dabei beide bewegen.","n":33,"h":"kap33-stimmfuehrung.html#g-quintparallele","f":["Quintparallele","Quintparallelen","parallele Quinten","parallelen Quinten"]},
  "g-quintsextakkord": {"t":"Quintsextakkord","d":"Der Quintsextakkord ist die erste Umkehrung eines Septakkords, mit der Terz im Bass, bei G7 also h–d–f–g. Über dem Bass liegen Quinte und Sexte, die Bezifferung ist 6/5.","n":15,"h":"kap15-septakkorde.html#g-quintsextakkord","f":["Quintsextakkord"]},
  "g-ragtime": {"t":"Ragtime","d":"Ragtime ist ein amerikanischer Klavierstil um 1900. Die linke Hand spielt einen gleichmäßigen Marschrhythmus aus Bass und Akkord, die rechte darüber stark synkopierte Melodien.","n":46,"h":"kap46-begleitmuster.html#g-ragtime","f":["Ragtime","Ragtimes"]},
  "g-ragtime-progression": {"t":"Ragtime-Progression","d":"Die Ragtime-Progression ist eine Kette von Zwischendominanten, deren Grundtöne in Quinten fallen, in C-Dur E7 – A7 – D7 – G7 – C. Sie ist typisch für Ragtime und frühen Jazz.","n":21,"h":"kap21-zwischendominanten.html#g-ragtime-progression","f":["Ragtime-Progression"]},
  "g-rallentando": {"t":"rallentando","d":"rallentando (abgekürzt rall.) ist eine Spielanweisung: allmählich langsamer werden, gleichbedeutend mit ritardando.","n":4,"h":"kap04-takt.html#g-rallentando","f":["rallentando"]},
  "g-rauigkeit": {"t":"Rauigkeit","d":"Rauigkeit ist der scharfe, kratzige Klangeindruck, den das Ohr wahrnimmt, wenn Schwebungen schneller als etwa 15 pro Sekunde werden. Sie macht zum Beispiel die kleine Sekunde scharf.","n":5,"h":"kap05-intervalle.html#g-rauigkeit","f":["Rauigkeit"]},
  "g-reale-antwort": {"t":"reale Antwort","d":"Eine reale Antwort ist die genaue Transposition des Fugenthemas eine Quinte höher oder eine Quarte tiefer.","n":38,"h":"kap38-fuge.html#g-reale-antwort","f":["reale Antwort","realen Antwort"]},
  "g-reale-sequenz": {"t":"reale Sequenz","d":"Bei einer realen Sequenz wird das Modell mit exakt gleichen Intervallen versetzt. Dafür braucht man tonartfremde Töne, etwa c – d – e zu d – e – fis.","n":26,"h":"kap26-sequenzen.html#g-reale-sequenz","f":["reale Sequenz","realen Sequenz","reale Sequenzen","realen Sequenzen"]},
  "g-refrain-rondo": {"t":"Refrain (Rondo)","d":"Der Refrain ist im Rondo der Hauptteil, der mehrmals in der Grundtonart wiederkehrt. Zwischen seinen Auftritten stehen die Couplets.","n":40,"h":"kap40-liedformen.html#g-refrain-rondo","f":["~Refrain","~Refrains"]},
  "g-refrain-song": {"t":"Refrain (Song)","d":"Der Refrain (englisch chorus) ist der Kern eines Songs. Er kehrt mehrmals mit gleichem Text wieder und enthält meist den Titel und die Hook.","n":42,"h":"kap42-songformen.html#g-refrain-song","f":["Refrain","Refrains"]},
  "g-naechster-weg": {"t":"Regel des nächsten Weges","d":"Nach der Regel des nächsten Weges bleiben gemeinsame Töne zweier Akkorde liegen, und alle anderen Töne gehen zum nächstgelegenen Ton des neuen Akkords.","n":33,"h":"kap33-stimmfuehrung.html#g-naechster-weg","f":["Regel des nächsten Weges","nächsten Weges","nächsten Weg"]},
  "g-reharmonisierung": {"t":"Reharmonisierung","d":"Eine Reharmonisierung ersetzt die ursprünglichen Akkorde eines Stücks durch andere, während die Melodie gleich bleibt.","n":32,"h":"kap32-reharmonisierung.html#g-reharmonisierung","f":["Reharmonisierung","Reharmonisierungen","reharmonisieren"]},
  "g-rein": {"t":"rein","d":"Rein heißt die Normalform von Prime, Quarte, Quinte und Oktave, etwa die reine Quinte c–g mit sieben Halbtönen. Diese Intervalle haben die einfachsten Frequenzverhältnisse und verschmelzen besonders stark.","n":5,"h":"kap05-intervalle.html#g-rein","f":[]},
  "g-reine-stimmung": {"t":"reine Stimmung","d":"Die reine Stimmung stimmt die Töne einer Tonleiter nach einfachen Frequenzverhältnissen, sodass die Hauptdreiklänge im Verhältnis 4:5:6 rein klingen. Dafür klingen andere Akkorde verstimmt, in C-Dur etwa d-Moll.","n":13,"h":"kap13-stufen.html#g-reine-stimmung","f":["reine Stimmung","reiner Stimmung"]},
  "g-relatives-gehoer": {"t":"relatives Gehör","d":"Das relative Gehör ist die Fähigkeit, Töne im Verhältnis zueinander zu erkennen, etwa dass der zweite Ton eine Terz höher liegt als der erste. Es lässt sich in jedem Alter trainieren.","n":49,"h":"kap49-nach-gehoer.html#g-relatives-gehoer","f":["relatives Gehör","relative Gehör","relativen Gehör","relativen Gehörs","relatives Hören","relativem Hören"]},
  "g-reprise": {"t":"Reprise","d":"Die Reprise ist der dritte Teil der Sonatenform. Hauptsatz und Seitensatz kehren zurück, jetzt beide in der Grundtonart, und lösen so den Tonartenkonflikt.","n":41,"h":"kap41-sonate.html#g-reprise","f":["Reprise","Reprisen"]},
  "g-residualton": {"t":"Residualton","d":"Ein Residualton ist ein Grundton, den das Gehör aus den Obertönen ergänzt, obwohl er selbst nicht erklingt. So hört man am Telefon tiefe Stimmen, obwohl die Leitung deren Grundtöne nicht überträgt.","n":29,"h":"kap29-voicings.html#g-residualton","f":["Residualton","fehlender Grundton"]},
  "g-resonanz": {"t":"Resonanz","d":"Resonanz entsteht, wenn ein schwingfähiger Körper wie eine Saite im Rhythmus seiner eigenen Frequenz angestoßen wird. Er gerät dann selbst in Schwingung.","n":45,"h":"kap45-pedal.html#g-resonanz","f":["Resonanz"]},
  "g-retardation": {"t":"Retardation","d":"Eine Retardation ist ein Vorhalt, der sich stufenweise aufwärts auflöst, meist weil der vorgehaltene Ton ein Leitton ist. Beispiel: h' über c löst sich nach c'' auf.","n":36,"h":"kap36-kontrapunkt-3.html#g-retardation","f":["Retardation","Retardationen"]},
  "g-rezitationston": {"t":"Rezitationston","d":"Der Rezitationston ist im gregorianischen Choral der Ton, auf dem längere Textstellen auf gleicher Tonhöhe gesungen werden.","n":24,"h":"kap24-modi.html#g-rezitationston","f":["Rezitationstöne","Rezitationstons","Rezitationston"]},
  "g-rhythm-changes": {"t":"Rhythm Changes","d":"Rhythm Changes ist die Akkordfolge von Gershwins „I Got Rhythm“ in AABA-Form. Jazzmusiker haben darüber zahlreiche neue Melodien geschrieben.","n":42,"h":"kap42-songformen.html#g-rhythm-changes","f":["Rhythm Changes"]},
  "g-rhythmus": {"t":"Rhythmus","d":"Der Rhythmus ist das Muster aus langen und kurzen Tönen und Pausen, das sich über diesen Puls legt.","n":3,"h":"kap03-rhythmus.html#g-rhythmus","f":["Rhythmus","Rhythmen"]},
  "g-rhythmusvarianten": {"t":"Rhythmusvarianten","d":"Beim Üben mit Rhythmusvarianten spielst du eine gleichmäßige Passage punktiert, erst lang–kurz, dann kurz–lang. So wird jeder Übergang einmal langsam und einmal schnell geübt.","n":47,"h":"kap47-ueben.html#g-rhythmusvarianten","f":["Rhythmusvarianten","Rhythmusvariante"]},
  "g-ritardando": {"t":"ritardando","d":"ritardando (abgekürzt rit.) ist eine Spielanweisung: allmählich langsamer werden. rallentando (rall.) bedeutet dasselbe.","n":4,"h":"kap04-takt.html#g-ritardando","f":["ritardando"]},
  "g-ritenuto": {"t":"ritenuto","d":"Ritenuto (abgekürzt riten.) bedeutet: sofort zurückhalten, also plötzlicher langsamer werden als bei einem ritardando.","n":10,"h":"kap10-vortrag.html#g-ritenuto","f":["ritenuto"]},
  "g-roadmap": {"t":"Roadmap","d":"Als Roadmap bezeichnet man die Wegbeschreibung durch ein Leadsheet. Zeichen und Abkürzungen sagen, in welcher Reihenfolge und wie oft die Formteile gespielt werden.","n":42,"h":"kap42-songformen.html#g-roadmap","f":["Roadmap"]},
  "g-romanesca": {"t":"Romanesca","d":"Die Romanesca ist ein Bassmodell des 16. und 17. Jahrhunderts. Ihre fallenden Quart- und Sekundschritte sind eng mit der Kanon-Folge verwandt.","n":18,"h":"kap18-pop-progressionen.html#g-romanesca","f":["Romanesca"]},
  "g-rondo": {"t":"Rondo","d":"Im Rondo kehrt ein Hauptteil, der Refrain, mehrmals in der Grundtonart wieder. Dazwischen stehen jeweils andere Teile, die Couplets, etwa im Plan A B A C A.","n":40,"h":"kap40-liedformen.html#g-rondo","f":["Rondo"]},
  "g-rootless-voicing": {"t":"Rootless-Voicing","d":"Ein Rootless-Voicing ist ein meist vierstimmiger Akkordgriff ohne Grundton in der Mitte der Klaviatur. Statt des Grundtons, den der Bass spielt, enthält es einen Optionston, etwa f–a–c'–e' für Dm9.","n":29,"h":"kap29-voicings.html#g-rootless-voicing","f":["Rootless-Voicing","Rootless-Voicings","Rootless"]},
  "g-rotation": {"t":"Rotation","d":"Rotation ist die Drehung des Unterarms, wie beim Aufschließen einer Tür. Sie bewegt die Hand zwischen Daumen- und Kleinfingerseite und ist die Grundlage für Triller, Tremolo und gebrochene Oktaven.","n":43,"h":"kap43-technik.html#g-rotation","f":["Rotation"]},
  "g-rubato": {"t":"rubato","d":"Rubato (italienisch „geraubt“) heißt, das Tempo im Ausdruck frei zu dehnen und zu drängen. Es ist typisch für Chopin.","n":4,"h":"kap04-takt.html#g-rubato","f":["rubato"]},
  "g-rueckfuehrung": {"t":"Rückführung","d":"Die Rückführung ist der letzte Abschnitt der Durchführung. Sie lenkt die Musik zur Dominante der Grundtonart und hält diese oft lange fest, um die Reprise vorzubereiten.","n":41,"h":"kap41-sonate.html#g-rueckfuehrung","f":["Rückführung"]},
  "g-rueckung": {"t":"Rückung","d":"Eine Rückung ist ein Tonartwechsel ohne Vorbereitung. Ein Abschnitt endet in der alten Tonart, der nächste beginnt sofort in der neuen, im Pop oft einen Halbton höher vor dem letzten Refrain.","n":22,"h":"kap22-modulation.html#g-rueckung","f":["Rückung","Rückungen"]},
  "g-rundkanon": {"t":"Rundkanon","d":"Ein Rundkanon (auch Zirkelkanon) ist ein Kanon, den man beliebig oft von vorn beginnen kann, zum Beispiel „Bruder Jakob“.","n":38,"h":"kap38-fuge.html#g-rundkanon","f":["Rundkanon","Rundkanons","Zirkelkanon"]},
  "g-sarabande": {"t":"Sarabande","d":"Die Sarabande ist ein langsamer barocker Tanz im Dreiertakt, oft mit einer Betonung auf der zweiten Zählzeit.","n":40,"h":"kap40-liedformen.html#g-sarabande","f":["Sarabanden","Sarabande"]},
  "g-satz": {"t":"Satz (Themenform)","d":"Der Satz (englisch sentence) ist eine meist achttaktige Themenform. Eine zweitaktige Basisidee erklingt zweimal, danach werden die Einheiten kürzer und münden in eine Kadenz (2 + 2 + 4 Takte).","n":39,"h":"kap39-bausteine.html#g-satz","f":[]},
  "g-satzlehre": {"t":"Satzlehre","d":"Die Satzlehre (auch Tonsatz) lehrt, wie man mehrstimmige Musik regelgerecht setzt, vor allem Stimmführung, Verdopplung und den Umgang mit Dissonanzen.","n":5,"h":"kap05-intervalle.html#g-satzlehre","f":["Satzlehre","Tonsatzes","Tonsatz"]},
  "g-schema": {"t":"Schema","d":"Schemata (Einzahl Schema) nennt Robert Gjerdingen die festen Wendungen wie Monte oder Fonte, die Komponisten des 18. Jahrhunderts wie Vokabeln lernten und zu Stücken zusammensetzten.","n":26,"h":"kap26-sequenzen.html#g-schema","f":[]},
  "g-scherzo": {"t":"Scherzo","d":"Ein Scherzo (italienisch „Scherz“) ist ein schneller Satz im Dreiertakt. Bei Beethoven ersetzt es oft das Menuett, meist in der Form Scherzo, Trio, Scherzo.","n":41,"h":"kap41-sonate.html#g-scherzo","f":["Scherzos","Scherzo","Scherzi"]},
  "g-schlag": {"t":"Schlag","d":"Ein einzelner Pulsschlag heißt Schlag oder Zählzeit (englisch beat).","n":3,"h":"kap03-rhythmus.html#g-schlag","f":["Schläge","Schlägen","Schlags","Zählzeit","Zählzeiten"]},
  "g-schleife": {"t":"Schleife","d":"Eine Schleife (englisch loop) ist eine kurze Akkordfolge, die sich über einen ganzen Abschnitt immer wieder wiederholt. In der Popmusik sind das meist vier Akkorde zu je einem Takt.","n":18,"h":"kap18-pop-progressionen.html#g-schleife","f":["Akkordschleife"]},
  "g-schlussgruppe": {"t":"Schlussgruppe","d":"Die Schlussgruppe beendet die Exposition einer Sonatenform. Sie bestätigt die neue Tonart mit mehreren Kadenzen.","n":41,"h":"kap41-sonate.html#g-schlussgruppe","f":["Schlussgruppe"]},
  "g-schlussstrich": {"t":"Schlussstrich","d":"Der Schlussstrich besteht aus einer dünnen und einer dicken Linie und beendet ein Stück.","n":4,"h":"kap04-takt.html#g-schlussstrich","f":["Schlussstrich","Schlussstrichs"]},
  "g-schwebung": {"t":"Schwebung","d":"Eine Schwebung ist ein schnelles Lauter-Leiser-Pulsieren. Sie entsteht, wenn zwei Töne oder Teiltöne nah beieinander, aber nicht genau aufeinander liegen.","n":5,"h":"kap05-intervalle.html#g-schwebung","f":["Schwebung","Schwebungen"]},
  "g-schwere-zeit": {"t":"schwere Zeit","d":"Schwere Zeiten sind die betonten Schläge eines Takts, etwa die 1 im 4/4-Takt. Auf ihnen landet das Gewicht der Musik.","n":4,"h":"kap04-takt.html#g-schwere-zeit","f":["schwere Zeit","schweren Zeit","schwere Zeiten","schweren Zeiten","schwerer Zeit"]},
  "g-sechzehntelnote": {"t":"Sechzehntelnote","d":"Die Sechzehntel (Sechzehntelnote) dauert halb so lang wie eine Achtel, vier Sechzehntel ergeben eine Viertel. Sie trägt zwei Fähnchen oder zwei Balken.","n":3,"h":"kap03-rhythmus.html#g-sechzehntelnote","f":["Sechzehntel","Sechzehnteln","Sechzehntelnote","Sechzehntelnoten"]},
  "g-seitenbewegung": {"t":"Seitenbewegung","d":"Bei Seitenbewegung bleibt eine Stimme liegen, während sich die andere bewegt.","n":33,"h":"kap33-stimmfuehrung.html#g-seitenbewegung","f":["Seitenbewegung"]},
  "g-seitensatz": {"t":"Seitensatz","d":"Der Seitensatz ist in der Sonatenform der Abschnitt mit dem zweiten Thema. In der Exposition steht er in der neuen Tonart (Dur: Dominante, Moll: Paralleltonart), in der Reprise in der Grundtonart.","n":41,"h":"kap41-sonate.html#g-seitensatz","f":["Seitensatz"]},
  "g-sekundakkord": {"t":"Sekundakkord","d":"Der Sekundakkord ist die dritte Umkehrung eines Septakkords, mit der Septime im Bass, bei G7 also f–g–h–d. Über dem Bass liegt eine Sekunde, die Bezifferung ist 2. Die Septime im Bass muss abwärts gehen.","n":15,"h":"kap15-septakkorde.html#g-sekundakkord","f":["Sekundakkord"]},
  "g-sekunde": {"t":"Sekunde","d":"Die Sekunde (lateinisch „die zweite“) ist das Intervall über zwei benachbarte Stammtöne, zum Beispiel c–d. Die kleine Sekunde hat einen Halbton, die große zwei.","n":5,"h":"kap05-intervalle.html#g-sekunde","f":["große Sekunde","großen Sekunde","kleine Sekunde","kleinen Sekunde","Sekundschritt","Sekundschritte","Sekundschritten"]},
  "g-septakkord": {"t":"Septakkord","d":"Ein Septakkord entsteht, wenn man auf einen Dreiklang eine weitere Terz schichtet. Er besteht aus Grundton, Terz, Quinte und Septime, zum Beispiel g–h–d–f.","n":15,"h":"kap15-septakkorde.html#g-septakkord","f":["Septakkord","Septakkorde","Septakkorden","Septakkords"]},
  "g-septime": {"t":"Septime","d":"Die Septime (lateinisch „die siebte“) ist das Intervall über sieben Stammtöne, zum Beispiel c–h. Die kleine Septime hat zehn Halbtöne, die große elf.","n":5,"h":"kap05-intervalle.html#g-septime","f":["Septime","Septimen"]},
  "g-sequenz": {"t":"Sequenz","d":"Eine Sequenz ist die Wiederholung eines musikalischen Abschnitts auf einer anderen Tonstufe.","n":26,"h":"kap26-sequenzen.html#g-sequenz","f":["Sequenz","Sequenzen"]},
  "g-sequenzglied": {"t":"Sequenzglied","d":"Ein Sequenzglied ist jede Wiederholung des Modells in einer Sequenz, versetzt auf eine andere Tonstufe. Meist folgen zwei bis vier Glieder in gleichen Abständen.","n":26,"h":"kap26-sequenzen.html#g-sequenzglied","f":["Sequenzglied","Sequenzglieder"]},
  "g-seufzermotiv": {"t":"Seufzermotiv","d":"Das Seufzermotiv ist eine Ausdrucksfigur des Barock aus zwei fallenden Tönen, meist einem Vorhalt mit Auflösung abwärts. Der erste Ton ist betont, der zweite leise.","n":19,"h":"kap19-nichtakkordtoene.html#g-seufzermotiv","f":["Seufzermotiv"]},
  "g-sextakkord": {"t":"Sextakkord","d":"Der Sextakkord ist die erste Umkehrung eines Dreiklangs, mit der Terz im Bass, zum Beispiel e–g–c. Über dem Bass liegen Terz und Sexte, daher der Name und die Bezifferung 6.","n":12,"h":"kap12-umkehrungen.html#g-sextakkord","f":["Sextakkord","Sextakkorde","Sextakkorden"]},
  "g-sexte": {"t":"Sexte","d":"Die Sexte (lateinisch „die sechste“) ist das Intervall über sechs Stammtöne, zum Beispiel c–a. Die kleine Sexte hat acht Halbtöne, die große neun.","n":5,"h":"kap05-intervalle.html#g-sexte","f":["Sexte","Sexten"]},
  "g-sforzato": {"t":"sforzato","d":"Sforzato oder sforzando (abgekürzt sf oder sfz) bedeutet: einen einzelnen Ton plötzlich stark betonen.","n":10,"h":"kap10-vortrag.html#g-sforzato","f":["sforzato","sforzando"]},
  "g-shell-voicing": {"t":"Shell-Voicing","d":"Ein Shell-Voicing besteht nur aus Grundton, Terz und Septime, in der Form 1–3–7 oder 1–7–3. Diese drei Töne zeigen die Funktion des Akkords vollständig.","n":29,"h":"kap29-voicings.html#g-shell-voicing","f":["Shell-Voicing","Shell-Voicings","Shell","Shells"]},
  "g-sinuston": {"t":"Sinuston","d":"Ein Sinuston ist ein reiner Ton ohne Obertöne, wie ihn ein Tongenerator erzeugt.","n":5,"h":"kap05-intervalle.html#g-sinuston","f":["Sinustönen","Sinustöne","Sinustons","Sinuston"]},
  "g-sixte-ajoutee": {"t":"Sixte ajoutée","d":"Die Sixte ajoutée („hinzugefügte Sexte“) ist ein Dreiklang mit zusätzlicher Sexte, etwa f–a–c–d. Rameau deutete den Klang als Subdominante. Er besteht aus denselben Tönen wie Dm7.","n":28,"h":"kap28-ii-v-i.html#g-sixte-ajoutee","f":["Sixte ajoutée"]},
  "g-skala": {"t":"Skala","d":"Skala (englisch scale) ist ein anderes Wort für Tonleiter: eine Auswahl von Tönen, die der Tonhöhe nach geordnet ist.","n":6,"h":"kap06-dur.html#g-skala","f":["Skala","Skalen"]},
  "g-slash-akkord": {"t":"Slash-Akkord","d":"Ein Slash-Akkord nennt hinter einem Schrägstrich den Basston eines Akkords. C/E bedeutet C-Dur mit e im Bass. Der Basston kann auch ein akkordfremder Ton sein, etwa bei C/D.","n":12,"h":"kap12-umkehrungen.html#g-slash-akkord","f":["Slash-Akkord","Slash-Akkorde","Slash-Akkorden"]},
  "g-so-what-voicing": {"t":"So-What-Voicing","d":"Das So-What-Voicing besteht aus drei reinen Quarten und einer großen Terz darüber, etwa e–a–d'–g'–h' über D-Dorisch. Es ist nach Miles Davis’ Stück „So What“ (1959) benannt.","n":29,"h":"kap29-voicings.html#g-so-what-voicing","f":["So-What-Voicing","So-What"]},
  "g-solokadenz": {"t":"Solokadenz","d":"Die Solokadenz ist die Stelle in einem Solokonzert, an der das Orchester schweigt und der Solist frei improvisiert oder eine ausgeschriebene virtuose Passage spielt.","n":16,"h":"kap16-kadenzen.html#g-solokadenz","f":["Solokadenz"]},
  "g-sonate": {"t":"Sonate","d":"Eine Sonate ist ein mehrsätziges Werk für ein oder zwei Instrumente, etwa eine Klaviersonate. Eine Sinfonie ist im Prinzip eine Sonate für Orchester, ein Streichquartett eine Sonate für vier Streicher.","n":41,"h":"kap41-sonate.html#g-sonate","f":["Sonate","Sonaten"]},
  "g-sonatenhauptsatzform": {"t":"Sonatenhauptsatzform","d":"Die Sonatenhauptsatzform (kurz Sonatenform) ist die wichtigste Großform der Klassik, meist im ersten Satz einer Sonate. Sie besteht aus Exposition, Durchführung und Reprise, oft mit Coda, und lebt vom Konflikt zweier Tonarten.","n":41,"h":"kap41-sonate.html#g-sonatenhauptsatzform","f":["Sonatenhauptsatzform","Sonatenform"]},
  "g-sonatenrondo": {"t":"Sonatenrondo","d":"Das Sonatenrondo verbindet Rondo und Sonatenform im Plan A B A C A B A. B steht beim ersten Mal in einer Nebentonart und kehrt später in der Grundtonart zurück, C ist oft eine Art Durchführung.","n":40,"h":"kap40-liedformen.html#g-sonatenrondo","f":["Sonatenrondo"]},
  "g-sonatensatz": {"t":"Sonatensatz","d":"Ein Sonatensatz ist ein einzelner Satz einer Sonate, einer Sinfonie oder eines Streichquartetts.","n":41,"h":"kap41-sonate.html#g-sonatensatz","f":["Sonatensatz"]},
  "g-sostenuto": {"t":"Sostenuto","d":"Das Sostenuto (Tonhaltepedal) ist das mittlere Pedal des Flügels. Es hält nur die Dämpfer der Tasten oben, die im Moment des Tretens gedrückt sind, alle anderen Töne werden normal gedämpft.","n":45,"h":"kap45-pedal.html#g-sostenuto","f":["Sostenuto","Tonhaltepedal"]},
  "g-spacing": {"t":"Spacing-Effekt","d":"Der Spacing-Effekt beschreibt, dass verteiltes Lernen besser wirkt als Lernen am Stück. Dieselbe Übemenge, auf mehrere Einheiten oder Tage verteilt, bleibt besser im Gedächtnis.","n":47,"h":"kap47-ueben.html#g-spacing","f":["Spacing-Effekt","Spacing-Effekts","verteiltes Üben","verteilten Üben","verteiltes Lernen","verteilten Lernens"]},
  "g-staccatissimo": {"t":"staccatissimo","d":"Staccatissimo (Zeichen: Keil über oder unter der Note) heißt sehr kurz und scharf, so kurz wie möglich.","n":10,"h":"kap10-vortrag.html#g-staccatissimo","f":["staccatissimo"]},
  "g-staccato": {"t":"staccato","d":"Staccato (Zeichen: Punkt über oder unter der Note) heißt kurz, abgestoßen. Der Ton beginnt pünktlich und endet früher, etwa nach der halben Notenlänge.","n":10,"h":"kap10-vortrag.html#g-staccato","f":["staccato","Staccati","Staccatos"]},
  "g-stammton": {"t":"Stammton","d":"Stammtöne sind die sieben Töne der weißen Tasten: c, d, e, f, g, a, h. Die Töne der schwarzen Tasten werden nach ihnen benannt.","n":1,"h":"kap01-klaviatur.html#g-stammton","f":["Stammton","Stammtöne","Stammtönen","Stammtons"]},
  "g-stellvertreter": {"t":"Stellvertreter","d":"Ein Stellvertreter ist ein Akkord, der die Funktion eines anderen übernimmt, weil er zwei Töne mit ihm teilt. So vertritt vi die Tonika, ii die Subdominante und vii° die Dominante.","n":14,"h":"kap14-funktionen.html#g-stellvertreter","f":["Stellvertreter"]},
  "g-stimme": {"t":"Stimme","d":"Eine Stimme ist eine einzelne melodische Linie in einem mehrstimmigen Satz. Am Klavier spielt eine Person oft mehrere Stimmen gleichzeitig.","n":33,"h":"kap33-stimmfuehrung.html#g-stimme","f":[]},
  "g-stimmfuehrung": {"t":"Stimmführung","d":"Stimmführung ist die Lehre davon, wie sich die einzelnen Stimmen eines mehrstimmigen Satzes von Klang zu Klang bewegen sollen.","n":33,"h":"kap33-stimmfuehrung.html#g-stimmfuehrung","f":["Stimmführung"]},
  "g-stimmkreuzung": {"t":"Stimmkreuzung","d":"Bei einer Stimmkreuzung gerät eine tiefere Stimme über eine höhere, etwa der Alt über den Sopran. Im klassischen Satz wird sie vermieden, weil das Ohr sonst die Linien verwechselt.","n":33,"h":"kap33-stimmfuehrung.html#g-stimmkreuzung","f":["Stimmkreuzung","Stimmkreuzungen"]},
  "g-stimmton": {"t":"Stimmton","d":"Der Stimmton (auch Kammerton) ist der Ton, nach dem Orchester und Instrumente gestimmt werden. Heute ist das das a' mit 440 Hz.","n":1,"h":"kap01-klaviatur.html#g-stimmton","f":["Stimmton","Stimmtons","Kammerton","Kammertons"]},
  "g-stopp-methode": {"t":"Stopp-Methode","d":"Bei der Stopp-Methode spielst du eine Stelle in Gruppen und hältst nach jeder Gruppe kurz an, um die nächste Handposition vorzubereiten. Danach werden die Gruppen schrittweise verbunden.","n":47,"h":"kap47-ueben.html#g-stopp-methode","f":["Stopp-Methode"]},
  "g-strebetendenz": {"t":"Strebetendenz","d":"Die Strebetendenz ist der Zug eines Tons zu einem benachbarten stabilen Ton, etwa der Zug des Leittons h einen Halbton aufwärts zur Tonika c.","n":6,"h":"kap06-dur.html#g-strebetendenz","f":["Strebetendenz","Strebetendenzen"]},
  "g-strenger-satz": {"t":"strenger Satz","d":"Der strenge Satz ist die Satzweise nach den festen Regeln der Vokalpolyphonie des 16. Jahrhunderts, wie sie die Gattungslehre von Johann Joseph Fux vermittelt.","n":33,"h":"kap33-stimmfuehrung.html#g-strenger-satz","f":["strengen Satzes","strenger Satz","strengen Satz","strenge Satz"]},
  "g-stride": {"t":"Stride","d":"Stride ist ein Begleitmuster im 4/4-Takt, bei dem die linke Hand den Bass auf 1 und 3 und den Akkord auf 2 und 4 spielt. Sie springt dabei ständig zwischen tiefer und mittlerer Lage.","n":46,"h":"kap46-begleitmuster.html#g-stride","f":["Stride"]},
  "g-strophe": {"t":"Strophe","d":"Die Strophe (englisch verse) ist der erzählende Teil eines Songs. Jede Strophe hat einen neuen Text bei gleicher Musik.","n":42,"h":"kap42-songformen.html#g-strophe","f":["Strophe","Strophen"]},
  "g-strophe-refrain": {"t":"Strophe-Refrain-Form","d":"In der Strophe-Refrain-Form wechseln sich Strophen mit wechselndem Text und ein gleichbleibender Refrain ab, oft ergänzt durch Pre-Chorus und Bridge. Die meisten Popsongs seit den 1960er-Jahren sind so gebaut.","n":42,"h":"kap42-songformen.html#g-strophe-refrain","f":["Strophe-Refrain-Form"]},
  "g-strophenlied": {"t":"Strophenlied","d":"Ein Strophenlied wiederholt dieselbe Musik mehrmals mit neuem Text, Form A A A. So sind die meisten Volks- und Kirchenlieder gebaut.","n":42,"h":"kap42-songformen.html#g-strophenlied","f":["Strophenlied"]},
  "g-studierzeichen": {"t":"Studierzeichen","d":"Studierzeichen sind Buchstaben oder Kürzel am Rand der Noten, die Formteile markieren, etwa A1, A2, B, A3 in Jazz-Leadsheets.","n":42,"h":"kap42-songformen.html#g-studierzeichen","f":["Studierzeichen"]},
  "g-stufe": {"t":"Stufe","d":"Stufen sind die Töne einer Tonleiter, vom Grundton aus durchgezählt: Der Grundton ist die 1. Stufe, der nächste Ton die 2. Stufe und so weiter.","n":6,"h":"kap06-dur.html#g-stufe","f":["Stufe","Stufen"]},
  "g-stufe-akkord": {"t":"Stufe (Akkord)","d":"Die Stufe eines Akkords gibt an, auf welchem Ton der Tonleiter sein Grundton steht. Man schreibt sie mit römischen Ziffern, groß für Dur und klein für Moll, etwa I, ii, V, vii°.","n":13,"h":"kap13-stufen.html#g-stufe-akkord","f":["Stufe","Stufen","Stufenziffern"]},
  "g-stufentheorie": {"t":"Stufentheorie","d":"Die Stufentheorie benennt Akkorde nach der Tonleiterstufe ihres Grundtons und schreibt sie mit römischen Ziffern (I, ii, V …). Sie ist international der Standard, auch in Jazz und Pop.","n":13,"h":"kap13-stufen.html#g-stufentheorie","f":["Stufentheorie"]},
  "g-stummer-fingerwechsel": {"t":"stummer Fingerwechsel","d":"Beim stummen Fingerwechsel tauschst du auf einer gedrückten Taste lautlos den Finger. So bleibt der Ton gebunden, und der erste Finger wird für den nächsten Ton frei.","n":37,"h":"kap37-choralsatz.html#g-stummer-fingerwechsel","f":["stummer Fingerwechsel","stumme Fingerwechsel","stummen Fingerwechsel"]},
  "g-subdominante": {"t":"Subdominante","d":"Die Subdominante ist die 4. Stufe einer Tonart, eine Quinte unter der Tonika. In C-Dur ist das f.","n":6,"h":"kap06-dur.html#g-subdominante","f":["Subdominante","Subdominanten"]},
  "g-subdominante-funktion": {"t":"Subdominante (Funktion)","d":"Die Subdominante (IV, Funktionssymbol S) ist der Akkord auf der 4. Stufe. Sie führt von der Tonika weg, ist weniger gespannt als die Dominante und bereitet sie oft vor.","n":14,"h":"kap14-funktionen.html#g-subdominante-funktion","f":["Subdominante"]},
  "g-subdominanttonart": {"t":"Subdominanttonart","d":"Die Subdominanttonart ist die Tonart, deren Tonika die vierte Stufe der Ausgangstonart ist, zu C-Dur also F-Dur. Ihre Vorzeichnung hat ein ♭ mehr oder ein ♯ weniger.","n":22,"h":"kap22-modulation.html#g-subdominanttonart","f":["Subdominanttonart","Subdominanttonarten"]},
  "g-subkontraoktave": {"t":"Subkontraoktave","d":"Die Subkontraoktave ist der Oktavbereich unter der Kontraoktave. Auf dem Klavier enthält sie nur die drei tiefsten Tasten A2, B2 und H2 (wissenschaftlich A0 bis B0).","n":1,"h":"kap01-klaviatur.html#g-subkontraoktave","f":["Subkontraoktave"]},
  "g-submediante": {"t":"Submediante","d":"Die Submediante ist die 6. Stufe einer Tonleiter, eine Terz unter der Tonika. In Dur ist sie der Grundton der parallelen Molltonart, in C-Dur a.","n":6,"h":"kap06-dur.html#g-submediante","f":["Submediante"]},
  "g-supertonika": {"t":"Supertonika","d":"Die Supertonika ist die 2. Stufe einer Tonleiter, die Stufe direkt über der Tonika. In C-Dur ist das d.","n":6,"h":"kap06-dur.html#g-supertonika","f":["Supertonika"]},
  "g-sus-akkord": {"t":"sus-Akkord","d":"Bei einem sus-Akkord wird die Terz durch die Quarte (sus4) oder die Sekunde (sus2) ersetzt.","n":17,"h":"kap17-leadsheets.html#g-sus-akkord","f":["sus-Akkord","sus-Akkorde","sus-Akkorden"]},
  "g-swing": {"t":"Swing","d":"Swing (auch Shuffle) heißt, Achtelpaare ungleich zu spielen: die erste länger, die zweite kürzer, ungefähr im Verhältnis einer Triole aus Viertel und Achtel. Notiert werden sie als normale Achtel.","n":3,"h":"kap03-rhythmus.html#g-swing","f":["Swing","Shuffle","geswingt","geswingte","geswingten"]},
  "g-symmetrische-skala": {"t":"symmetrische Skala","d":"Eine symmetrische Skala wiederholt ihr Intervallmuster innerhalb der Oktave mehrmals, die Ganztonleiter etwa alle zwei, die Halbton-Ganzton-Skala alle drei Halbtöne. Deshalb gibt es von ihnen nur wenige verschiedene.","n":30,"h":"kap30-akkordskalen.html#g-symmetrische-skala","f":["symmetrische Skala","symmetrische Skalen","symmetrischen Skala","symmetrischen Skalen"]},
  "g-synkope": {"t":"Synkope","d":"Eine Synkope entsteht, wenn ein Ton auf einer leichten Zählzeit beginnt und über die folgende schwere Zählzeit hinweg klingt.","n":4,"h":"kap04-takt.html#g-synkope","f":["Synkope","Synkopen","synkopiert","synkopierte","synkopierten"]},
  "g-synkopisches-pedal": {"t":"synkopisches Pedal","d":"Beim synkopischen Pedal (Legato-Pedal) hebst du das Pedal erst, nachdem du den neuen Akkord angeschlagen hast, und trittst sofort wieder. So verbinden sich zwei Harmonien lückenlos, ohne sich zu vermischen.","n":45,"h":"kap45-pedal.html#g-synkopisches-pedal","f":["synkopisches Pedal","synkopische Pedal","synkopischen Pedal","synkopischen Pedals","synkopischem Pedal","Legato-Pedal","nachgetretenes Pedal"]},
  "g-syntonisches-komma": {"t":"syntonisches Komma","d":"Das syntonische Komma ist der Unterschied zwischen der großen Terz aus vier reinen Quinten (407,8 Cent) und der reinen großen Terz 5/4 (386,3 Cent). Es beträgt 81/80 ≈ 21,5 Cent.","n":7,"h":"kap07-quintenzirkel.html#g-syntonisches-komma","f":["syntonisches Komma","syntonische Komma","syntonischen Komma","syntonischen Kommas"]},
  "g-takt": {"t":"Takt","d":"Ein Takt ist eine Einheit aus einem schweren Schlag und den folgenden leichteren bis zum nächsten schweren.","n":4,"h":"kap04-takt.html#g-takt","f":["Takt","Takte","Takten","Takts","Taktes"]},
  "g-taktangabe": {"t":"Taktangabe","d":"Die Taktangabe am Anfang eines Stücks sieht aus wie ein Bruch. Die obere Zahl gibt an, wie viele Schläge ein Takt hat, die untere, welcher Notenwert einem Schlag entspricht: 3/4 heißt drei Viertel pro Takt.","n":4,"h":"kap04-takt.html#g-taktangabe","f":["Taktangabe","Taktangaben"]},
  "g-taktart": {"t":"Taktart","d":"Die Taktart gibt an, wie viele Schläge ein Takt hat und wie sie gewichtet sind, etwa 3/4 oder 6/8. Sie steht als Taktangabe am Anfang des Stücks.","n":3,"h":"kap03-rhythmus.html#g-taktart","f":["Taktarten","Taktart"]},
  "g-taktstrich": {"t":"Taktstrich","d":"Ein Taktstrich ist ein senkrechter Strich durch das Notensystem, der zwei Takte voneinander trennt. Der erste Schlag nach dem Taktstrich ist der schwerste.","n":4,"h":"kap04-takt.html#g-taktstrich","f":["Taktstrich","Taktstriche","Taktstrichen","Taktstrichs"]},
  "g-oberton": {"t":"Teilton","d":"Teiltöne (auch Obertöne oder Partialtöne) sind die leiseren Töne mit doppelter, dreifacher, vierfacher … Frequenz, die in jedem Klavierton mitschwingen. Sie verschmelzen zur Klangfarbe, ihre Folge heißt Obertonreihe.","n":5,"h":"kap05-intervalle.html#g-oberton","f":["Teilton","Teiltöne","Teiltönen","Teiltons","Oberton","Obertöne","Obertönen","Obertons","Partialton","Partialtöne","Obertonreihe","Obertonreihen"]},
  "g-tempo": {"t":"Tempo","d":"Das Tempo gibt an, wie schnell die Schläge aufeinanderfolgen. Man gibt es in Schlägen pro Minute (BPM) oder mit italienischen Bezeichnungen wie Andante oder Allegro an.","n":4,"h":"kap04-takt.html#g-tempo","f":["Tempo","Tempos","Tempi"]},
  "g-tempo-primo": {"t":"Tempo primo","d":"Tempo primo ist eine Spielanweisung: zurück zum Anfangstempo des Stücks.","n":4,"h":"kap04-takt.html#g-tempo-primo","f":["Tempo primo"]},
  "g-tendenzton": {"t":"Tendenzton","d":"Ein Tendenzton ist ein Ton mit starker Strebung in eine bestimmte Richtung, etwa der Leitton aufwärts zum Grundton oder die Septime eines Septakkords abwärts. Tendenztöne werden nicht verdoppelt.","n":37,"h":"kap37-choralsatz.html#g-tendenzton","f":["Tendenzton","Tendenztöne","Tendenztönen"]},
  "g-tenorklausel": {"t":"Tenorklausel","d":"Die Tenorklausel ist die Schlussformel des Tenors, der Schritt von der 2. zur 1. Stufe einen Ganzton abwärts, in C-Dur d → c.","n":16,"h":"kap16-kadenzen.html#g-tenorklausel","f":["Tenorklausel"]},
  "g-tenorschluessel": {"t":"Tenorschlüssel","d":"Der Tenorschlüssel ist ein C-Schlüssel auf der vierten Linie. Das c' steht dann auf dieser Linie. Cello, Fagott und Posaune benutzen ihn in hoher Lage.","n":2,"h":"kap02-notenschrift.html#g-tenorschluessel","f":["Tenorschlüssel","Tenorschlüssels"]},
  "g-tenuto": {"t":"tenuto","d":"Tenuto (Zeichen: waagrechter Strich über oder unter der Note) heißt: den Ton in voller Länge aushalten und leicht gewichten.","n":10,"h":"kap10-vortrag.html#g-tenuto","f":["tenuto"]},
  "g-terz": {"t":"Terz","d":"Die Terz (lateinisch „die dritte“) ist das Intervall über drei Stammtöne, zum Beispiel c–e. Die kleine Terz hat drei Halbtöne, die große vier.","n":5,"h":"kap05-intervalle.html#g-terz","f":["Terz","Terzen"]},
  "g-terzfall": {"t":"Terzfall","d":"Beim Terzfall fallen die Akkordgrundtöne jeweils um eine Terz, etwa C – Am – F – Dm. Benachbarte Akkorde teilen dabei zwei von drei Tönen, der Wechsel klingt sehr weich.","n":26,"h":"kap26-sequenzen.html#g-terzfall","f":["Terzfall"]},
  "g-terzlage": {"t":"Terzlage","d":"Bei der Terzlage liegt die Terz eines Akkords als oberster Ton, C-Dur etwa als g'–c''–e''.","n":12,"h":"kap12-umkehrungen.html#g-terzlage","f":["Terzlage"]},
  "g-terzquartakkord": {"t":"Terzquartakkord","d":"Der Terzquartakkord ist die zweite Umkehrung eines Septakkords, mit der Quinte im Bass, bei G7 also d–f–g–h. Über dem Bass liegen Terz und Quarte, die Bezifferung ist 4/3.","n":15,"h":"kap15-septakkorde.html#g-terzquartakkord","f":["Terzquartakkord"]},
  "g-terzschichtung": {"t":"Terzschichtung","d":"Terzschichtung ist das Bauprinzip, Akkorde aus übereinandergelegten Terzen zu bilden. c–e–g besteht zum Beispiel aus den Terzen c–e und e–g.","n":11,"h":"kap11-dreiklaenge.html#g-terzschichtung","f":["Terzschichtung"]},
  "g-terzverwandt": {"t":"terzverwandt","d":"Terzverwandt heißen Akkorde, deren Grundtöne eine Terz auseinanderliegen, etwa C und Am. Leitereigene terzverwandte Dreiklänge haben zwei gemeinsame Töne und können einander deshalb oft vertreten.","n":32,"h":"kap32-reharmonisierung.html#g-terzverwandt","f":["terzverwandt","terzverwandte","terzverwandten"]},
  "g-tetrachord": {"t":"Tetrachord","d":"Ein Tetrachord (griechisch „vier Saiten“) ist eine Gruppe aus vier Tönen im Rahmen einer Quarte. Die Dur-Tonleiter besteht aus zwei gleichen Tetrachorden (Ganz – Ganz – Halb), getrennt durch einen Ganzton.","n":6,"h":"kap06-dur.html#g-tetrachord","f":["Tetrachord","Tetrachorde","Tetrachorden","Tetrachords"]},
  "g-tiefengrenze": {"t":"Tiefengrenze","d":"Die Tiefengrenze eines Intervalls ist die Lage, unterhalb derer es rau und dumpf klingt. Kleine Intervalle brauchen Höhe, große wie Oktave und Quinte vertragen Tiefe.","n":46,"h":"kap46-begleitmuster.html#g-tiefengrenze","f":["Tiefengrenze","Tiefengrenzen"]},
  "g-tin-pan-alley": {"t":"Tin Pan Alley","d":"Tin Pan Alley nannte man das New Yorker Musikverlagsviertel von etwa 1900 bis 1950. Der Name steht auch für die Songs, die dort verlegt wurden, meist in 32-taktiger AABA-Form.","n":42,"h":"kap42-songformen.html#g-tin-pan-alley","f":["Tin Pan Alley"]},
  "g-tonale-ambivalenz": {"t":"tonale Ambivalenz","d":"Tonale Ambivalenz heißt, dass eine Akkordfolge zwischen zwei Tonarten schwankt, etwa zwischen C-Dur und a-Moll, weil offenbleibt, welcher Akkord als Tonika gehört wird.","n":18,"h":"kap18-pop-progressionen.html#g-tonale-ambivalenz","f":["tonale Ambivalenz","tonalen Ambivalenz"]},
  "g-tonale-antwort": {"t":"tonale Antwort","d":"Eine tonale Antwort ist eine Fugenantwort, die am Anfang leicht verändert wird, damit sie in der Grundtonart verankert bleibt. Wo das Thema die Dominante hat, steht in der Antwort die Tonika und umgekehrt.","n":38,"h":"kap38-fuge.html#g-tonale-antwort","f":["tonale Antwort","tonalen Antwort"]},
  "g-tonale-anziehung": {"t":"tonale Anziehung","d":"Tonale Anziehung ist nach Fred Lerdahl die Kraft, mit der ein unstabiler Ton zu einem stabileren strebt. Sie ist umso größer, je stabiler der Zielton im Vergleich zum Ausgangston ist und je näher er liegt.","n":14,"h":"kap14-funktionen.html#g-tonale-anziehung","f":["tonale Anziehung","tonalen Anziehung"]},
  "g-tonale-hierarchie": {"t":"tonale Hierarchie","d":"Die tonale Hierarchie ist die Rangfolge, in der Hörer die Töne einer Tonart als passend empfinden. Grundton, Quinte und Terz stehen oben, die übrigen Tonleitertöne darunter, tonleiterfremde Töne ganz unten.","n":32,"h":"kap32-reharmonisierung.html#g-tonale-hierarchie","f":["tonale Hierarchie","tonalen Hierarchie"]},
  "g-tonale-sequenz": {"t":"tonale Sequenz","d":"Bei einer tonalen Sequenz wird das Modell nur mit Tönen der Tonleiter versetzt. Die Intervalle können sich dabei leicht ändern, etwa c – d – e zu d – e – f.","n":26,"h":"kap26-sequenzen.html#g-tonale-sequenz","f":["tonale Sequenz","tonalen Sequenz","tonale Sequenzen","tonalen Sequenzen"]},
  "g-tonalitaet": {"t":"Tonalität","d":"Tonalität bezeichnet Musik, die auf ein Zentrum bezogen ist, die Tonika. Töne und Akkorde werden nach ihrer Beziehung zu diesem Zentrum gehört, wie im Dur-Moll-System.","n":5,"h":"kap05-intervalle.html#g-tonalitaet","f":["tonalen Harmonik","tonale Harmonik","tonalen Musik","tonaler Musik","tonale Musik","Tonalität"]},
  "g-tonart": {"t":"Tonart","d":"Eine Tonart bezeichnet den Tonvorrat eines Stücks und seinen Grundton als Zentrum. Ein Stück in G-Dur benutzt vor allem die Töne der G-Dur-Tonleiter und endet meist auf G.","n":7,"h":"kap07-quintenzirkel.html#g-tonart","f":["Tonart","Tonarten"]},
  "g-tonartenplan": {"t":"Tonartenplan","d":"Der Tonartenplan beschreibt, in welchen Tonarten die Teile eines Stücks stehen und in welcher Reihenfolge sie wechseln, etwa von der Grundtonart zur Dominante und zurück.","n":40,"h":"kap40-liedformen.html#g-tonartenplan","f":["Tonartenplan"]},
  "g-tonhierarchie": {"t":"Tonhierarchie","d":"Die Tonhierarchie ist die Rangfolge, in der das Ohr die Töne einer Tonart als passenden Abschluss empfindet: zuerst die Tonika, dann Quinte und Terz, dann die übrigen Töne der Tonleiter, zuletzt die Töne außerhalb.","n":6,"h":"kap06-dur.html#g-tonhierarchie","f":["Tonhierarchie","Tonhierarchien"]},
  "g-tonika": {"t":"Tonika","d":"Die Tonika ist die 1. Stufe einer Tonart, ihr Grundton und Ruhepunkt, das „Zuhause“. In C-Dur ist das c.","n":6,"h":"kap06-dur.html#g-tonika","f":["Tonika"]},
  "g-tonika-funktion": {"t":"Tonika (Funktion)","d":"Die Tonika (I, Funktionssymbol T) ist der Akkord auf der 1. Stufe und das Zentrum der Tonart. Auf ihr kommt die Musik zur Ruhe.","n":14,"h":"kap14-funktionen.html#g-tonika-funktion","f":["Tonika"]},
  "g-tonikalisierung": {"t":"Tonikalisierung","d":"Tonikalisierung heißt der Vorgang, bei dem ein Akkord der Tonart kurz wie eine Tonika wirkt, meist weil ihm seine eigene Dominante vorangeht. Die Tonart wechselt dabei nicht.","n":21,"h":"kap21-zwischendominanten.html#g-tonikalisierung","f":["Tonikalisierung","tonikalisiert","tonikalisieren"]},
  "g-tonikaorgelpunkt": {"t":"Tonikaorgelpunkt","d":"Ein Tonikaorgelpunkt ist ein Orgelpunkt auf dem Grundton der Tonart, oft am Anfang oder Ende eines Stücks. Er wirkt beruhigend, wie ein festes Fundament.","n":26,"h":"kap26-sequenzen.html#g-tonikaorgelpunkt","f":["Tonikaorgelpunkt","Tonikaorgelpunkte"]},
  "g-tonleiter": {"t":"Tonleiter","d":"Eine Tonleiter (auch Skala, englisch scale) ist eine Auswahl von Tönen, die der Tonhöhe nach geordnet ist.","n":6,"h":"kap06-dur.html#g-tonleiter","f":["Tonleiter","Tonleitern"]},
  "g-tonverschmelzung": {"t":"Tonverschmelzung","d":"Tonverschmelzung beschreibt, wie stark zwei gleichzeitig klingende Töne beim Hören zu einem einzigen Klangeindruck verschmelzen. Am stärksten verschmilzt die Oktave, dann die Quinte, deutlich schwächer verschmelzen Terzen und Sexten.","n":33,"h":"kap33-stimmfuehrung.html#g-tonverschmelzung","f":["Tonverschmelzung"]},
  "g-tonvorrat": {"t":"Tonvorrat","d":"Der Tonvorrat ist die Menge der Töne, die ein Stück oder eine Tonart benutzt, in beliebiger Reihenfolge. Eine Tonleiter schreibt diesen Vorrat nur übersichtlich geordnet auf.","n":6,"h":"kap06-dur.html#g-tonvorrat","f":["Tonvorrat","Tonvorrats"]},
  "g-transponieren": {"t":"Transponieren","d":"Transponieren heißt, ein Stück oder eine Akkordfolge in eine andere Tonart zu übertragen. Alle Töne und Akkorde werden dabei um dasselbe Intervall verschoben.","n":49,"h":"kap49-nach-gehoer.html#g-transponieren","f":["Transponieren","transponiert","transponiere","transponierten","Transposition"]},
  "g-tredezime": {"t":"Tredezime","d":"Die Tredezime ist eine Sexte plus eine Oktave, zum Beispiel c'–a''. Die kleine Tredezime hat 20 Halbtöne, die große 21. In Akkordsymbolen erscheint sie als 13.","n":5,"h":"kap05-intervalle.html#g-tredezime","f":["Tredezime","Tredezimen"]},
  "g-tremolo": {"t":"Tremolo","d":"Ein Tremolo ist der schnelle, wiederholte Wechsel zwischen zwei Tönen oder Akkorden. Am Klavier spielt man es meist aus einer Drehbewegung des Unterarms.","n":43,"h":"kap43-technik.html#g-tremolo","f":["Tremolos","Tremolo","Tremoli"]},
  "g-tresillo": {"t":"Tresillo","d":"Der Tresillo ist ein Rhythmus, der die acht Achtel eines 4/4-Takts in Gruppen von 3 + 3 + 2 teilt. Er stammt aus afro-kubanischer Musik und steckt in unzähligen Popsongs.","n":46,"h":"kap46-begleitmuster.html#g-tresillo","f":["Tresillo","Tresillos"]},
  "g-triller": {"t":"Triller","d":"Ein Triller (Zeichen tr) ist ein schneller Wechsel zwischen Hauptnote und oberer Nebennote über die ganze Notenlänge.","n":10,"h":"kap10-vortrag.html#g-triller","f":["Triller"]},
  "g-trio": {"t":"Trio","d":"Das Trio ist der kontrastierende Mittelteil in der Satzfolge Menuett – Trio – Menuett. Nach ihm wird das Menuett noch einmal gespielt (da capo).","n":40,"h":"kap40-liedformen.html#g-trio","f":["Trio"]},
  "g-triole": {"t":"Triole","d":"Eine Triole besteht aus drei Noten, die zusammen so lang sind wie zwei Noten desselben Werts. So lässt sich ein Schlag in drei gleiche Teile teilen.","n":3,"h":"kap03-rhythmus.html#g-triole","f":["Triole","Triolen"]},
  "g-triosonate": {"t":"Triosonate","d":"Die Triosonate ist eine Werkform des Barock für zwei Melodieinstrumente und Generalbass.","n":36,"h":"kap36-kontrapunkt-3.html#g-triosonate","f":["Triosonaten","Triosonate"]},
  "g-tritonus": {"t":"Tritonus","d":"Der Tritonus teilt die Oktave genau in der Mitte und heißt so, weil er aus drei Ganztönen besteht (c–d–e–fis).","n":5,"h":"kap05-intervalle.html#g-tritonus","f":["Tritonus","Tritoni"]},
  "g-tritonus-griff": {"t":"Tritonus-Griff","d":"Beim Tritonus-Griff spielt die linke Hand den Grundton eines Dominantseptakkords, die rechte nur Terz und Septime, die zusammen einen Tritonus bilden. In Dominantketten gleitet die rechte Hand so in Halbtonschritten abwärts.","n":21,"h":"kap21-zwischendominanten.html#g-tritonus-griff","f":["Tritonus-Griff"]},
  "g-tritonussubstitution": {"t":"Tritonussubstitution","d":"Bei der Tritonussubstitution ersetzt man einen Dominantseptakkord durch den Dominantseptakkord, dessen Grundton einen Tritonus entfernt liegt, etwa G7 durch D♭7. Beide teilen den Tritonus aus Terz und Septime.","n":31,"h":"kap31-tritonus-substitution.html#g-tritonussubstitution","f":["Tritonussubstitution","Tritonussubstitutionen","Tritonussubstitut","Tritonussubstitute","Tritonussubstituts","subV"]},
  "g-truck-drivers-gear-change": {"t":"truck driver's gear change","d":"Truck driver's gear change („Gangwechsel des Lastwagenfahrers“) ist ein spöttischer englischer Name für die Rückung einen Halbton höher vor dem letzten Refrain eines Popsongs.","n":22,"h":"kap22-modulation.html#g-truck-drivers-gear-change","f":["truck driver's gear change"]},
  "g-trugschluss": {"t":"Trugschluss","d":"Beim Trugschluss führt die Dominante nicht zur I, sondern zur vi.","n":16,"h":"kap16-kadenzen.html#g-trugschluss","f":["Trugschluss"]},
  "g-turnaround": {"t":"Turnaround","d":"Ein Turnaround ist eine kurze Akkordfolge am Ende eines Formteils, die zurück zum Anfang führt. Die häufigste Form ist I–vi–ii–V, etwa Cmaj7–Am7–Dm7–G7.","n":28,"h":"kap28-ii-v-i.html#g-turnaround","f":["Turnaround","Turnarounds"]},
  "g-ueben": {"t":"Üben","d":"Üben heißt, gezielt an etwas zu arbeiten, das du noch nicht kannst.","n":47,"h":"kap47-ueben.html#g-ueben","f":[]},
  "g-ueberleitung": {"t":"Überleitung","d":"Die Überleitung ist in der Sonatenform der bewegte Abschnitt zwischen Hauptsatz und Seitensatz. In der Exposition moduliert sie in die neue Tonart, in der Reprise bleibt sie in der Grundtonart.","n":41,"h":"kap41-sonate.html#g-ueberleitung","f":["Überleitung"]},
  "g-uebermaessig": {"t":"übermäßig","d":"Ist ein Intervall um einen Halbton größer als die große bzw. reine Form, heißt es übermäßig.","n":5,"h":"kap05-intervalle.html#g-uebermaessig","f":["übermäßige Prime","übermäßige Sekunde","übermäßigen Sekunde","übermäßige Quarte","übermäßigen Quarte","übermäßige Quinte","übermäßigen Quinte","übermäßige Sexte","übermäßige Intervalle","übermäßigen Intervalle"]},
  "g-uebermaessiger-dreiklang": {"t":"übermäßiger Dreiklang","d":"Ein übermäßiger Dreiklang besteht aus zwei großen Terzen und hat deshalb eine übermäßige Quinte, zum Beispiel c–e–gis. Akkordsymbol C+ oder Caug.","n":11,"h":"kap11-dreiklaenge.html#g-uebermaessiger-dreiklang","f":["übermäßiger Dreiklang","übermäßigen Dreiklang","übermäßige Dreiklang","übermäßigen Dreiklangs","übermäßige Dreiklänge"]},
  "g-uebermaessiger-grosser-septakkord": {"t":"übermäßiger großer Septakkord","d":"Der übermäßige große Septakkord ist ein übermäßiger Dreiklang mit großer Septime, zum Beispiel c–e–gis–h (Cmaj7♯5). Er kommt vor allem im Jazz vor.","n":15,"h":"kap15-septakkorde.html#g-uebermaessiger-grosser-septakkord","f":["übermäßiger großer Septakkord","übermäßige große Septakkord"]},
  "g-uebermaessiger-sextakkord": {"t":"übermäßiger Sextakkord","d":"Ein übermäßiger Sextakkord hat die erniedrigte 6. Stufe im Bass und darüber die erhöhte 4. Stufe, in c-Moll as und fis. Beide Töne streben zum Grundton der Dominante. Es gibt eine italienische, deutsche und französische Form.","n":25,"h":"kap25-chromatische-akkorde.html#g-uebermaessiger-sextakkord","f":["übermäßiger Sextakkord","übermäßige Sextakkord","übermäßigen Sextakkord","übermäßige Sextakkorde","übermäßigen Sextakkorde","übermäßigen Sextakkorden","übermäßigen Sextakkords"]},
  "g-uebersatz": {"t":"Übersatz","d":"Beim Übersatz greift ein Finger, meist der dritte oder vierte, über den Daumen hinweg auf den nächsten Ton. So wechselt die Hand rechts abwärts und links aufwärts die Lage.","n":44,"h":"kap44-fingersaetze.html#g-uebersatz","f":["Übersatz","Fingerübersatz"]},
  "g-umdeutung": {"t":"Umdeutung","d":"Umdeutung heißt, dass ein Akkord im Verlauf eines Stücks eine neue Rolle erhält, etwa beim Modulieren. So wird a-Moll von der vi-Stufe in C-Dur zur ii-Stufe in G-Dur, in der Funktionstheorie von Tp zu Sp.","n":22,"h":"kap22-modulation.html#g-umdeutung","f":["Umdeutung"]},
  "g-umkehrung-akkord": {"t":"Umkehrung","d":"Bei einer Umkehrung liegt ein anderer Akkordton als der Grundton im Bass. Ein Dreiklang hat zwei Umkehrungen, mit der Terz im Bass (Sextakkord) und mit der Quinte im Bass (Quartsextakkord).","n":12,"h":"kap12-umkehrungen.html#g-umkehrung-akkord","f":["Umkehrung","Umkehrungen"]},
  "g-umkehrung": {"t":"Umkehrung (Intervall)","d":"Ein Intervall wird umgekehrt, wenn man den unteren Ton eine Oktave nach oben legt. Die Zahlen ergänzen sich dabei zu 9, groß wird klein, übermäßig wird vermindert, rein bleibt rein: Aus der großen Terz c–e wird die kleine Sexte e–c.","n":5,"h":"kap05-intervalle.html#g-umkehrung","f":["~Umkehrung","~Umkehrungen"]},
  "g-umkehrung-motiv": {"t":"Umkehrung (Motiv)","d":"Bei der Umkehrung eines Motivs wird jede Bewegung gespiegelt. Aufwärts wird abwärts und abwärts wird aufwärts, der Rhythmus bleibt gleich.","n":39,"h":"kap39-bausteine.html#g-umkehrung-motiv","f":["~Umkehrung","~Umkehrungen"]},
  "g-una-corda": {"t":"Una corda","d":"Una corda heißt das linke Pedal des Flügels. Es verschiebt die Mechanik, sodass die Hämmer weniger Saiten und eine weichere Stelle des Filzes treffen. Der Ton wird leiser und matter.","n":45,"h":"kap45-pedal.html#g-una-corda","f":["Una corda"]},
  "g-undezime": {"t":"Undezime","d":"Die Undezime ist eine Quarte plus eine Oktave, zum Beispiel c'–f''. Die reine Undezime hat 17 Halbtöne. In Akkordsymbolen erscheint sie als 11.","n":5,"h":"kap05-intervalle.html#g-undezime","f":["Undezime","Undezimen"]},
  "g-ungerader-takt": {"t":"ungerade Taktart","d":"Ungerade oder asymmetrische Taktarten wie 5/4 oder 7/8 lassen sich nicht in gleich große Gruppen teilen. Sie mischen Zweier- und Dreiergruppen, etwa 7/8 als 2 + 2 + 3 Achtel.","n":4,"h":"kap04-takt.html#g-ungerader-takt","f":["ungerade Taktart","ungerade Taktarten","ungeraden Taktarten","ungerade Takte","ungeraden Takte","asymmetrische Taktarten","asymmetrischen Taktarten"]},
  "g-untertonreihe": {"t":"Untertonreihe","d":"Die Untertonreihe ist eine gedachte Spiegelung der Obertonreihe nach unten. Hugo Riemann leitete daraus den Mollakkord ab, als Eigenschaft schwingender Saiten existiert sie aber nicht.","n":14,"h":"kap14-funktionen.html#g-untertonreihe","f":["Untertonreihe"]},
  "g-unvollkommene-konsonanz": {"t":"unvollkommene Konsonanz","d":"Unvollkommene Konsonanzen sind große und kleine Terz sowie große und kleine Sexte. Sie klingen wohl und voll, verschmelzen aber weniger als die vollkommenen Konsonanzen.","n":5,"h":"kap05-intervalle.html#g-unvollkommene-konsonanz","f":["unvollkommene Konsonanz","unvollkommene Konsonanzen","unvollkommenen Konsonanz","unvollkommenen Konsonanzen"]},
  "g-unvollkommener-ganzschluss": {"t":"unvollkommener Ganzschluss","d":"Bei einem unvollkommenen Ganzschluss V–I liegt im Schlussakkord die Terz oder Quinte oben, oder einer der Akkorde steht in Umkehrung. Er wirkt schwächer als der vollkommene Ganzschluss.","n":16,"h":"kap16-kadenzen.html#g-unvollkommener-ganzschluss","f":["unvollkommener Ganzschluss","unvollkommenen Ganzschluss"]},
  "g-upper-structure": {"t":"Upper Structure","d":"Eine Upper Structure ist ein einfacher Dur- oder Molldreiklang, den die rechte Hand über der Shell einer Dominante spielt. Zusammen ergibt das einen erweiterten oder alterierten Akkord, etwa E♭-Dur über G7 als G7♯9♭13.","n":31,"h":"kap31-tritonus-substitution.html#g-upper-structure","f":["Upper Structure","Upper Structures","Upper-Structure-Dreiklang","Upper-Structure-Dreiklänge"]},
  "g-urtext": {"t":"Urtext","d":"Eine Urtextausgabe gibt den Notentext so wieder, wie ihn der Komponist hinterlassen hat, ohne Zusätze eines Herausgebers.","n":10,"h":"kap10-vortrag.html#g-urtext","f":["Urtextausgaben","Urtextausgabe","Urtext"]},
  "g-vamp": {"t":"Vamp","d":"Ein Vamp ist eine kurze, ständig wiederholte Akkordfolge, oft nur zwei Akkorde im Wechsel, über der man spielt oder improvisiert. In modaler Musik etabliert er Grundton und Modus.","n":24,"h":"kap24-modi.html#g-vamp","f":["Vamp","Vamps"]},
  "g-varianttonart": {"t":"Varianttonart","d":"Varianttonarten sind Dur und Moll mit demselben Grundton, etwa C-Dur und c-Moll (englisch parallel keys). Die Moll-Variante hat drei ♭ mehr oder drei ♯ weniger als die Dur-Tonart.","n":8,"h":"kap08-moll.html#g-varianttonart","f":["Varianttonart","Varianttonarten"]},
  "g-variation": {"t":"Variation","d":"Bei der Variation wird ein Thema mehrfach hintereinander gespielt, jedes Mal verändert.","n":40,"h":"kap40-liedformen.html#g-variation","f":["Variation","Variationen"]},
  "g-verdeckte-parallele": {"t":"verdeckte Parallele","d":"Eine verdeckte Parallele entsteht, wenn zwei Stimmen in Gleichbewegung (gleiche Richtung) in eine Quinte oder Oktave hineingehen.","n":33,"h":"kap33-stimmfuehrung.html#g-verdeckte-parallele","f":["verdeckte Parallele","verdeckten Parallele","verdeckte Parallelen","verdeckten Parallelen","verdeckte Oktave","verdeckte Quinten","verdeckten Quinten"]},
  "g-verdopplung": {"t":"Verdopplung","d":"Verdopplung heißt, dass ein Akkordton in zwei Stimmen gleichzeitig erklingt, meist im Oktavabstand. Sie ist nötig, wenn ein Dreiklang mit vier oder mehr Stimmen gespielt wird.","n":12,"h":"kap12-umkehrungen.html#g-verdopplung","f":[]},
  "g-verkuerzte-zwischendominante": {"t":"verkürzte Zwischendominante","d":"Eine verkürzte Zwischendominante ist ein verminderter Septakkord auf dem Leitton eines Zielakkords, der dessen Zwischendominante ersetzt. In C-Dur führt etwa C♯°7 (cis – e – g – b) statt A7 zu d-Moll.","n":21,"h":"kap21-zwischendominanten.html#g-verkuerzte-zwischendominante","f":["verkürzte Zwischendominante","verkürzte Zwischendominanten","verkürzten Zwischendominante","verkürzten Zwischendominanten"]},
  "g-vermindert": {"t":"vermindert","d":"Vermindert heißt ein Intervall, das um einen Halbton kleiner ist als die kleine bzw. reine Form, zum Beispiel die verminderte Quinte c–ges.","n":5,"h":"kap05-intervalle.html#g-vermindert","f":["verminderte Terz","verminderte Quarte","verminderte Quinte","verminderten Quinte","verminderte Septime","verminderten Septime","verminderte Oktave","verminderte Intervalle","verminderten Intervalle"]},
  "g-verminderter-dreiklang": {"t":"verminderter Dreiklang","d":"Ein verminderter Dreiklang besteht aus zwei kleinen Terzen und hat deshalb eine verminderte Quinte, zum Beispiel c–es–ges. Akkordsymbol C° oder Cdim.","n":11,"h":"kap11-dreiklaenge.html#g-verminderter-dreiklang","f":["verminderter Dreiklang","verminderten Dreiklang","verminderte Dreiklang"]},
  "g-verminderter-septakkord": {"t":"verminderter Septakkord","d":"Der verminderte Septakkord besteht aus drei kleinen Terzen, zum Beispiel C°7 = c–es–ges–heses. Er teilt die Oktave in vier gleiche Teile, deshalb kann jeder seiner Töne als Grundton gedeutet werden.","n":15,"h":"kap15-septakkorde.html#g-verminderter-septakkord","f":["verminderter Septakkord","verminderte Septakkord","verminderten Septakkord","verminderte Septakkorde","verminderten Septakkords","verminderten Septakkorde"]},
  "g-versetzungszeichen": {"t":"Versetzungszeichen","d":"Versetzungszeichen (englisch accidentals) sind ♯, ♭ und ♮ vor einzelnen Noten. Sie gelten bis zum Ende des Takts für alle Noten in derselben Höhe.","n":2,"h":"kap02-notenschrift.html#g-versetzungszeichen","f":["Versetzungszeichen","Versetzungszeichens"]},
  "g-verwandte-ii": {"t":"verwandte II","d":"Die verwandte II ist der m7-Akkord, der zu einer Dominante steht wie die II zur V, etwa Dm7 zu G7 oder A♭m7 zu D♭7. Schiebt man ihn vor die Dominante ein, entsteht eine II–V.","n":31,"h":"kap31-tritonus-substitution.html#g-verwandte-ii","f":["verwandte II","verwandten II","eingeschobene II","eingeschobenen II"]},
  "g-verzierung": {"t":"Verzierung","d":"Verzierungen (auch Ornamente) sind kleine Tonfolgen um eine Hauptnote, die in den Noten nur mit einem Kürzel stehen.","n":10,"h":"kap10-vortrag.html#g-verzierung","f":["Verzierung","Verzierungen","Ornament","Ornamente"]},
  "g-vierklang": {"t":"Vierklang","d":"Ein Vierklang ist ein Akkord aus vier verschiedenen Tönen, meist ein Septakkord.","n":15,"h":"kap15-septakkorde.html#g-vierklang","f":["Vierklängen","Vierklänge","Vierklangs","Vierklang"]},
  "g-vierstimmiger-satz": {"t":"vierstimmiger Satz","d":"Der vierstimmige Satz ist eine Satzweise mit den vier Stimmen eines gemischten Chors, also Sopran, Alt, Tenor und Bass. Er ist das Grundmodell der klassischen Harmonielehre.","n":37,"h":"kap37-choralsatz.html#g-vierstimmiger-satz","f":["vierstimmiger Satz","vierstimmige Satz","vierstimmigen Satz","vierstimmigen Satzes","vierstimmige Sätze"]},
  "g-viertelnote": {"t":"Viertelnote","d":"Die Viertel (Viertelnote) dauert ein Viertel einer Ganzen, also halb so lang wie eine Halbe. Sie wird als gefüllte Note mit Hals geschrieben.","n":3,"h":"kap03-rhythmus.html#g-viertelnote","f":["Viertelnote","Viertelnoten"]},
  "g-violinschluessel": {"t":"Violinschlüssel","d":"Der Violinschlüssel (englisch treble clef) ist ein verschnörkeltes G. Er legt fest, dass auf der zweiten Linie des Notensystems das g' steht.","n":2,"h":"kap02-notenschrift.html#g-violinschluessel","f":["Violinschlüssel","Violinschlüssels"]},
  "g-virtuelle-tonhoehe": {"t":"virtuelle Tonhöhe","d":"Die virtuelle Tonhöhe ist der gefühlte Grundton, den das Gehör aus den Teiltönen eines Zusammenklangs ermittelt. Das Modell stammt von dem Hörforscher Ernst Terhardt.","n":11,"h":"kap11-dreiklaenge.html#g-virtuelle-tonhoehe","f":["virtuelle Tonhöhe","virtuellen Tonhöhe"]},
  "g-vivace": {"t":"Vivace","d":"Vivace (italienisch „lebendig“) ist eine schnelle Tempobezeichnung, ungefähr ♩ = 156–176.","n":4,"h":"kap04-takt.html#g-vivace","f":["Vivace"]},
  "g-voicing": {"t":"Voicing","d":"Ein Voicing (englisch, etwa „Stimmverteilung“) legt fest, welche Töne eines Akkords gespielt werden, in welcher Oktave sie liegen und welcher Ton oben und unten steht.","n":29,"h":"kap29-voicings.html#g-voicing","f":["Voicing","Voicings"]},
  "g-vollkommener-ganzschluss": {"t":"vollkommener Ganzschluss","d":"Bei einem vollkommenen Ganzschluss V–I stehen beide Akkorde in Grundstellung, und im Schlussakkord liegt der Grundton in der Oberstimme. Er ist der stärkste Schluss.","n":16,"h":"kap16-kadenzen.html#g-vollkommener-ganzschluss","f":["vollkommener Ganzschluss"]},
  "g-vollstaendige-kadenz": {"t":"vollständige Kadenz","d":"Die vollständige Kadenz ist die Folge I–IV–V–I, in der Funktionstheorie T–S–D–T. Sie führt von der Ruhe über die Subdominante zur Spannung der Dominante und zurück zur Tonika.","n":16,"h":"kap16-kadenzen.html#g-vollstaendige-kadenz","f":["vollständige Kadenz"]},
  "g-volta": {"t":"Volta (Klammer)","d":"Volten oder Klammern stehen über dem Ende eines wiederholten Abschnitts. Die 1. Klammer spielt man nur beim ersten Durchgang, beim zweiten springt man direkt in die 2. Klammer.","n":10,"h":"kap10-vortrag.html#g-volta","f":["Volta","Volten"]},
  "g-vordersatz": {"t":"Vordersatz","d":"Der Vordersatz ist die erste Hälfte einer Periode, meist Takt 1–4. Er stellt einen Gedanken vor und endet offen, meist mit einem Halbschluss.","n":39,"h":"kap39-bausteine.html#g-vordersatz","f":["Vordersatz","Vordersatzes"]},
  "g-vorhalt": {"t":"Vorhalt","d":"Ein Vorhalt entsteht, wenn ein Ton liegen bleibt, während der Akkord darunter wechselt, und dadurch zur Dissonanz wird. Danach löst er sich einen Schritt, meist abwärts, in einen Akkordton auf.","n":19,"h":"kap19-nichtakkordtoene.html#g-vorhalt","f":["Vorhalt","Vorhalte","Vorhalts","Vorhalten"]},
  "g-vorhaltskette": {"t":"Vorhaltskette","d":"Eine Vorhaltskette ist eine Folge von Vorhalten, in der jede Auflösung zugleich die Vorbereitung des nächsten Vorhalts ist. Typisch sind 7–6-Vorhalte über einem stufenweise fallenden Bass.","n":36,"h":"kap36-kontrapunkt-3.html#g-vorhaltskette","f":["Vorhaltskette","Vorhaltsketten"]},
  "g-vorpedal": {"t":"Vorpedal","d":"Beim Vorpedal trittst du das Pedal, bevor du den ersten Ton spielst.","n":45,"h":"kap45-pedal.html#g-vorpedal","f":["Vorpedal"]},
  "g-vorschlag": {"t":"Vorschlag","d":"Ein Vorschlag ist eine kleine Note vor der Hauptnote. Der lange Vorschlag (ohne Strich) nimmt sich Zeit von der Hauptnote und wird betont, der kurze (mit Schrägstrich, Acciaccatura) ist so kurz wie möglich.","n":10,"h":"kap10-vortrag.html#g-vorschlag","f":["Vorschlag","Vorschläge","Vorschlägen","Acciaccatura"]},
  "g-generalvorzeichen": {"t":"Vorzeichnung","d":"Die Vorzeichnung (auch Generalvorzeichen) sind die Vorzeichen der Tonart am Anfang jeder Notenzeile, direkt hinter dem Schlüssel. Sie gelten für die ganze Zeile und in allen Oktaven.","n":7,"h":"kap07-quintenzirkel.html#g-generalvorzeichen","f":["Vorzeichnung","Vorzeichnungen","Generalvorzeichen","Tonartvorzeichen"]},
  "g-warnungsvorzeichen": {"t":"Warnungsvorzeichen","d":"Ein Warnungsvorzeichen ist ein zusätzliches, oft eingeklammertes Vorzeichen, das nur daran erinnert, welcher Ton gilt. Es ändert nichts am Ton.","n":2,"h":"kap02-notenschrift.html#g-warnungsvorzeichen","f":["Warnungsvorzeichen","Warnungsvorzeichens"]},
  "g-wechselnote": {"t":"Wechselnote","d":"Eine Wechselnote (auch Nebennote) verlässt einen Akkordton im Schritt und kehrt sofort zu ihm zurück.","n":19,"h":"kap19-nichtakkordtoene.html#g-wechselnote","f":["Wechselnote","Wechselnoten","Nebennote","Nebennoten"]},
  "g-lage-weit": {"t":"weite Lage","d":"In weiter Lage sind die Oberstimmen eines Akkords gespreizt. Zwischen ihnen ist Platz für einen Akkordton, der nicht gespielt wird.","n":12,"h":"kap12-umkehrungen.html#g-lage-weit","f":["weite Lage","weiter Lage","weiten Lage","weite Lagen"]},
  "g-wiederholung": {"t":"Wiederholung","d":"Wiederholung heißt in der Motivverarbeitung, dass ein Motiv unverändert noch einmal erklingt. Sie schafft Wiedererkennen und Zusammenhang.","n":39,"h":"kap39-bausteine.html#g-wiederholung","f":[]},
  "g-wiederholungszeichen": {"t":"Wiederholungszeichen","d":"Wiederholungszeichen sind Doppelstriche mit zwei Punkten (𝄆 … 𝄇). Der Abschnitt dazwischen wird zweimal gespielt. Fehlt das öffnende Zeichen, geht die Wiederholung zurück zum Anfang.","n":10,"h":"kap10-vortrag.html#g-wiederholungszeichen","f":["Wiederholungszeichen","Wiederholungszeichens"]},
  "g-wissenschaftliche-schreibweise": {"t":"wissenschaftliche Schreibweise","d":"Die wissenschaftliche Schreibweise (englisch scientific pitch notation) verbindet den englischen Tonnamen mit einer Ziffer für die Oktave.","n":1,"h":"kap01-klaviatur.html#g-wissenschaftliche-schreibweise","f":["wissenschaftliche Schreibweise","wissenschaftlichen Schreibweise","wissenschaftlicher Schreibweise"]},
  "g-wohltemperiert": {"t":"wohltemperierte Stimmung","d":"Wohltemperierte Stimmungen, etwa von Andreas Werckmeister, machten ab dem späten 17. Jahrhundert alle Tonarten spielbar. Anders als die gleichstufige Stimmung gaben sie jeder Tonart eine leicht andere Färbung.","n":5,"h":"kap05-intervalle.html#g-wohltemperiert","f":["wohltemperierte Stimmung","wohltemperierten Stimmung","wohltemperierten Stimmungen","wohltemperiert","wohltemperierte","wohltemperierten"]},
  "g-zaesur": {"t":"Zäsur","d":"Eine Zäsur ist der Einschnitt am Ende einer Phrase. Dort entsteht ein kleiner Ruhepunkt, oft durch einen längeren Ton, eine Pause oder einen stabilen Akkord.","n":39,"h":"kap39-bausteine.html#g-zaesur","f":["Zäsur","Zäsuren"]},
  "g-zusammengesetzte-periode": {"t":"zusammengesetzte Periode","d":"Eine zusammengesetzte Periode besteht aus einem Vordersatz und einem Nachsatz von je acht Takten und umfasst daher 16 Takte.","n":39,"h":"kap39-bausteine.html#g-zusammengesetzte-periode","f":["zusammengesetzte Periode"]},
  "g-zusammengesetzter-takt": {"t":"zusammengesetzte Taktart","d":"In zusammengesetzten Taktarten wie 6/8, 9/8 und 12/8 wird jeder Schlag in drei Teile geteilt. Der Schlag ist eine punktierte Viertel mit drei Achteln, die obere Zahl zählt die Achtel.","n":4,"h":"kap04-takt.html#g-zusammengesetzter-takt","f":["zusammengesetzte Taktart","zusammengesetzte Taktarten","zusammengesetzten Taktarten","zusammengesetzte Takte","zusammengesetzten Takte"]},
  "g-zusammengesetzt": {"t":"zusammengesetztes Intervall","d":"Intervalle, die größer als eine Oktave sind, heißen zusammengesetzte Intervalle.","n":5,"h":"kap05-intervalle.html#g-zusammengesetzt","f":["zusammengesetztes Intervall","zusammengesetzte Intervalle","zusammengesetzten Intervalle","zusammengesetzten Intervallen","zusammengesetzte Sekunde"]},
  "g-schleifer": {"t":"Zusammenschlag","d":"Beim Zusammenschlag (engl. crushed note) schlägt man zwei benachbarte Töne wie es und e fast gleichzeitig an und lässt den unteren sofort los. So ahmt das Klavier eine Blue Note nach, die von unten hineinrutscht.","n":49,"h":"kap49-nach-gehoer.html#g-schleifer","f":["Zusammenschlag","crushed note"]},
  "g-zweite-praxis": {"t":"zweite Praxis","d":"Als zweite Praxis verteidigte Claudio Monteverdi um 1600 seinen Kompositionsstil, in dem der Ausdruck des Textes auch frei eingesetzte Dissonanzen rechtfertigt.","n":15,"h":"kap15-septakkorde.html#g-zweite-praxis","f":["zweite Praxis"]},
  "g-zweiteilige-liedform": {"t":"zweiteilige Liedform","d":"Die zweiteilige Liedform besteht aus zwei Teilen A und B, die oft jeweils wiederholt werden. Teil A moduliert meist zur Dominante oder Paralleltonart, Teil B führt zur Grundtonart zurück.","n":40,"h":"kap40-liedformen.html#g-zweiteilige-liedform","f":["zweiteilige Liedform","zweiteilige Form","zweiteiligen Form"]},
  "g-zweiunddreissigstelnote": {"t":"Zweiunddreißigstelnote","d":"Die Zweiunddreißigstel dauert halb so lang wie eine Sechzehntel, acht Zweiunddreißigstel ergeben eine Viertel. Sie trägt drei Fähnchen oder drei Balken.","n":3,"h":"kap03-rhythmus.html#g-zweiunddreissigstelnote","f":["Zweiunddreißigstel","Zweiunddreißigsteln"]},
  "g-zwischendominante": {"t":"Zwischendominante","d":"Eine Zwischendominante ist die Dominante eines anderen Akkords innerhalb der Tonart, in C-Dur etwa A7 vor d-Moll. Man schreibt sie als V/x, zum Beispiel V7/ii. Die Tonart wechselt dabei nicht.","n":21,"h":"kap21-zwischendominanten.html#g-zwischendominante","f":["Zwischendominante","Zwischendominanten"]},
  "g-zwischenspiel": {"t":"Zwischenspiel","d":"Ein Zwischenspiel ist ein Abschnitt einer Fuge ohne vollständiges Thema, oft eine Sequenz aus Themenmotiven. Zwischenspiele führen häufig in neue Tonarten.","n":38,"h":"kap38-fuge.html#g-zwischenspiel","f":["Zwischenspiele","Zwischenspielen"]}
};
